INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C1','soc',5,1,'u3',1,'법의 뜻과 특징 — 법은 사회 구성원이 반드시 지켜야 하는 강제성이 있는 규범(규범 = 행동하거나 판단할 때 따라야 할 기준) · 특징 ① 모두가 반드시 지켜야 하는 강제성 ② 지키지 않으면 국가로부터 제재(법이나 규정을 어겼을 때 국가가 하는 처벌이나 금지)를 받음 · 법에는 그 나라의 문화와 가치가 담기기도 함(책가방 무게 제한·공공장소 껌 금지·반려견 산책)',ARRAY['6사 정치 — 법의 의미와 역할, 법을 지키는 태도(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C2','soc',5,1,'u3',1,'법과 약속·규칙의 차이 — 일상생활의 약속이나 규칙(실내에서 걷기·휴대 전화 꺼 두기·시설물 훼손하지 않기)은 양심에 따라 자율적으로 지키고 어겨도 국가의 제재가 없음 · 지키지 않으면 다툼·갈등과 피해가 생겨 반드시 지키도록 어기면 벌을 주는 기준을 만든 것이 법 · 안전에 큰 위협이 되거나(안전벨트·횡단보도 신호) 남에게 큰 피해를 주는 일(물건값 안 내기)은 법이 필요하고, 심각하게 위험하지 않은 일(웃어른 인사·쓰레기 줍기·형제 말다툼)은 양심에 맡김',ARRAY['6사 정치 — 법의 의미와 역할, 법을 지키는 태도(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C3','soc',5,1,'u3',2,'학교생활 속 법 — 「도로 교통법」으로 안전하게 등교하고, 「초·중등 교육법」에 따라 교육을 받고, 「학교 급식법」으로 영양가 있고 안전한 급식을 먹고, 「어린이 놀이 시설 안전 관리법」으로 안전한 놀이터를 이용함 · 학교에서 보내는 하루에도 여러 법이 함께함',ARRAY['6사 정치 — 법의 의미와 역할, 법을 지키는 태도(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C4','soc',5,1,'u3',2,'일상생활 속 법과 생활에 주는 영향 — 창작물(「저작권법」)·순찰(「경찰관 직무 집행법」)·건물 안전(「건축법」)·자연 보호(「자연환경 보전법」)·소방(「소방 기본법」)·소비자(「소비자 기본법」)·먹을거리(「식품 안전 기본법」)·진료(「의료법」)처럼 법은 생활 곳곳에 적용되고 우리 사회의 많은 일이 법에 따라 이루어짐 · 법마다 정해 둔 까닭(건강하고 안전한 식생활 보장, 생태계 보호, 위급할 때 생명과 재산 보호)이 있음 · 조사는 알고 싶은 주제 정하기 → 생활 법령 누리집에서 찾기 → 내용 살펴보고 내 말로 정리하기 · 특별 사법 경찰은 세금·교통·환경 같은 전문 분야에서 법이 지켜지는지 살핌',ARRAY['6사 정치 — 법의 의미와 역할, 법을 지키는 태도(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C5','soc',5,1,'u3',3,'법이 필요한 까닭 — 폐수를 함부로 버리면 하천이 오염되고 악취가 나 생물과 사람이 함께 피해를 입듯, 문제가 생겼을 때 법은 사람들 사이의 갈등이나 다툼을 해결하는 기준이 됨 · 법이 없다고 떠올려 보면 법이 평소에 하던 일이 보임 · 법은 누구에게나 똑같이 적용되어야 기준이 될 수 있음',ARRAY['6사 정치 — 법의 의미와 역할, 법을 지키는 태도(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C6','soc',5,1,'u3',3,'법의 역할 — 개인의 권리 보호: 개인 사이의 다툼을 법에 따른 재판으로 해결하고 피해를 보상받게 함(동의 없이 사진을 올려 초상권을 침해당한 사람이 손해 배상을 청구해 법원이 판결) · 사고나 화재 위험에서 개인의 생명이나 재산을 보호 · 생년월일·전화번호 같은 개인 정보를 보호(개인 안심 번호)',ARRAY['6사 정치 — 법의 의미와 역할, 법을 지키는 태도(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C7','soc',5,1,'u3',3,'법의 역할 — 사회 질서 유지: 사고나 범죄를 예방하고(어린이 보호 구역), 도로의 교통질서를 유지하고, 거리를 깨끗하고 쾌적하게 지키고(환경 보호), 공정한 경제 질서를 유지함 · 소방차 전용 구역에 주차하거나 진입을 막으면 과태료를 내게 하는 법처럼 모두의 안전을 위한 질서를 지킴 → 그래서 우리가 안전하게 살아갈 수 있음',ARRAY['6사 정치 — 법의 의미와 역할, 법을 지키는 태도(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C8','soc',5,1,'u3',4,'인권의 뜻과 특징 — 인권은 사람이 태어나면서 당연히 가지는 권리로 사람이라면 누구나 누려야 할 기본적인 권리 · 태어나는 순간부터 주어지고, 성별·나이·국적 등에 관계없이 차별 없이 평등하게 주어지며, 다른 사람이 힘이나 권력으로 함부로 빼앗을 수 없음(노력의 대가가 아님) · 교육받기, 먹고 쉬기, 아플 때 치료받기처럼 일상에서 누리고, 인간다운 삶을 위해 중요함',ARRAY['6사 정치 — 헌법에 담긴 인권, 인권 침해 해결과 인권 보호 실천(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C9','soc',5,1,'u3',4,'헌법과 헌법에 담긴 인권 보장 — 헌법은 우리나라의 최고법으로 국가 운영 원칙과 국민의 자유와 권리, 인권을 보장하는 내용을 담음 · 국가 권력이 개인의 기본적인 인권을 함부로 침해할 수 없도록 하려고 헌법에 정해 둠 · 헌법이 보장하는 모습 다섯: 차별받지 않고 동등하게 대우받기 · 국가의 간섭 없이 자유롭게 생각하고 행동하기(살고 싶은 곳으로 이사) · 국가의 정치 의사 형성 과정에 참여하기(선거권으로 투표) · 권리가 침해되었을 때 국가에 요구하기(재판 받기) · 더 나은 삶을 국가에 요구하기(교육받기·인간다운 생활) — 국가 법령 정보 누리집으로 찾아보고 소책자로 정리',ARRAY['6사 정치 — 헌법에 담긴 인권, 인권 침해 해결과 인권 보호 실천(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C10','soc',5,1,'u3',5,'법을 지키는 태도 — 인터넷에 남을 비방하는 글은 명예를 훼손하고, 보행 신호를 안 지키면 나와 남의 안전을 위협하고, 허락 없이 친구 사진을 올리면 초상권을 침해함 → 바르고 고운 말, 파란불에 건너기, 먼저 허락 받기 · 법을 지키는 까닭은 상이나 벌이 아니라 남에게 피해를 주지 않고, 나와 남의 권리를 보호하고, 모두가 조화롭고 안정된 삶을 누리기 위해서',ARRAY['6사 정치 — 법의 의미와 역할, 법을 지키는 태도(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C11','soc',5,1,'u3',5,'인권을 존중하는 태도와 캠페인 — 인권은 모두가 누려야 할 권리이고 나의 권리가 소중한 만큼 다른 사람의 권리도 소중함(생각이 다른 친구 말 들어 주기, 싫어하는 별명 부르지 않기) · 점검표는 「예」 개수가 아니라 잘 못 지킨 부분을 함께 이야기하고 방법을 찾는 데 씀 · 캠페인은 중요성을 알리고 함께 참여하도록 하는 활동 — 해시태그를 붙여 올리고 공감과 댓글로 소통하며 실천 의지를 다짐',ARRAY['6사 정치 — 헌법에 담긴 인권, 인권 침해 해결과 인권 보호 실천(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C12','soc',5,1,'u3',6,'인권 침해의 뜻과 사례 — 인권 침해는 성별·나이·신체적 특징·종교·국적 등으로 인권을 보호받지 못하는 것 · 편견이나 차별, 폭력, 사생활 침해, 시설 부족, 안전 문제 등으로 일어남(경사로가 없어 식당에 못 들어감, 단체 대화방의 사이버 폭력, 공사장 소음, 외국인이라는 까닭의 월급 차별, 고층 건물로 햇빛을 못 받음, 악취와 매연, 일기장 몰래 보기) · 잘못한 것이 없는데도 생활에서 어려움을 겪고 인간다운 삶을 누리지 못하게 됨 · 미디어로도 만나고, 내 행동 속에도 있는지 살펴봄',ARRAY['6사 정치 — 헌법에 담긴 인권, 인권 침해 해결과 인권 보호 실천(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C13','soc',5,1,'u3',7,'인권 침해 문제의 원인과 해결 — 원인을 파악하면 해결 방법을 찾을 수 있음(청소년의 국회 도서관 이용 제한 — 업무를 방해할 것이라는 편견, 전문 서적을 안 읽을 것이라는 생각이 원인 → 캠페인·국가 인권 위원회 의견서 → 청소년 자유 이용제) · 토의: 문제 고르기 → 원인 정리 → 각자 해결 방법 두 가지 → 이유나 근거와 함께 발표 → 자신이 낸 방법을 뺀 것에 별표 셋·둘·하나로 모둠 의견 정하기 · 보호 자세: 스스로 인권을 지키려 노력, 주변의 침해를 찾아 해결에 관심, 침해당한 사람의 어려움에 공감하고 입장 존중',ARRAY['6사 정치 — 헌법에 담긴 인권, 인권 침해 해결과 인권 보호 실천(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C14','soc',5,1,'u3',8,'우리 사회의 인권 보호 노력 — 주변: 사회적으로 보호가 필요한 사람을 배려하는 시설이나 물건(어린이 전용 세면대·노인을 위한 큰 글자 도서·임산부 배려석·옐로 카펫·무장애 통합 놀이터) · 학교: 인권 보호 시설(경사로·계단 점자 블록·음성 지원 안내판·복도 안전 손잡이), 인권 교육, 선생님·학생·학부모가 함께 만드는 규칙 · 국가: 법과 제도, 사회 보장 제도(질병·실업·장애·노령·빈곤으로 어려운 사람을 돕고 인간다운 생활 보장), 공공 편의 시설, 인권 교육과 캠페인, 국가 인권 위원회(침해 사례 조사·도움·정책 제안)',ARRAY['6사 정치 — 헌법에 담긴 인권, 인권 침해 해결과 인권 보호 실천(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C15','soc',5,1,'u3',9,'생활 속 인권 보호 실천 — 인권을 존중하는 말, 이웃 돕기 봉사, 인권 보호 캠페인 참여처럼 내가 할 수 있는 일을 찾아 작은 일부터 실천함(큰일을 기다리지 않음) · 실천 방법: 인권 사진전(침해와 보호가 대조되게 찍고 보호 방법과 찍은 까닭을 적음)·포스터 전시회·손수 제작물 전시회 — 모둠이 하나 골라 차례대로(찍어야 붙일 수 있음) 하고 마지막엔 게시하거나 누리집에 올려 알림 · 사회 복지사는 보호가 필요한 사람이 사회에 잘 적응하도록 도움',ARRAY['6사 정치 — 헌법에 담긴 인권, 인권 침해 해결과 인권 보호 실천(초안)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u3-C16','soc',5,1,'u3',10,'장애물 없는 생활 환경 인증 제도와 시설 제안 — 어린이·노인·장애인·임산부 등 모든 사람이 건물이나 시설을 이용할 때 불편을 느끼지 않도록 설계하고 관리하는 것을 평가하는 제도(법에 근거) · 학교 시설을 내부 시설(출입문·복도·계단·경사로·승강기)·위생 시설(화장실 출입문·변기·세면대)·안내 시설(안내판·점자 블록)·기타 시설(급식실·강당·장애인 전용 주차 구역)로 나눠 빠짐없이 살핌 · 제안 한 줄은 어디에·무엇을·무엇을 위해가 모두 있어야 하고 내기 전까지 고쳐 쓸 수 있음 · 학급이 함께 나누고 실현된 모습을 그림으로 나타냄(사회+미술)',ARRAY['6사 정치 — 헌법에 담긴 인권, 인권 침해 해결과 인권 보호 실천(초안)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X01','soc',5,'u3',ARRAY['SO5-1-u3-C1','SO5-1-u3-C2']::text[],'법과 일상의 약속·규칙을 헷갈린다(법도 양심에 맡기는 것이라고, 약속을 어기면 나라가 벌을 준다고 여긴다)','법 — 반드시·국가의 제재 · 약속 — 양심·스스로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X02','soc',5,'u3',ARRAY['SO5-1-u3-C1']::text[],'제재와 규범의 뜻을 잘못 안다(제재를 칭찬이나 친구끼리의 꾸중으로, 규범을 아무 말이나로 여긴다)','제재 = 국가가 하는 처벌이나 금지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X03','soc',5,'u3',ARRAY['SO5-1-u3-C2']::text[],'법이 필요한 상황과 그렇지 않은 상황을 가르지 못한다(안전벨트 안 매기를 양심 문제로, 형제 말다툼을 법으로 다스릴 일로 여긴다)','크게 다치거나 큰 피해 → 법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X04','soc',5,'u3',ARRAY['SO5-1-u3-C3','SO5-1-u3-C4']::text[],'법은 어른이나 먼 곳의 일이라 내 하루와는 관계없다고 여긴다','등굣길·급식·놀이터에도 법이 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X05','soc',5,'u3',ARRAY['SO5-1-u3-C3','SO5-1-u3-C4']::text[],'법과 그 법이 지켜 주는 것을 맞지 않게 짝짓는다','법이 무엇을 지켜 주는지 생각해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X06','soc',5,'u3',ARRAY['SO5-1-u3-C4']::text[],'법을 조사하는 차례나 방법을 잘못 안다(주제를 정하지 않고 찾는다, 찾은 글을 그대로 옮긴다)','주제 → 찾기 → 살펴보기 → 내 말로 정리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X07','soc',5,'u3',ARRAY['SO5-1-u3-C5']::text[],'법이 필요한 까닭을 잘못 안다(법은 많을수록 좋다고, 어른이 정했으니 따른다고, 외우기 쉬우라고 만든다고 여긴다)','갈등이나 다툼을 해결하는 기준') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X08','soc',5,'u3',ARRAY['SO5-1-u3-C6','SO5-1-u3-C7']::text[],'법의 두 역할(개인의 권리 보호·사회 질서 유지)을 바꾸어 짝짓는다','한 사람을 지켜 줌 · 모두의 질서를 지킴') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X09','soc',5,'u3',ARRAY['SO5-1-u3-C5']::text[],'법을 사람에 따라 다르게 적용해도 된다고 여긴다','누구에게나 똑같아야 기준이 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X10','soc',5,'u3',ARRAY['SO5-1-u3-C8']::text[],'인권을 조건이 있어야 받는 것으로 여긴다(어른이 되어야, 노력해야, 우리나라 사람이어야 누린다고, 남이 빼앗을 수 있다고)','태어나면서 · 누구나 · 빼앗을 수 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X11','soc',5,'u3',ARRAY['SO5-1-u3-C9']::text[],'헌법의 자리와 헌법에 인권을 정한 까닭을 잘못 안다(여러 법 가운데 하나일 뿐이라고, 국민이 지키라고만 정했다고 여긴다)','최고법 · 국가 권력이 함부로 침해하지 못하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X12','soc',5,'u3',ARRAY['SO5-1-u3-C9']::text[],'헌법이 보장하는 인권의 모습과 생활 장면을 맞지 않게 짝짓는다','동등한 대우·자유·정치 참여·국가에 요구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X13','soc',5,'u3',ARRAY['SO5-1-u3-C10']::text[],'법을 지키는 까닭을 상을 받거나 벌을 피하려는 것으로만 여긴다','피해 주지 않기·권리 보호·조화로운 삶') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X14','soc',5,'u3',ARRAY['SO5-1-u3-C11']::text[],'내 권리만 소중하다고, 힘이 세거나 나이가 많으면 권리가 더 크다고 여긴다','나의 권리가 소중한 만큼 남의 권리도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X15','soc',5,'u3',ARRAY['SO5-1-u3-C11']::text[],'점검표·캠페인의 목적을 점수나 순위로 여긴다(예 개수 세기, 공감 수 겨루기, 혼자 알고 있기)','함께 이야기하고 함께 참여하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X16','soc',5,'u3',ARRAY['SO5-1-u3-C12']::text[],'인권 침해의 뜻을 잘못 알아 존중하는 모습을 침해로, 침해를 그냥 불편한 일로 여긴다','~이라는 까닭으로 인권을 보호받지 못함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X17','soc',5,'u3',ARRAY['SO5-1-u3-C12']::text[],'인권 침해는 먼 곳이나 남의 일이라 내 주변과 내 행동은 살펴보지 않아도 된다고 여긴다','내 주변·내 행동부터 살펴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X18','soc',5,'u3',ARRAY['SO5-1-u3-C12']::text[],'침해 사례에서 어떤 권리를 보호받지 못했는지 잘못 짚는다','무엇 때문에 무엇을 못 누렸나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X19','soc',5,'u3',ARRAY['SO5-1-u3-C13']::text[],'인권 침해 문제의 원인을 살피지 않거나 원인을 피해를 입은 사람 탓으로 돌린다','원인은 편견과 잘못된 생각에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X20','soc',5,'u3',ARRAY['SO5-1-u3-C13']::text[],'해결 방법 토의의 차례와 규칙을 잘못 안다(내 방법에 별표 주기, 근거 없이 발표, 처음 나온 방법에 몰아주기)','근거와 함께 · 내 것은 빼고 별표') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X21','soc',5,'u3',ARRAY['SO5-1-u3-C14']::text[],'배려하는 시설·물건과 그 대상, 또는 노력의 주체(주변·학교·국가)를 맞지 않게 짝짓는다','누구를 위해 · 누가 하는 노력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X22','soc',5,'u3',ARRAY['SO5-1-u3-C14']::text[],'국가는 인권 침해를 개인에게 맡긴다고, 공공 편의 시설은 장애인만 쓴다고, 학교 규칙은 선생님 혼자 만든다고 여긴다','국가가 돕고 · 모두가 쓰고 · 함께 만들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X23','soc',5,'u3',ARRAY['SO5-1-u3-C15']::text[],'인권 보호 실천을 큰일이 생길 때까지 미루거나, 실천 활동의 차례와 마지막 알리기를 놓친다','작은 일부터 · 차례대로 · 많은 사람에게 알리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X24','soc',5,'u3',ARRAY['SO5-1-u3-C16']::text[],'장애물 없는 생활 환경 인증 제도를 장애인만을 위한 것으로, 또는 내가 불편한 곳만 살피면 되는 것으로 여긴다','모든 사람 · 여럿의 눈으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X25','soc',5,'u3',ARRAY['SO5-1-u3-C16']::text[],'학교 시설을 네 갈래로 잘못 나누거나, 제안에서 어디에·무엇을·무엇을 위해 가운데 하나를 빠뜨린다','내부·위생·안내·기타 · 세 칸 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u3-X26','soc',5,'u3',ARRAY['SO5-1-u3-C1','SO5-1-u3-C4','SO5-1-u3-C9']::text[],'법과 인권 공부를 법 이름이나 조항 번호를 외우는 것으로 여겨 생활 속 뜻과 쓰임을 놓친다','이름보다 무엇을 지켜 주는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_basic#1','soc',5,1,'u3','L01','g5_1_soc_u3_L01_basic','lesson_basic','SO5-1-u3-C1',1,'mc','auto','사회 구성원이 반드시 지켜야 하는 강제성이 있는 규범을 무엇이라고 하나요?',ARRAY['SO5-1-u3-X01','SO5-1-u3-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C1","difficulty":1,"kind":"mc","stem":"사회 구성원이 반드시 지켜야 하는 강제성이 있는 규범을 무엇이라고 하나요?","options":[{"t":"법","correct":true},{"t":"약속","mis":"SO5-1-u3-X01"},{"t":"예절","mis":"SO5-1-u3-X01"},{"t":"취미","mis":"SO5-1-u3-X02"}],"explanation":["모두가 반드시 지켜야 해요.","어기면 국가가 그냥 두지 않아요.","이것이 법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_basic#2','soc',5,1,'u3','L01','g5_1_soc_u3_L01_basic','lesson_basic','SO5-1-u3-C1',1,'sa','auto','행동하거나 판단할 때 따라야 할 기준을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u3-C1","difficulty":1,"kind":"sa","stem":"행동하거나 판단할 때 따라야 할 기준을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["규범"],"explanation":["법의 뜻 안에 들어 있는 낱말이에요.","따라야 할 기준이에요.","규범이에요."],"mis":"SO5-1-u3-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_basic#3','soc',5,1,'u3','L01','g5_1_soc_u3_L01_basic','lesson_basic','SO5-1-u3-C1',1,'mc','auto','법을 지키지 않았을 때 국가가 하는 처벌이나 금지를 무엇이라고 하나요?',ARRAY['SO5-1-u3-X02','SO5-1-u3-X01']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C1","difficulty":1,"kind":"mc","stem":"법을 지키지 않았을 때 국가가 하는 처벌이나 금지를 무엇이라고 하나요?","options":[{"t":"제재","correct":true},{"t":"칭찬","mis":"SO5-1-u3-X02"},{"t":"약속","mis":"SO5-1-u3-X01"},{"t":"양심","mis":"SO5-1-u3-X01"}],"explanation":["법을 어기면 그냥 넘어가지 않아요.","국가가 처벌하거나 금지해요.","이것을 제재라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_basic#4','soc',5,1,'u3','L01','g5_1_soc_u3_L01_basic','lesson_basic','SO5-1-u3-C2',1,'ox','auto','학교에서 실내에서 걷기, 영화관에서 휴대 전화 꺼 두기는 사람들이 양심에 따라 스스로 지키는 약속이에요.',ARRAY['SO5-1-u3-X01']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C2","difficulty":1,"kind":"ox","stem":"학교에서 실내에서 걷기, 영화관에서 휴대 전화 꺼 두기는 사람들이 양심에 따라 스스로 지키는 약속이에요.","answer":"O","reason_options":[{"t":"어겨도 국가가 벌을 주지는 않지만 모두를 위해 스스로 지키기 때문에","correct":true},{"t":"어기면 반드시 국가로부터 처벌을 받기 때문에","mis":"SO5-1-u3-X01"}],"mis":"SO5-1-u3-X01","explanation":["장소마다 약속이 있어요.","스스로 지켜요.","국가의 제재는 없어요."],"asset":{"type":"passage","lines":["학교 — 실내에서 걷고 바르고 고운 말을 쓴다.","영화관 — 휴대 전화를 꺼 두고 쓰레기는 가지고 나간다.","공원 — 시설물을 망가뜨리지 않고 소란을 피우지 않는다."],"title":"장소마다 지키는 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_basic#5','soc',5,1,'u3','L01','g5_1_soc_u3_L01_basic','lesson_basic','SO5-1-u3-C2',2,'mc','auto','법이 일상의 약속이나 규칙과 다른 점은 어느 것인가요?',ARRAY['SO5-1-u3-X01']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C2","difficulty":2,"kind":"mc","stem":"법이 일상의 약속이나 규칙과 다른 점은 어느 것인가요?","options":[{"t":"지키지 않으면 국가로부터 제재를 받는다","correct":true},{"t":"여럿이 함께 정한다","mis":"SO5-1-u3-X01"},{"t":"어릴 때부터 배운다","mis":"SO5-1-u3-X01"},{"t":"지키지 않아도 아무 일이 없다","mis":"SO5-1-u3-X01"}],"explanation":["약속은 양심에 따라 지켜요.","법은 반드시 지켜야 해요.","어기면 국가가 제재해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_basic#6','soc',5,1,'u3','L01','g5_1_soc_u3_L01_basic','lesson_basic','SO5-1-u3-C2',2,'mc','auto','여섯 가지 상황 가운데 법이 필요한 상황은 어느 것인가요?',ARRAY['SO5-1-u3-X03']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C2","difficulty":2,"kind":"mc","stem":"여섯 가지 상황 가운데 법이 필요한 상황은 어느 것인가요?","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"SO5-1-u3-X03"},{"t":"㉣","mis":"SO5-1-u3-X03"},{"t":"㉥","mis":"SO5-1-u3-X03"}],"explanation":["안전벨트를 안 매면 크게 다칠 수 있어요.","안전에 큰 위협이에요.","그래서 법으로 정했어요."],"asset":{"type":"passage","lines":["㉠ 차에 타서 안전벨트를 매지 않는다.","㉡ 웃어른을 만나도 인사하지 않는다.","㉢ 횡단보도에서 신호를 지키지 않는다.","㉣ 길에 떨어진 쓰레기를 줍지 않고 지나간다.","㉤ 가게에서 값을 내지 않고 물건을 가져간다.","㉥ 형제끼리 말다툼을 한다."],"title":"여섯 가지 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_basic#7','soc',5,1,'u3','L01','g5_1_soc_u3_L01_basic','lesson_basic','SO5-1-u3-C2',2,'mc','auto','여섯 가지 상황 가운데 법보다 양심에 따라 스스로 지키는 일에 가까운 것은 어느 것인가요?',ARRAY['SO5-1-u3-X03']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C2","difficulty":2,"kind":"mc","stem":"여섯 가지 상황 가운데 법보다 양심에 따라 스스로 지키는 일에 가까운 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"SO5-1-u3-X03"},{"t":"㉢","mis":"SO5-1-u3-X03"},{"t":"㉤","mis":"SO5-1-u3-X03"}],"explanation":["쓰레기를 줍는 것은 좋은 일이에요.","하지만 안 줍는다고 국가가 벌을 주지는 않아요.","양심에 맡기는 일이에요."],"asset":{"type":"passage","lines":["㉠ 차에 타서 안전벨트를 매지 않는다.","㉡ 웃어른을 만나도 인사하지 않는다.","㉢ 횡단보도에서 신호를 지키지 않는다.","㉣ 길에 떨어진 쓰레기를 줍지 않고 지나간다.","㉤ 가게에서 값을 내지 않고 물건을 가져간다.","㉥ 형제끼리 말다툼을 한다."],"title":"여섯 가지 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_basic#8','soc',5,1,'u3','L01','g5_1_soc_u3_L01_basic','lesson_basic','SO5-1-u3-C1',2,'mc','auto','세계의 여러 법에서 ㉯처럼 껌을 씹지 못하게 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X07']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C1","difficulty":2,"kind":"mc","stem":"세계의 여러 법에서 ㉯처럼 껌을 씹지 못하게 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"씹다 뱉은 껌으로 생긴 문제를 해결하려고","correct":true},{"t":"껌이 너무 비싸서","mis":"SO5-1-u3-X07"},{"t":"껌을 만들 수 없어서","mis":"SO5-1-u3-X07"},{"t":"그 나라 사람들이 껌을 싫어해서","mis":"SO5-1-u3-X07"}],"explanation":["아무 데나 뱉은 껌이 문제였어요.","그 문제를 풀려고 만들었어요.","법에는 그 나라의 문화와 가치가 담겨요."],"asset":{"type":"passage","lines":["㉮ 어느 주 — 어린이 책가방 무게를 제한한다.","㉯ 어느 나라 — 공공장소에서 껌을 씹지 못하게 한다.","㉰ 어느 도시 — 반려견을 하루 세 번 산책시키게 한다."],"title":"세계의 여러 법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_basic#9','soc',5,1,'u3','L01','g5_1_soc_u3_L01_basic','lesson_basic','SO5-1-u3-C1',2,'ox','auto','법은 나라마다 같아서 세계 어디에서나 똑같은 법을 지켜요.',ARRAY['SO5-1-u3-X26']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C1","difficulty":2,"kind":"ox","stem":"법은 나라마다 같아서 세계 어디에서나 똑같은 법을 지켜요.","answer":"X","reason_options":[{"t":"법에는 그 나라의 문화와 가치가 담겨 나라마다 다를 수 있기 때문에","correct":true},{"t":"법은 한 사람이 만들어 온 세계가 함께 쓰기 때문에","mis":"SO5-1-u3-X26"}],"mis":"SO5-1-u3-X26","explanation":["책가방·껌·반려견 법을 보았어요.","나라마다 다른 법이 있어요.","문화와 가치가 담겨요."],"asset":{"type":"passage","lines":["㉮ 어느 주 — 어린이 책가방 무게를 제한한다.","㉯ 어느 나라 — 공공장소에서 껌을 씹지 못하게 한다.","㉰ 어느 도시 — 반려견을 하루 세 번 산책시키게 한다."],"title":"세계의 여러 법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_basic#10','soc',5,1,'u3','L01','g5_1_soc_u3_L01_basic','lesson_basic','SO5-1-u3-C2',3,'error','auto','법과 약속을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X03','SO5-1-u3-X01']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C2","difficulty":3,"kind":"error","stem":"법과 약속을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「형제끼리 말다툼하면 나라에서 벌을 줘.」","correct":true,"mis_target":"SO5-1-u3-X03"},{"t":"서아 — 「값을 안 내고 물건을 가져가면 법의 제재를 받아.」","mis":"SO5-1-u3-X03"},{"t":"로운 — 「웃어른께 인사하는 건 스스로 지키는 예절이야.」","mis":"SO5-1-u3-X01"}],"explanation":["형제 말다툼은 위험한 일이 아니에요.","국가가 벌을 주지 않아요.","하준이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_challenge#1','soc',5,1,'u3','L01','g5_1_soc_u3_L01_challenge','lesson_challenge','SO5-1-u3-C2',2,'match','auto','여섯 가지 상황을 법이 필요한 것과 양심에 맡기는 것으로 나누어 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u3-C2","difficulty":2,"kind":"match","stem":"여섯 가지 상황을 법이 필요한 것과 양심에 맡기는 것으로 나누어 이으세요.","pairs":[{"l":"㉠ 안전벨트","r":"법 — 크게 다칠 수 있어요"},{"l":"㉤ 물건값","r":"법 — 큰 피해를 줘요"},{"l":"㉡ 웃어른 인사","r":"양심 — 위험하지 않아요"},{"l":"㉥ 형제 말다툼","r":"양심 — 제재가 없어요"}],"mis":"SO5-1-u3-X03","explanation":["안전과 큰 피해는 법이에요.","위험하지 않은 일은 양심이에요.","두 서랍으로 나누어요."],"asset":{"type":"passage","lines":["㉠ 차에 타서 안전벨트를 매지 않는다.","㉡ 웃어른을 만나도 인사하지 않는다.","㉢ 횡단보도에서 신호를 지키지 않는다.","㉣ 길에 떨어진 쓰레기를 줍지 않고 지나간다.","㉤ 가게에서 값을 내지 않고 물건을 가져간다.","㉥ 형제끼리 말다툼을 한다."],"title":"여섯 가지 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_challenge#2','soc',5,1,'u3','L01','g5_1_soc_u3_L01_challenge','lesson_challenge','SO5-1-u3-C1',2,'sa','auto','법은 사회 구성원이 반드시 지켜야 하는 무엇이 있는 규범인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u3-C1","difficulty":2,"kind":"sa","stem":"법은 사회 구성원이 반드시 지켜야 하는 무엇이 있는 규범인가요? 세 글자로 쓰세요.","answer":["강제성"],"explanation":["누구나 반드시 지켜야 해요.","스스로 고르는 것이 아니에요.","강제성이 있어요."],"mis":"SO5-1-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_challenge#3','soc',5,1,'u3','L01','g5_1_soc_u3_L01_challenge','lesson_challenge','SO5-1-u3-C2',3,'mc','auto','자전거를 탄 채 횡단보도를 건너면 안 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X03','SO5-1-u3-X01']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C2","difficulty":3,"kind":"mc","stem":"자전거를 탄 채 횡단보도를 건너면 안 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"건너는 사람을 다치게 할 수 있고 법으로도 정해져 있기 때문에","correct":true},{"t":"자전거가 빨리 낡기 때문에","mis":"SO5-1-u3-X03"},{"t":"횡단보도가 좁아지기 때문에","mis":"SO5-1-u3-X03"},{"t":"양심에만 맡겨 둔 일이기 때문에","mis":"SO5-1-u3-X01"}],"explanation":["다른 사람이 다칠 수 있어요.","그래서 법으로 정했어요.","꼭 내려서 끌고 건너요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_challenge#4','soc',5,1,'u3','L01','g5_1_soc_u3_L01_challenge','lesson_challenge','SO5-1-u3-C1',3,'mc','auto','약속이나 규칙을 지키지 않는 사람이 많아질 때 생기는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X07','SO5-1-u3-X01']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C1","difficulty":3,"kind":"mc","stem":"약속이나 규칙을 지키지 않는 사람이 많아질 때 생기는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"다툼이나 갈등이 생기고 피해를 겪는 사람이 생긴다","correct":true},{"t":"모두가 더 편안해진다","mis":"SO5-1-u3-X07"},{"t":"아무 일도 생기지 않는다","mis":"SO5-1-u3-X01"},{"t":"법이 저절로 사라진다","mis":"SO5-1-u3-X07"}],"explanation":["지키지 않으면 다툼이 생겨요.","피해를 겪는 사람도 생겨요.","그래서 법이 만들어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_challenge#5','soc',5,1,'u3','L01','g5_1_soc_u3_L01_challenge','lesson_challenge','SO5-1-u3-C2',3,'mc','auto','「상점에서 값을 내지 않고 물건을 가져가는 일」을 법으로 정해 둔 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X03','SO5-1-u3-X01']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C2","difficulty":3,"kind":"mc","stem":"「상점에서 값을 내지 않고 물건을 가져가는 일」을 법으로 정해 둔 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"상점 주인에게 큰 피해를 주기 때문에","correct":true},{"t":"물건이 무거워지기 때문에","mis":"SO5-1-u3-X03"},{"t":"상점 주인이 싫어하는 인사이기 때문에","mis":"SO5-1-u3-X03"},{"t":"양심에 따라 스스로 지키면 되기 때문에","mis":"SO5-1-u3-X01"}],"explanation":["주인의 재산을 빼앗는 일이에요.","큰 피해를 줘요.","그래서 법이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_challenge#6','soc',5,1,'u3','L01','g5_1_soc_u3_L01_challenge','lesson_challenge','SO5-1-u3-C1',3,'ox','auto','법을 지키는 일은 하고 싶을 때만 골라서 하면 돼요.',ARRAY['SO5-1-u3-X01']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C1","difficulty":3,"kind":"ox","stem":"법을 지키는 일은 하고 싶을 때만 골라서 하면 돼요.","answer":"X","reason_options":[{"t":"법은 모두가 반드시 지켜야 하는 강제성이 있기 때문에","correct":true},{"t":"법은 양심에 따라 스스로 정하는 약속이기 때문에","mis":"SO5-1-u3-X01"}],"mis":"SO5-1-u3-X01","explanation":["법은 고르는 것이 아니에요.","반드시 지켜야 해요.","어기면 제재를 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_challenge#7','soc',5,1,'u3','L01','g5_1_soc_u3_L01_challenge','lesson_challenge','SO5-1-u3-C1',3,'error','auto','세계의 여러 법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X26']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C1","difficulty":3,"kind":"error","stem":"세계의 여러 법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「반려견 산책 법은 우리나라 법이니까 우리도 꼭 지켜야 해.」","correct":true,"mis_target":"SO5-1-u3-X26"},{"t":"태율 — 「책가방 무게 법은 자라는 어린이의 건강을 생각한 거야.」","mis":"SO5-1-u3-X26"},{"t":"하늘 — 「반려견 산책 법은 동물을 보호하려고 만든 거야.」","mis":"SO5-1-u3-X26"}],"explanation":["반려견 산책 법은 다른 나라 도시의 법이에요.","나라마다 법이 달라요.","지안이가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 어느 주 — 어린이 책가방 무게를 제한한다.","㉯ 어느 나라 — 공공장소에서 껌을 씹지 못하게 한다.","㉰ 어느 도시 — 반려견을 하루 세 번 산책시키게 한다."],"title":"세계의 여러 법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_challenge#8','soc',5,1,'u3','L01','g5_1_soc_u3_L01_challenge','lesson_challenge','SO5-1-u3-C1',4,'mc','auto','법 서랍과 양심 서랍을 견주어 알게 된 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X01','SO5-1-u3-X02']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C1","difficulty":4,"kind":"mc","stem":"법 서랍과 양심 서랍을 견주어 알게 된 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"법은 지키지 않으면 국가가 제재하지만, 양심에 맡긴 일은 스스로 지켜야 한다","correct":true},{"t":"법과 양심은 똑같아서 가를 필요가 없다","mis":"SO5-1-u3-X01"},{"t":"양심에 맡긴 일은 안 지켜도 아무 문제가 없다","mis":"SO5-1-u3-X01"},{"t":"법은 국가가 제재하지 않는다","mis":"SO5-1-u3-X02"}],"explanation":["법 서랍은 자물쇠가 걸려요.","양심 서랍은 아무도 재지 않아요.","그래서 스스로 지켜야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_challenge#9','soc',5,1,'u3','L01','g5_1_soc_u3_L01_challenge','lesson_challenge','SO5-1-u3-C2',4,'mc','auto','어떤 일에 법이 필요한지 판단하는 잣대로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X03','SO5-1-u3-X07']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C2","difficulty":4,"kind":"mc","stem":"어떤 일에 법이 필요한지 판단하는 잣대로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지키지 않으면 크게 다치거나 다른 사람에게 큰 피해가 생기는지 살펴본다","correct":true},{"t":"어른들이 자주 하는 일인지 살펴본다","mis":"SO5-1-u3-X03"},{"t":"글로 쓰기 쉬운 일인지 살펴본다","mis":"SO5-1-u3-X07"},{"t":"친구들이 좋아하는 일인지 살펴본다","mis":"SO5-1-u3-X03"}],"explanation":["안전에 큰 위협인지 봐요.","큰 피해가 생기는지 봐요.","그런 일에 법이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L01_challenge#10','soc',5,1,'u3','L01','g5_1_soc_u3_L01_challenge','lesson_challenge','SO5-1-u3-C1',4,'essay','teacher','법의 뜻과 두 가지 특징을 쓰고, 여섯 가지 상황 가운데 법이 필요한 상황 하나를 골라 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u3-C1","difficulty":4,"kind":"essay","stem":"법의 뜻과 두 가지 특징을 쓰고, 여섯 가지 상황 가운데 법이 필요한 상황 하나를 골라 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 법은 사회 구성원이 반드시 지켜야 하는 강제성이 있는 규범이다. 모두가 반드시 지켜야 하고, 지키지 않으면 국가로부터 제재를 받는다. ㉢ 횡단보도에서 신호를 지키지 않으면 큰 사고가 날 수 있으므로 법이 필요하다.","scoring_points":["법의 뜻을 썼는가","강제성과 국가의 제재를 썼는가","법이 필요한 상황과 까닭을 썼는가"]},"explanation":["뜻을 먼저 써요.","특징 둘을 써요.","상황과 까닭을 이어 써요."],"asset":{"type":"passage","lines":["㉠ 차에 타서 안전벨트를 매지 않는다.","㉡ 웃어른을 만나도 인사하지 않는다.","㉢ 횡단보도에서 신호를 지키지 않는다.","㉣ 길에 떨어진 쓰레기를 줍지 않고 지나간다.","㉤ 가게에서 값을 내지 않고 물건을 가져간다.","㉥ 형제끼리 말다툼을 한다."],"title":"여섯 가지 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_basic#1','soc',5,1,'u3','L02','g5_1_soc_u3_L02_basic','lesson_basic','SO5-1-u3-C3',1,'mc','auto','영양가 있고 안전한 급식을 먹을 수 있도록 정해 둔 법은 어느 것인가요?',ARRAY['SO5-1-u3-X05']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C3","difficulty":1,"kind":"mc","stem":"영양가 있고 안전한 급식을 먹을 수 있도록 정해 둔 법은 어느 것인가요?","options":[{"t":"「학교 급식법」","correct":true},{"t":"「건축법」","mis":"SO5-1-u3-X05"},{"t":"「의료법」","mis":"SO5-1-u3-X05"},{"t":"「저작권법」","mis":"SO5-1-u3-X05"}],"explanation":["급식에 관한 법이에요.","영양과 안전을 지켜 줘요.","「학교 급식법」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_basic#2','soc',5,1,'u3','L02','g5_1_soc_u3_L02_basic','lesson_basic','SO5-1-u3-C3',1,'mc','auto','안전한 놀이터를 이용할 수 있도록 정해 둔 법은 어느 것인가요?',ARRAY['SO5-1-u3-X05']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C3","difficulty":1,"kind":"mc","stem":"안전한 놀이터를 이용할 수 있도록 정해 둔 법은 어느 것인가요?","options":[{"t":"「어린이 놀이 시설 안전 관리법」","correct":true},{"t":"「소비자 기본법」","mis":"SO5-1-u3-X05"},{"t":"「학교 급식법」","mis":"SO5-1-u3-X05"},{"t":"「소방 기본법」","mis":"SO5-1-u3-X05"}],"explanation":["놀이 시설의 안전을 살펴요.","놀이터에도 법이 있어요.","이름에 놀이 시설이 들어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_basic#3','soc',5,1,'u3','L02','g5_1_soc_u3_L02_basic','lesson_basic','SO5-1-u3-C4',1,'mc','auto','노래나 그림 같은 창작물을 만든 사람의 권리를 보호하는 법은 어느 것인가요?',ARRAY['SO5-1-u3-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C4","difficulty":1,"kind":"mc","stem":"노래나 그림 같은 창작물을 만든 사람의 권리를 보호하는 법은 어느 것인가요?","options":[{"t":"「저작권법」","correct":true},{"t":"「의료법」","mis":"SO5-1-u3-X05"},{"t":"「건축법」","mis":"SO5-1-u3-X05"},{"t":"「도로 교통법」","mis":"SO5-1-u3-X05"}],"explanation":["창작물을 만든 사람을 저작자라고 해요.","저작자의 권리를 지켜요.","「저작권법」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_basic#4','soc',5,1,'u3','L02','g5_1_soc_u3_L02_basic','lesson_basic','SO5-1-u3-C4',1,'ox','auto','법은 법원이나 국회 안에서만 쓰여서 우리 하루와는 관계가 없어요.',ARRAY['SO5-1-u3-X04']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C4","difficulty":1,"kind":"ox","stem":"법은 법원이나 국회 안에서만 쓰여서 우리 하루와는 관계가 없어요.","answer":"X","reason_options":[{"t":"등굣길·급식·놀이터처럼 생활 곳곳에 법이 적용되기 때문에","correct":true},{"t":"법은 어른들만 지키면 되기 때문에","mis":"SO5-1-u3-X04"}],"mis":"SO5-1-u3-X04","explanation":["학교 하루에도 법이 있어요.","마을 곳곳에도 법이 있어요.","생활 곳곳에 적용돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_basic#5','soc',5,1,'u3','L02','g5_1_soc_u3_L02_basic','lesson_basic','SO5-1-u3-C3',2,'mc','auto','서진이의 학교 하루에서 ㉠과 관련 있는 법은 어느 것인가요?',ARRAY['SO5-1-u3-X05']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C3","difficulty":2,"kind":"mc","stem":"서진이의 학교 하루에서 ㉠과 관련 있는 법은 어느 것인가요?","options":[{"t":"「도로 교통법」","correct":true},{"t":"「학교 급식법」","mis":"SO5-1-u3-X05"},{"t":"「초·중등 교육법」","mis":"SO5-1-u3-X05"},{"t":"「어린이 놀이 시설 안전 관리법」","mis":"SO5-1-u3-X05"}],"explanation":["횡단보도를 건너 등교해요.","도로와 교통에 관한 법이에요.","「도로 교통법」이에요."],"asset":{"type":"passage","lines":["㉠ 아침 — 횡단보도를 건너 안전하게 학교에 간다.","㉡ 오전 — 교실에서 선생님과 수업을 한다.","㉢ 점심 — 영양을 생각한 급식을 먹는다.","㉣ 쉬는 시간 — 안전 검사를 받은 놀이터에서 논다."],"title":"서진이의 학교 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_basic#6','soc',5,1,'u3','L02','g5_1_soc_u3_L02_basic','lesson_basic','SO5-1-u3-C3',2,'mc','auto','서진이의 학교 하루에서 ㉡과 관련 있는 법은 어느 것인가요?',ARRAY['SO5-1-u3-X05']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C3","difficulty":2,"kind":"mc","stem":"서진이의 학교 하루에서 ㉡과 관련 있는 법은 어느 것인가요?","options":[{"t":"「초·중등 교육법」","correct":true},{"t":"「도로 교통법」","mis":"SO5-1-u3-X05"},{"t":"「소방 기본법」","mis":"SO5-1-u3-X05"},{"t":"「식품 안전 기본법」","mis":"SO5-1-u3-X05"}],"explanation":["교실에서 수업을 해요.","학교 교육에 관한 법이에요.","「초·중등 교육법」이에요."],"asset":{"type":"passage","lines":["㉠ 아침 — 횡단보도를 건너 안전하게 학교에 간다.","㉡ 오전 — 교실에서 선생님과 수업을 한다.","㉢ 점심 — 영양을 생각한 급식을 먹는다.","㉣ 쉬는 시간 — 안전 검사를 받은 놀이터에서 논다."],"title":"서진이의 학교 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_basic#7','soc',5,1,'u3','L02','g5_1_soc_u3_L02_basic','lesson_basic','SO5-1-u3-C4',2,'mc','auto','마을 곳곳의 장면에서 ㉰와 관련 있는 법은 어느 것인가요?',ARRAY['SO5-1-u3-X05']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C4","difficulty":2,"kind":"mc","stem":"마을 곳곳의 장면에서 ㉰와 관련 있는 법은 어느 것인가요?","options":[{"t":"「건축법」","correct":true},{"t":"「의료법」","mis":"SO5-1-u3-X05"},{"t":"「저작권법」","mis":"SO5-1-u3-X05"},{"t":"「소비자 기본법」","mis":"SO5-1-u3-X05"}],"explanation":["새 건물의 안전을 살펴요.","건물을 짓는 일에 관한 법이에요.","「건축법」이에요."],"asset":{"type":"passage","lines":["㉮ 노래를 내려받을 때 값을 낸다.","㉯ 경찰관이 골목을 순찰한다.","㉰ 새로 지은 건물의 안전을 확인한다.","㉱ 공원에서 쓰레기를 가지고 나온다.","㉲ 병원에서 의사에게 진찰을 받는다.","㉳ 음식점에서 안전한 음식을 사 먹는다."],"title":"마을 곳곳의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_basic#8','soc',5,1,'u3','L02','g5_1_soc_u3_L02_basic','lesson_basic','SO5-1-u3-C4',2,'mc','auto','「소방 기본법」을 정해 둔 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X05']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C4","difficulty":2,"kind":"mc","stem":"「소방 기본법」을 정해 둔 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"불이나 재난이 났을 때 국민의 생명과 재산을 보호하려고","correct":true},{"t":"급식을 더 맛있게 만들려고","mis":"SO5-1-u3-X05"},{"t":"건물을 더 높게 지으려고","mis":"SO5-1-u3-X05"},{"t":"창작물의 값을 정하려고","mis":"SO5-1-u3-X05"}],"explanation":["소방관이 출동해요.","위급한 상황이에요.","생명과 재산을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_basic#9','soc',5,1,'u3','L02','g5_1_soc_u3_L02_basic','lesson_basic','SO5-1-u3-C4',2,'mc','auto','알고 싶은 주제의 법을 조사할 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['SO5-1-u3-X06','SO5-1-u3-X26']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C4","difficulty":2,"kind":"mc","stem":"알고 싶은 주제의 법을 조사할 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"알고 싶은 주제를 정한다","correct":true},{"t":"친구가 쓴 것을 그대로 옮긴다","mis":"SO5-1-u3-X06"},{"t":"법 이름을 모두 외운다","mis":"SO5-1-u3-X26"},{"t":"조사한 내용을 지운다","mis":"SO5-1-u3-X06"}],"explanation":["주제가 있어야 찾을 수 있어요.","그다음 누리집에서 찾아요.","내용을 살펴 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_basic#10','soc',5,1,'u3','L02','g5_1_soc_u3_L02_basic','lesson_basic','SO5-1-u3-C4',3,'error','auto','법 조사를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X06']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C4","difficulty":3,"kind":"error","stem":"법 조사를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「누리집에 나온 설명을 한 글자도 안 바꾸고 그대로 베껴 내면 돼.」","correct":true,"mis_target":"SO5-1-u3-X06"},{"t":"예린 — 「먼저 알고 싶은 주제를 정해야 해.」","mis":"SO5-1-u3-X06"},{"t":"시우 — 「찾은 내용을 살펴보고 내 말로 정리할래.」","mis":"SO5-1-u3-X06"}],"explanation":["조사는 내 말로 정리해요.","그대로 베끼면 안 돼요.","준서가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"나는 학교 급식에 관한 법이 궁금해."},{"who":"수아","text":"그럼 먼저 생활 법령 누리집에서 찾아보자."},{"who":"이안","text":"찾은 내용은 내 말로 간추려 적을게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_challenge#1','soc',5,1,'u3','L02','g5_1_soc_u3_L02_challenge','lesson_challenge','SO5-1-u3-C4',2,'match','auto','마을 곳곳의 장면과 관련 있는 법을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u3-C4","difficulty":2,"kind":"match","stem":"마을 곳곳의 장면과 관련 있는 법을 알맞게 이으세요.","pairs":[{"l":"㉮ 노래 값 내기","r":"「저작권법」"},{"l":"㉯ 골목 순찰","r":"「경찰관 직무 집행법」"},{"l":"㉲ 진찰받기","r":"「의료법」"},{"l":"㉳ 안전한 음식","r":"「식품 안전 기본법」"}],"mis":"SO5-1-u3-X05","explanation":["창작물은 저작권이에요.","순찰은 경찰관의 일이에요.","진찰은 의료, 음식은 식품 안전이에요."],"asset":{"type":"passage","lines":["㉮ 노래를 내려받을 때 값을 낸다.","㉯ 경찰관이 골목을 순찰한다.","㉰ 새로 지은 건물의 안전을 확인한다.","㉱ 공원에서 쓰레기를 가지고 나온다.","㉲ 병원에서 의사에게 진찰을 받는다.","㉳ 음식점에서 안전한 음식을 사 먹는다."],"title":"마을 곳곳의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_challenge#2','soc',5,1,'u3','L02','g5_1_soc_u3_L02_challenge','lesson_challenge','SO5-1-u3-C4',2,'mc','auto','마을 곳곳의 장면에서 ㉱와 관련 있는 법은 어느 것인가요?',ARRAY['SO5-1-u3-X05']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C4","difficulty":2,"kind":"mc","stem":"마을 곳곳의 장면에서 ㉱와 관련 있는 법은 어느 것인가요?","options":[{"t":"「자연환경 보전법」","correct":true},{"t":"「건축법」","mis":"SO5-1-u3-X05"},{"t":"「의료법」","mis":"SO5-1-u3-X05"},{"t":"「학교 급식법」","mis":"SO5-1-u3-X05"}],"explanation":["공원 쓰레기를 가지고 나와요.","자연을 깨끗하게 지켜요.","「자연환경 보전법」이에요."],"asset":{"type":"passage","lines":["㉮ 노래를 내려받을 때 값을 낸다.","㉯ 경찰관이 골목을 순찰한다.","㉰ 새로 지은 건물의 안전을 확인한다.","㉱ 공원에서 쓰레기를 가지고 나온다.","㉲ 병원에서 의사에게 진찰을 받는다.","㉳ 음식점에서 안전한 음식을 사 먹는다."],"title":"마을 곳곳의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_challenge#3','soc',5,1,'u3','L02','g5_1_soc_u3_L02_challenge','lesson_challenge','SO5-1-u3-C4',3,'mc','auto','「자연환경 보전법」을 정해 둔 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C4","difficulty":3,"kind":"mc","stem":"「자연환경 보전법」을 정해 둔 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"생태계와 자연환경을 보호해 국민이 건강하게 생활하도록 하려고","correct":true},{"t":"도로를 더 많이 만들려고","mis":"SO5-1-u3-X05"},{"t":"건물을 높이 지으려고","mis":"SO5-1-u3-X05"},{"t":"급식을 빨리 먹으려고","mis":"SO5-1-u3-X05"}],"explanation":["자연이 망가지면 모두가 아파요.","생태계를 지켜요.","국민의 건강한 생활을 위해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_challenge#4','soc',5,1,'u3','L02','g5_1_soc_u3_L02_challenge','lesson_challenge','SO5-1-u3-C4',3,'mc','auto','특별 사법 경찰이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X04','SO5-1-u3-X07']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C4","difficulty":3,"kind":"mc","stem":"특별 사법 경찰이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"세금·교통·환경 같은 전문 분야에서 법이 잘 지켜지는지 수사한다","correct":true},{"t":"학교에서 급식을 만든다","mis":"SO5-1-u3-X04"},{"t":"새로운 법을 혼자 만든다","mis":"SO5-1-u3-X07"},{"t":"놀이터 놀이기구를 새로 칠한다","mis":"SO5-1-u3-X04"}],"explanation":["특수하고 전문적인 분야를 맡아요.","불법 행위가 없는지 살펴요.","그 분야의 공무원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_challenge#5','soc',5,1,'u3','L02','g5_1_soc_u3_L02_challenge','lesson_challenge','SO5-1-u3-C4',3,'mc','auto','생활 법령 누리집에서 검색어를 바꾸어 여러 번 찾아보았더니 다른 법이 계속 나왔어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X04','SO5-1-u3-X06','SO5-1-u3-X26']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C4","difficulty":3,"kind":"mc","stem":"생활 법령 누리집에서 검색어를 바꾸어 여러 번 찾아보았더니 다른 법이 계속 나왔어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"법이 생활 곳곳에 적용되어 주제마다 다른 법이 있기 때문에","correct":true},{"t":"법이 하나뿐이어서 여러 번 찾아야 하기 때문에","mis":"SO5-1-u3-X04"},{"t":"검색어가 길수록 좋은 법이 나오기 때문에","mis":"SO5-1-u3-X06"},{"t":"법 이름을 모두 외워야 하기 때문에","mis":"SO5-1-u3-X26"}],"explanation":["등굣길·급식·놀이터 법이 달랐어요.","주제마다 다른 법이 있어요.","우리 사회의 많은 일이 법에 따라 이루어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_challenge#6','soc',5,1,'u3','L02','g5_1_soc_u3_L02_challenge','lesson_challenge','SO5-1-u3-C3',3,'ox','auto','서진이의 학교 하루에서 ㉣ 놀이터의 안전도 법이 지켜 주고 있어요.',ARRAY['SO5-1-u3-X04']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C3","difficulty":3,"kind":"ox","stem":"서진이의 학교 하루에서 ㉣ 놀이터의 안전도 법이 지켜 주고 있어요.","answer":"O","reason_options":[{"t":"놀이 시설의 안전을 관리하는 법이 있기 때문에","correct":true},{"t":"놀이터는 법이 아니라 양심으로만 관리하기 때문에","mis":"SO5-1-u3-X04"}],"mis":"SO5-1-u3-X04","explanation":["놀이터도 안전 검사를 받아요.","관리하는 법이 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 아침 — 횡단보도를 건너 안전하게 학교에 간다.","㉡ 오전 — 교실에서 선생님과 수업을 한다.","㉢ 점심 — 영양을 생각한 급식을 먹는다.","㉣ 쉬는 시간 — 안전 검사를 받은 놀이터에서 논다."],"title":"서진이의 학교 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_challenge#7','soc',5,1,'u3','L02','g5_1_soc_u3_L02_challenge','lesson_challenge','SO5-1-u3-C4',3,'error','auto','일상생활 속 법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X04','SO5-1-u3-X05']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C4","difficulty":3,"kind":"error","stem":"일상생활 속 법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희 — 「서비스 센터에 물건을 고치러 가는 건 법과 상관없는 일이야.」","correct":true,"mis_target":"SO5-1-u3-X04"},{"t":"현우 — 「서비스 센터 방문은 「소비자 기본법」과 이어져.」","mis":"SO5-1-u3-X05"},{"t":"다인 — 「음식점의 음식도 법이 안전을 살펴.」","mis":"SO5-1-u3-X05"}],"explanation":["소비자를 지키는 법이 있어요.","서비스 센터도 법과 이어져요.","라희가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_challenge#8','soc',5,1,'u3','L02','g5_1_soc_u3_L02_challenge','lesson_challenge','SO5-1-u3-C4',4,'mc','auto','「식품 안전 기본법」·「자연환경 보전법」·「소방 기본법」을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X05','SO5-1-u3-X04','SO5-1-u3-X26']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C4","difficulty":4,"kind":"mc","stem":"「식품 안전 기본법」·「자연환경 보전법」·「소방 기본법」을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"법마다 정해 둔 까닭이 있고 모두 국민의 안전하고 건강한 생활을 위한 것이다","correct":true},{"t":"세 법은 이름만 다르고 하는 일이 같다","mis":"SO5-1-u3-X05"},{"t":"세 법은 어른들만 지키면 된다","mis":"SO5-1-u3-X04"},{"t":"법은 이름만 외우면 생활에 쓸 수 있다","mis":"SO5-1-u3-X26"}],"explanation":["먹을거리, 자연, 생명과 재산을 지켜요.","까닭은 저마다 달라요.","모두 국민의 생활을 위해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_challenge#9','soc',5,1,'u3','L02','g5_1_soc_u3_L02_challenge','lesson_challenge','SO5-1-u3-C3',4,'mc','auto','서진이의 학교 하루를 함께 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO5-1-u3-X04','SO5-1-u3-X05']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C3","difficulty":4,"kind":"mc","stem":"서진이의 학교 하루를 함께 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"학교에서 보내는 하루에도 여러 법이 함께하며 안전하게 생활하도록 도와준다","correct":true},{"t":"학교 안에서는 법이 하나도 적용되지 않는다","mis":"SO5-1-u3-X04"},{"t":"법은 등굣길에만 필요하다","mis":"SO5-1-u3-X04"},{"t":"급식과 놀이터는 같은 법이 지킨다","mis":"SO5-1-u3-X05"}],"explanation":["등굣길·수업·급식·놀이터 모두예요.","저마다 다른 법이 있어요.","하루 내내 법이 함께해요."],"asset":{"type":"passage","lines":["㉠ 아침 — 횡단보도를 건너 안전하게 학교에 간다.","㉡ 오전 — 교실에서 선생님과 수업을 한다.","㉢ 점심 — 영양을 생각한 급식을 먹는다.","㉣ 쉬는 시간 — 안전 검사를 받은 놀이터에서 논다."],"title":"서진이의 학교 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L02_challenge#10','soc',5,1,'u3','L02','g5_1_soc_u3_L02_challenge','lesson_challenge','SO5-1-u3-C4',4,'essay','teacher','내가 알고 싶은 주제를 하나 정해 법을 조사하는 차례를 쓰고, 일상생활 속 법 하나를 골라 그 법이 우리 생활에 주는 영향을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u3-C4","difficulty":4,"kind":"essay","stem":"내가 알고 싶은 주제를 하나 정해 법을 조사하는 차례를 쓰고, 일상생활 속 법 하나를 골라 그 법이 우리 생활에 주는 영향을 쓰세요.","answer_guide":{"answer":"예: 주제를 「먹을거리 안전」으로 정한 뒤 생활 법령 누리집에서 찾아 내용을 살펴보고 내 말로 정리한다. 「식품 안전 기본법」이 있어 식품의 안전을 살피므로 우리는 건강하고 안전한 먹을거리를 얻을 수 있다.","scoring_points":["주제 정하기부터 차례를 썼는가","법 하나를 골랐는가","그 법이 생활에 주는 영향을 썼는가"]},"explanation":["주제부터 정해요.","찾고 살피고 정리해요.","생활에 주는 영향을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_basic#1','soc',5,1,'u3','L03','g5_1_soc_u3_L03_basic','lesson_basic','SO5-1-u3-C5',1,'mc','auto','법이 필요한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X07','SO5-1-u3-X26']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C5","difficulty":1,"kind":"mc","stem":"법이 필요한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람들 사이의 갈등이나 다툼을 해결하는 기준이 되기 때문에","correct":true},{"t":"법이 많을수록 좋기 때문에","mis":"SO5-1-u3-X07"},{"t":"어른들이 정해 두었기 때문에","mis":"SO5-1-u3-X07"},{"t":"글로 적어 두면 외우기 쉽기 때문에","mis":"SO5-1-u3-X26"}],"explanation":["문제가 생기면 기준이 필요해요.","법이 그 기준이 돼요.","그래서 법이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_basic#2','soc',5,1,'u3','L03','g5_1_soc_u3_L03_basic','lesson_basic','SO5-1-u3-C6',1,'sa','auto','개인 사이에 다툼이 생겼을 때 법에 따라 옳고 그름을 가리는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u3-C6","difficulty":1,"kind":"sa","stem":"개인 사이에 다툼이 생겼을 때 법에 따라 옳고 그름을 가리는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["재판"],"explanation":["법원에서 해요.","옳고 그름을 가려요.","재판이에요."],"mis":"SO5-1-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_basic#3','soc',5,1,'u3','L03','g5_1_soc_u3_L03_basic','lesson_basic','SO5-1-u3-C7',1,'mc','auto','공정한 경제 질서를 유지하는 것은 법의 어떤 역할인가요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C7","difficulty":1,"kind":"mc","stem":"공정한 경제 질서를 유지하는 것은 법의 어떤 역할인가요?","options":[{"t":"사회 질서 유지","correct":true},{"t":"개인 정보 보호","mis":"SO5-1-u3-X08"},{"t":"개인의 생명 보호","mis":"SO5-1-u3-X08"},{"t":"개인 사이의 다툼 해결","mis":"SO5-1-u3-X08"}],"explanation":["모두가 공정하게 사고팔아요.","사회 전체의 질서예요.","사회 질서 유지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_basic#4','soc',5,1,'u3','L03','g5_1_soc_u3_L03_basic','lesson_basic','SO5-1-u3-C6',1,'ox','auto','생년월일이나 전화번호 같은 개인 정보도 법이 보호해 줘요.',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C6","difficulty":1,"kind":"ox","stem":"생년월일이나 전화번호 같은 개인 정보도 법이 보호해 줘요.","answer":"O","reason_options":[{"t":"개인 정보를 지키는 것은 개인의 권리를 보호하는 일이기 때문에","correct":true},{"t":"개인 정보는 누구나 마음대로 써도 되기 때문에","mis":"SO5-1-u3-X08"}],"mis":"SO5-1-u3-X08","explanation":["개인 정보는 소중해요.","법이 지켜 줘요.","개인의 권리 보호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_basic#5','soc',5,1,'u3','L03','g5_1_soc_u3_L03_basic','lesson_basic','SO5-1-u3-C5',2,'mc','auto','어느 하천 이야기에서 법이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X07']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C5","difficulty":2,"kind":"mc","stem":"어느 하천 이야기에서 법이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"폐수를 함부로 버리지 못하게 해 사람과 생물이 함께 입는 피해를 막으려고","correct":true},{"t":"공장을 더 많이 짓게 하려고","mis":"SO5-1-u3-X07"},{"t":"하천을 더 깊게 파려고","mis":"SO5-1-u3-X07"},{"t":"물고기를 더 많이 잡으려고","mis":"SO5-1-u3-X07"}],"explanation":["물고기가 죽고 냄새가 나요.","마을 사람들도 걱정해요.","함부로 버리지 못하게 법이 필요해요."],"asset":{"type":"passage","lines":["어느 공장이 몇 달 동안 폐수를 하천에 몰래 흘려보냈다.","하천의 물고기가 죽고 둘레에서 심한 냄새가 났다.","하천 아래 마을 사람들은 마실 물을 걱정하고 있다."],"title":"어느 하천 이야기(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_basic#6','soc',5,1,'u3','L03','g5_1_soc_u3_L03_basic','lesson_basic','SO5-1-u3-C6',2,'mc','auto','전화번호 대신 개인 안심 번호를 쓰도록 안내하는 모습은 법의 어떤 역할을 보여 주나요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C6","difficulty":2,"kind":"mc","stem":"전화번호 대신 개인 안심 번호를 쓰도록 안내하는 모습은 법의 어떤 역할을 보여 주나요?","options":[{"t":"개인 정보를 보호한다","correct":true},{"t":"교통질서를 유지한다","mis":"SO5-1-u3-X08"},{"t":"공정한 경제 질서를 유지한다","mis":"SO5-1-u3-X08"},{"t":"거리를 깨끗하게 한다","mis":"SO5-1-u3-X08"}],"explanation":["내 진짜 번호를 감춰요.","개인 정보를 지켜요.","개인의 권리 보호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_basic#7','soc',5,1,'u3','L03','g5_1_soc_u3_L03_basic','lesson_basic','SO5-1-u3-C7',2,'mc','auto','어린이 보호 구역에서 자동차가 천천히 달리게 하는 것은 법의 어떤 역할인가요?',ARRAY['SO5-1-u3-X08','SO5-1-u3-X05']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C7","difficulty":2,"kind":"mc","stem":"어린이 보호 구역에서 자동차가 천천히 달리게 하는 것은 법의 어떤 역할인가요?","options":[{"t":"사고를 예방해 사회 질서를 유지한다","correct":true},{"t":"개인 사이의 다툼을 재판으로 해결한다","mis":"SO5-1-u3-X08"},{"t":"개인 정보를 보호한다","mis":"SO5-1-u3-X08"},{"t":"창작물을 보호한다","mis":"SO5-1-u3-X05"}],"explanation":["사고가 나기 전에 막아요.","모두의 안전을 지켜요.","사회 질서 유지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_basic#8','soc',5,1,'u3','L03','g5_1_soc_u3_L03_basic','lesson_basic','SO5-1-u3-C6',2,'mc','auto','신문 기사 두 건 가운데 ㉮에서 법이 한 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C6","difficulty":2,"kind":"mc","stem":"신문 기사 두 건 가운데 ㉮에서 법이 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"초상권을 침해당한 사람의 권리를 보호했다","correct":true},{"t":"소방차가 지나갈 길을 지켰다","mis":"SO5-1-u3-X08"},{"t":"교통질서를 유지했다","mis":"SO5-1-u3-X08"},{"t":"공장의 폐수를 막았다","mis":"SO5-1-u3-X08"}],"explanation":["동의 없이 사진을 올렸어요.","법원이 배상하게 판결했어요.","개인의 권리를 보호했어요."],"asset":{"type":"passage","lines":["㉮ 동의 없이 남의 사진을 누리 소통망에 올린 사람이 있었다.","㉮ 피해자가 손해 배상을 청구했고, 법원은 배상금을 주고","㉮ 사진을 더는 쓰지 못하게 판결했다.","㉯ 소방차 전용 구역에 차를 세우거나 길을 막으면","㉯ 과태료를 내게 하는 법이 만들어졌다."],"title":"신문 기사 두 건(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_basic#9','soc',5,1,'u3','L03','g5_1_soc_u3_L03_basic','lesson_basic','SO5-1-u3-C7',2,'mc','auto','신문 기사 두 건 가운데 ㉯에서 알 수 있는 법의 역할은 어느 것인가요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C7","difficulty":2,"kind":"mc","stem":"신문 기사 두 건 가운데 ㉯에서 알 수 있는 법의 역할은 어느 것인가요?","options":[{"t":"사회 질서를 유지한다","correct":true},{"t":"개인 정보를 보호한다","mis":"SO5-1-u3-X08"},{"t":"개인 사이의 다툼을 해결한다","mis":"SO5-1-u3-X08"},{"t":"창작물을 보호한다","mis":"SO5-1-u3-X08"}],"explanation":["소방차 길을 지켜요.","모두의 안전을 위한 질서예요.","사회 질서 유지예요."],"asset":{"type":"passage","lines":["㉮ 동의 없이 남의 사진을 누리 소통망에 올린 사람이 있었다.","㉮ 피해자가 손해 배상을 청구했고, 법원은 배상금을 주고","㉮ 사진을 더는 쓰지 못하게 판결했다.","㉯ 소방차 전용 구역에 차를 세우거나 길을 막으면","㉯ 과태료를 내게 하는 법이 만들어졌다."],"title":"신문 기사 두 건(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_basic#10','soc',5,1,'u3','L03','g5_1_soc_u3_L03_basic','lesson_basic','SO5-1-u3-C5',3,'error','auto','법의 역할을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X09','SO5-1-u3-X08']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C5","difficulty":3,"kind":"error","stem":"법의 역할을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세준 — 「힘이 센 사람에게는 법을 조금 느슨하게 적용해도 돼.」","correct":true,"mis_target":"SO5-1-u3-X09"},{"t":"나윤 — 「법은 개인의 권리를 보호해.」","mis":"SO5-1-u3-X08"},{"t":"도하 — 「법은 사회 질서를 유지해.」","mis":"SO5-1-u3-X08"}],"explanation":["법은 누구에게나 똑같아야 해요.","그래야 기준이 돼요.","세준이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_challenge#1','soc',5,1,'u3','L03','g5_1_soc_u3_L03_challenge','lesson_challenge','SO5-1-u3-C6',2,'match','auto','법이 하는 일과 그 역할을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u3-C6","difficulty":2,"kind":"match","stem":"법이 하는 일과 그 역할을 알맞게 이으세요.","pairs":[{"l":"㉠ 재판으로 다툼 해결","r":"개인의 권리 보호"},{"l":"㉡ 어린이 보호 구역","r":"사회 질서 유지 — 사고 예방"},{"l":"㉣ 공정한 거래","r":"사회 질서 유지 — 경제 질서"},{"l":"㉤ 화재 때 생명 지키기","r":"개인의 권리 보호 — 생명과 재산"}],"mis":"SO5-1-u3-X08","explanation":["한 사람을 지켜 주면 권리 보호예요.","모두의 질서를 지키면 질서 유지예요.","두 갈래로 나누어요."],"asset":{"type":"passage","lines":["㉠ 개인 사이의 다툼을 재판으로 해결한다.","㉡ 어린이 보호 구역에서 자동차가 천천히 달리게 한다.","㉢ 전화번호 대신 개인 안심 번호를 쓰게 한다.","㉣ 공정하게 물건을 사고팔도록 한다.","㉤ 불이 났을 때 생명과 재산을 지킨다.","㉥ 거리를 깨끗하게 유지한다."],"title":"법이 하는 일 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_challenge#2','soc',5,1,'u3','L03','g5_1_soc_u3_L03_challenge','lesson_challenge','SO5-1-u3-C7',2,'mc','auto','법이 하는 일 여섯 가운데 사회 질서 유지에 드는 것끼리 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C7","difficulty":2,"kind":"mc","stem":"법이 하는 일 여섯 가운데 사회 질서 유지에 드는 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"㉡·㉣·㉥","correct":true},{"t":"㉠·㉢·㉤","mis":"SO5-1-u3-X08"},{"t":"㉠·㉡·㉢","mis":"SO5-1-u3-X08"},{"t":"㉢·㉤·㉥","mis":"SO5-1-u3-X08"}],"explanation":["사고 예방·경제 질서·깨끗한 거리예요.","모두를 위한 질서예요.","㉡·㉣·㉥이에요."],"asset":{"type":"passage","lines":["㉠ 개인 사이의 다툼을 재판으로 해결한다.","㉡ 어린이 보호 구역에서 자동차가 천천히 달리게 한다.","㉢ 전화번호 대신 개인 안심 번호를 쓰게 한다.","㉣ 공정하게 물건을 사고팔도록 한다.","㉤ 불이 났을 때 생명과 재산을 지킨다.","㉥ 거리를 깨끗하게 유지한다."],"title":"법이 하는 일 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_challenge#3','soc',5,1,'u3','L03','g5_1_soc_u3_L03_challenge','lesson_challenge','SO5-1-u3-C5',3,'mc','auto','「법이 없다면 어떤 일이 생길까?」 하고 떠올려 보는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X07','SO5-1-u3-X26']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C5","difficulty":3,"kind":"mc","stem":"「법이 없다면 어떤 일이 생길까?」 하고 떠올려 보는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"평소에 법이 무슨 일을 하고 있었는지 알 수 있기 때문에","correct":true},{"t":"법을 없애는 방법을 배우려고","mis":"SO5-1-u3-X07"},{"t":"법이 몇 개인지 세어 보려고","mis":"SO5-1-u3-X26"},{"t":"법이 필요 없다는 것을 보이려고","mis":"SO5-1-u3-X07"}],"explanation":["법을 걷어 내 보면 달라져요.","그 빈자리가 법의 일이에요.","법의 역할이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_challenge#4','soc',5,1,'u3','L03','g5_1_soc_u3_L03_challenge','lesson_challenge','SO5-1-u3-C6',3,'mc','auto','불이 났을 때 소방관이 빨리 와서 큰 피해를 막아 주었어요. 이 경험에서 볼 수 있는 법의 역할은 어느 것인가요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C6","difficulty":3,"kind":"mc","stem":"불이 났을 때 소방관이 빨리 와서 큰 피해를 막아 주었어요. 이 경험에서 볼 수 있는 법의 역할은 어느 것인가요?","options":[{"t":"개인의 생명이나 재산을 보호한다","correct":true},{"t":"공정한 경제 질서를 유지한다","mis":"SO5-1-u3-X08"},{"t":"거리를 깨끗하게 한다","mis":"SO5-1-u3-X08"},{"t":"개인 사이의 다툼을 해결한다","mis":"SO5-1-u3-X08"}],"explanation":["집과 가족을 지켰어요.","생명과 재산이에요.","개인의 권리 보호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_challenge#5','soc',5,1,'u3','L03','g5_1_soc_u3_L03_challenge','lesson_challenge','SO5-1-u3-C5',3,'ox','auto','법이 사람에 따라 다르게 적용된다면 다툼을 해결하는 기준이 될 수 없어요.',ARRAY['SO5-1-u3-X09']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C5","difficulty":3,"kind":"ox","stem":"법이 사람에 따라 다르게 적용된다면 다툼을 해결하는 기준이 될 수 없어요.","answer":"O","reason_options":[{"t":"같은 일에 다른 판단이 나오면 누구도 기준을 믿을 수 없기 때문에","correct":true},{"t":"법은 원래 사람마다 다르게 쓰는 것이기 때문에","mis":"SO5-1-u3-X09"}],"mis":"SO5-1-u3-X09","explanation":["기준은 같아야 해요.","누구에게나 똑같이요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_challenge#6','soc',5,1,'u3','L03','g5_1_soc_u3_L03_challenge','lesson_challenge','SO5-1-u3-C7',3,'error','auto','신문 기사 두 건을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C7","difficulty":3,"kind":"error","stem":"신문 기사 두 건을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「㉯는 사진을 올린 한 사람의 권리를 지켜 준 일이야.」","correct":true,"mis_target":"SO5-1-u3-X08"},{"t":"채아 — 「㉮는 개인의 권리를 보호한 거야.」","mis":"SO5-1-u3-X08"},{"t":"주원 — 「㉯는 모두의 안전을 위한 질서야.」","mis":"SO5-1-u3-X08"}],"explanation":["㉯는 소방차 길에 관한 기사예요.","모두의 질서를 지켜요.","윤호가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 동의 없이 남의 사진을 누리 소통망에 올린 사람이 있었다.","㉮ 피해자가 손해 배상을 청구했고, 법원은 배상금을 주고","㉮ 사진을 더는 쓰지 못하게 판결했다.","㉯ 소방차 전용 구역에 차를 세우거나 길을 막으면","㉯ 과태료를 내게 하는 법이 만들어졌다."],"title":"신문 기사 두 건(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_challenge#7','soc',5,1,'u3','L03','g5_1_soc_u3_L03_challenge','lesson_challenge','SO5-1-u3-C5',3,'mc','auto','어느 하천 이야기와 같은 일이 계속 생길 때 법이 있으면 달라지는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X07','SO5-1-u3-X09']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C5","difficulty":3,"kind":"mc","stem":"어느 하천 이야기와 같은 일이 계속 생길 때 법이 있으면 달라지는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"폐수를 버린 쪽에 제재를 하고 피해를 본 사람이 보상받을 기준이 생긴다","correct":true},{"t":"공장과 마을이 서로 탓만 하게 된다","mis":"SO5-1-u3-X07"},{"t":"물고기가 저절로 돌아온다","mis":"SO5-1-u3-X07"},{"t":"마을 사람들이 이사를 가야 한다","mis":"SO5-1-u3-X09"}],"explanation":["기준이 있으면 다툼이 풀려요.","버린 쪽은 제재를 받아요.","피해는 보상받아요."],"asset":{"type":"passage","lines":["어느 공장이 몇 달 동안 폐수를 하천에 몰래 흘려보냈다.","하천의 물고기가 죽고 둘레에서 심한 냄새가 났다.","하천 아래 마을 사람들은 마실 물을 걱정하고 있다."],"title":"어느 하천 이야기(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_challenge#8','soc',5,1,'u3','L03','g5_1_soc_u3_L03_challenge','lesson_challenge','SO5-1-u3-C6',4,'mc','auto','법의 역할을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u3-X08','SO5-1-u3-X26']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C6","difficulty":4,"kind":"mc","stem":"법의 역할을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"개인의 권리를 보호하고 사회 질서를 유지해 우리가 안전하게 살아가게 한다","correct":true},{"t":"개인의 권리만 보호하고 사회 질서와는 관계없다","mis":"SO5-1-u3-X08"},{"t":"사회 질서만 지키고 개인은 지키지 않는다","mis":"SO5-1-u3-X08"},{"t":"법 이름을 외우게 해 생활을 편하게 한다","mis":"SO5-1-u3-X26"}],"explanation":["한 사람을 지켜요.","모두의 질서도 지켜요.","그래서 안전하게 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_challenge#9','soc',5,1,'u3','L03','g5_1_soc_u3_L03_challenge','lesson_challenge','SO5-1-u3-C7',4,'mc','auto','법이 하는 일 여섯을 두 갈래로 나누어 보면 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X08','SO5-1-u3-X07']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C7","difficulty":4,"kind":"mc","stem":"법이 하는 일 여섯을 두 갈래로 나누어 보면 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"법은 한 사람의 권리와 모두의 질서를 함께 지키고 있다","correct":true},{"t":"법은 한 가지 일만 한다","mis":"SO5-1-u3-X08"},{"t":"개인 정보와 경제 질서는 같은 역할이다","mis":"SO5-1-u3-X08"},{"t":"법이 하는 일은 서로 아무 관계가 없다","mis":"SO5-1-u3-X07"}],"explanation":["㉠·㉢·㉤은 권리 보호예요.","㉡·㉣·㉥은 질서 유지예요.","둘을 함께 해요."],"asset":{"type":"passage","lines":["㉠ 개인 사이의 다툼을 재판으로 해결한다.","㉡ 어린이 보호 구역에서 자동차가 천천히 달리게 한다.","㉢ 전화번호 대신 개인 안심 번호를 쓰게 한다.","㉣ 공정하게 물건을 사고팔도록 한다.","㉤ 불이 났을 때 생명과 재산을 지킨다.","㉥ 거리를 깨끗하게 유지한다."],"title":"법이 하는 일 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L03_challenge#10','soc',5,1,'u3','L03','g5_1_soc_u3_L03_challenge','lesson_challenge','SO5-1-u3-C5',4,'essay','teacher','법이 필요한 까닭을 쓰고, 법의 두 역할을 각각 생활 속 예를 하나씩 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u3-C5","difficulty":4,"kind":"essay","stem":"법이 필요한 까닭을 쓰고, 법의 두 역할을 각각 생활 속 예를 하나씩 들어 쓰세요.","answer_guide":{"answer":"예: 법은 문제가 생겼을 때 사람들 사이의 갈등이나 다툼을 해결하는 기준이 되므로 필요하다. 법은 개인의 권리를 보호하는데, 동의 없이 사진을 올려 초상권을 침해당한 사람이 손해 배상을 받게 했다. 또 사회 질서를 유지하는데, 어린이 보호 구역에서 자동차가 천천히 달리게 해 사고를 예방한다.","scoring_points":["법이 필요한 까닭을 썼는가","개인의 권리 보호와 예를 썼는가","사회 질서 유지와 예를 썼는가"]},"explanation":["기준이 되는 까닭을 써요.","권리 보호의 예를 들어요.","질서 유지의 예를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_basic#1','soc',5,1,'u3','L04','g5_1_soc_u3_L04_basic','lesson_basic','SO5-1-u3-C8',1,'mc','auto','사람이 태어나면서 당연히 가지는, 누구나 누려야 할 기본적인 권리를 무엇이라고 하나요?',ARRAY['SO5-1-u3-X02','SO5-1-u3-X08']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C8","difficulty":1,"kind":"mc","stem":"사람이 태어나면서 당연히 가지는, 누구나 누려야 할 기본적인 권리를 무엇이라고 하나요?","options":[{"t":"인권","correct":true},{"t":"제재","mis":"SO5-1-u3-X02"},{"t":"규범","mis":"SO5-1-u3-X02"},{"t":"재판","mis":"SO5-1-u3-X08"}],"explanation":["사람이라면 누구나 가져요.","태어나면서부터 가져요.","인권이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_basic#2','soc',5,1,'u3','L04','g5_1_soc_u3_L04_basic','lesson_basic','SO5-1-u3-C9',1,'sa','auto','우리나라의 최고법으로, 국민의 자유와 권리를 보장하는 내용을 담은 법은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u3-C9","difficulty":1,"kind":"sa","stem":"우리나라의 최고법으로, 국민의 자유와 권리를 보장하는 내용을 담은 법은 무엇인가요? 두 글자로 쓰세요.","answer":["헌법"],"explanation":["가장 높은 자리의 법이에요.","인권을 보장하는 내용을 담았어요.","헌법이에요."],"mis":"SO5-1-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_basic#3','soc',5,1,'u3','L04','g5_1_soc_u3_L04_basic','lesson_basic','SO5-1-u3-C8',1,'ox','auto','인권은 어른이 되어야 비로소 생기는 권리예요.',ARRAY['SO5-1-u3-X10']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C8","difficulty":1,"kind":"ox","stem":"인권은 어른이 되어야 비로소 생기는 권리예요.","answer":"X","reason_options":[{"t":"인권은 태어나는 순간부터 누구에게나 주어지기 때문에","correct":true},{"t":"어린이는 아직 사람으로서의 권리가 없기 때문에","mis":"SO5-1-u3-X10"}],"mis":"SO5-1-u3-X10","explanation":["태어나는 순간부터예요.","나이와 관계없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_basic#4','soc',5,1,'u3','L04','g5_1_soc_u3_L04_basic','lesson_basic','SO5-1-u3-C8',1,'mc','auto','일상생활에서 우리가 누리는 인권의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X16','SO5-1-u3-X14']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C8","difficulty":1,"kind":"mc","stem":"일상생활에서 우리가 누리는 인권의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"아플 때 병원에서 치료를 받는다","correct":true},{"t":"친구의 일기장을 몰래 본다","mis":"SO5-1-u3-X16"},{"t":"싫어하는 별명을 부른다","mis":"SO5-1-u3-X14"},{"t":"줄을 무시하고 먼저 들어간다","mis":"SO5-1-u3-X14"}],"explanation":["치료받는 것도 인권이에요.","교육받고 쉬는 것도요.","인간다운 삶을 위해 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_basic#5','soc',5,1,'u3','L04','g5_1_soc_u3_L04_basic','lesson_basic','SO5-1-u3-C8',2,'mc','auto','인권의 특징으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X10']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C8","difficulty":2,"kind":"mc","stem":"인권의 특징으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"열심히 노력한 사람에게만 주어진다","correct":true},{"t":"태어나는 순간부터 주어진다","mis":"SO5-1-u3-X10"},{"t":"성별·나이·국적과 관계없이 누구나 누린다","mis":"SO5-1-u3-X10"},{"t":"다른 사람이 함부로 빼앗을 수 없다","mis":"SO5-1-u3-X10"}],"explanation":["인권은 차별 없이 주어져요.","노력의 대가가 아니에요.","그래서 첫째 보기가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_basic#6','soc',5,1,'u3','L04','g5_1_soc_u3_L04_basic','lesson_basic','SO5-1-u3-C9',2,'mc','auto','헌법에 기본적인 인권을 정해 놓은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X11','SO5-1-u3-X26']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C9","difficulty":2,"kind":"mc","stem":"헌법에 기본적인 인권을 정해 놓은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"국가 권력이 개인의 인권을 함부로 침해할 수 없도록 하려고","correct":true},{"t":"법의 수를 늘리려고","mis":"SO5-1-u3-X11"},{"t":"어른들만 읽게 하려고","mis":"SO5-1-u3-X11"},{"t":"글을 길게 쓰려고","mis":"SO5-1-u3-X26"}],"explanation":["가장 힘이 센 쪽은 국가예요.","국가도 인권을 함부로 못 건드려요.","그래서 최고법에 정했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_basic#7','soc',5,1,'u3','L04','g5_1_soc_u3_L04_basic','lesson_basic','SO5-1-u3-C9',2,'mc','auto','생활 속 다섯 장면 가운데 「국가의 정치에 참여하는 모습」은 어느 것인가요?',ARRAY['SO5-1-u3-X12']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C9","difficulty":2,"kind":"mc","stem":"생활 속 다섯 장면 가운데 「국가의 정치에 참여하는 모습」은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"SO5-1-u3-X12"},{"t":"㉰","mis":"SO5-1-u3-X12"},{"t":"㉲","mis":"SO5-1-u3-X12"}],"explanation":["선거 날 투표를 해요.","나라의 일을 함께 정해요.","정치 참여예요."],"asset":{"type":"passage","lines":["㉮ 어른이 되어 선거 날 투표를 한다.","㉯ 살고 싶은 동네로 이사를 간다.","㉰ 남자든 여자든 같은 일에 같은 대우를 받는다.","㉱ 억울한 일을 겪어 재판을 받는다.","㉲ 모든 어린이가 학교에서 교육을 받는다."],"title":"생활 속 다섯 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_basic#8','soc',5,1,'u3','L04','g5_1_soc_u3_L04_basic','lesson_basic','SO5-1-u3-C9',2,'mc','auto','생활 속 다섯 장면 가운데 ㉯와 이어지는 헌법의 인권 보장 모습은 어느 것인가요?',ARRAY['SO5-1-u3-X12']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C9","difficulty":2,"kind":"mc","stem":"생활 속 다섯 장면 가운데 ㉯와 이어지는 헌법의 인권 보장 모습은 어느 것인가요?","options":[{"t":"국가의 간섭 없이 자유롭게 생각하고 행동하기","correct":true},{"t":"국가의 정치에 참여하기","mis":"SO5-1-u3-X12"},{"t":"권리가 침해되었을 때 국가에 요구하기","mis":"SO5-1-u3-X12"},{"t":"더 나은 삶을 국가에 요구하기","mis":"SO5-1-u3-X12"}],"explanation":["살고 싶은 곳으로 이사를 가요.","나라가 막지 않아요.","자유롭게 행동하는 모습이에요."],"asset":{"type":"passage","lines":["㉮ 어른이 되어 선거 날 투표를 한다.","㉯ 살고 싶은 동네로 이사를 간다.","㉰ 남자든 여자든 같은 일에 같은 대우를 받는다.","㉱ 억울한 일을 겪어 재판을 받는다.","㉲ 모든 어린이가 학교에서 교육을 받는다."],"title":"생활 속 다섯 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_basic#9','soc',5,1,'u3','L04','g5_1_soc_u3_L04_basic','lesson_basic','SO5-1-u3-C9',2,'mc','auto','생활 속 다섯 장면 가운데 ㉰와 이어지는 헌법의 인권 보장 모습은 어느 것인가요?',ARRAY['SO5-1-u3-X12']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C9","difficulty":2,"kind":"mc","stem":"생활 속 다섯 장면 가운데 ㉰와 이어지는 헌법의 인권 보장 모습은 어느 것인가요?","options":[{"t":"차별받지 않고 동등하게 대우받기","correct":true},{"t":"국가의 정치에 참여하기","mis":"SO5-1-u3-X12"},{"t":"자유롭게 생각하고 행동하기","mis":"SO5-1-u3-X12"},{"t":"권리가 침해되었을 때 국가에 요구하기","mis":"SO5-1-u3-X12"}],"explanation":["남녀가 같은 대우를 받아요.","차별이 없어요.","동등한 대우예요."],"asset":{"type":"passage","lines":["㉮ 어른이 되어 선거 날 투표를 한다.","㉯ 살고 싶은 동네로 이사를 간다.","㉰ 남자든 여자든 같은 일에 같은 대우를 받는다.","㉱ 억울한 일을 겪어 재판을 받는다.","㉲ 모든 어린이가 학교에서 교육을 받는다."],"title":"생활 속 다섯 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_basic#10','soc',5,1,'u3','L04','g5_1_soc_u3_L04_basic','lesson_basic','SO5-1-u3-C8',3,'error','auto','인권을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X10']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C8","difficulty":3,"kind":"error","stem":"인권을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「다른 나라에서 온 사람은 우리나라에서 인권을 누릴 수 없어.」","correct":true,"mis_target":"SO5-1-u3-X10"},{"t":"수빈 — 「인권은 누구도 함부로 빼앗을 수 없어.」","mis":"SO5-1-u3-X10"},{"t":"지오 — 「인권은 성별과 나이에 관계없이 누구나 누려.」","mis":"SO5-1-u3-X10"}],"explanation":["국적과 관계없어요.","누구나 누려요.","태린이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_challenge#1','soc',5,1,'u3','L04','g5_1_soc_u3_L04_challenge','lesson_challenge','SO5-1-u3-C9',2,'match','auto','생활 속 장면과 헌법이 보장하는 인권의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u3-C9","difficulty":2,"kind":"match","stem":"생활 속 장면과 헌법이 보장하는 인권의 모습을 알맞게 이으세요.","pairs":[{"l":"㉮ 투표하기","r":"정치에 참여하기"},{"l":"㉯ 이사 가기","r":"자유롭게 행동하기"},{"l":"㉱ 재판 받기","r":"침해되면 국가에 요구하기"},{"l":"㉲ 교육받기","r":"더 나은 삶을 요구하기"}],"mis":"SO5-1-u3-X12","explanation":["투표는 정치 참여예요.","이사는 자유예요.","재판은 바로잡기, 교육은 더 나은 삶이에요."],"asset":{"type":"passage","lines":["㉮ 어른이 되어 선거 날 투표를 한다.","㉯ 살고 싶은 동네로 이사를 간다.","㉰ 남자든 여자든 같은 일에 같은 대우를 받는다.","㉱ 억울한 일을 겪어 재판을 받는다.","㉲ 모든 어린이가 학교에서 교육을 받는다."],"title":"생활 속 다섯 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_challenge#2','soc',5,1,'u3','L04','g5_1_soc_u3_L04_challenge','lesson_challenge','SO5-1-u3-C8',2,'mc','auto','살아가는 데 꼭 필요한 것을 말한 세 친구의 말에 공통으로 담긴 것은 어느 것인가요?',ARRAY['SO5-1-u3-X10']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C8","difficulty":2,"kind":"mc","stem":"살아가는 데 꼭 필요한 것을 말한 세 친구의 말에 공통으로 담긴 것은 어느 것인가요?","options":[{"t":"사람이라면 누구나 누려야 할 인권","correct":true},{"t":"돈을 내야 살 수 있는 물건","mis":"SO5-1-u3-X10"},{"t":"시험을 잘 본 사람이 받는 상","mis":"SO5-1-u3-X10"},{"t":"어른만 가질 수 있는 권리","mis":"SO5-1-u3-X10"}],"explanation":["집·음식·평등한 대우예요.","누구에게나 필요해요.","모두 인권이에요."],"asset":{"type":"speech","turns":[{"who":"민호","text":"살아가려면 편히 쉬고 잘 수 있는 집이 있어야 해."},{"who":"라온","text":"배고플 때 먹을 음식도 필요해."},{"who":"지유","text":"누구에게나 차별받지 않고 똑같이 대우받는 것도!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_challenge#3','soc',5,1,'u3','L04','g5_1_soc_u3_L04_challenge','lesson_challenge','SO5-1-u3-C9',3,'mc','auto','헌법이 「최고법」이라는 말의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X11','SO5-1-u3-X26']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C9","difficulty":3,"kind":"mc","stem":"헌법이 「최고법」이라는 말의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라를 운영하는 원칙과 국민의 권리를 담아 다른 법들의 바탕이 된다","correct":true},{"t":"가장 최근에 만든 법이다","mis":"SO5-1-u3-X11"},{"t":"글자 수가 가장 많은 법이다","mis":"SO5-1-u3-X26"},{"t":"어른들만 지키는 법이다","mis":"SO5-1-u3-X11"}],"explanation":["나라 운영의 원칙을 담았어요.","국민의 권리도 담았어요.","모든 법의 바탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_challenge#4','soc',5,1,'u3','L04','g5_1_soc_u3_L04_challenge','lesson_challenge','SO5-1-u3-C9',3,'mc','auto','인권 소책자 4면의 제목과 어울리는 생활 장면은 어느 것인가요?',ARRAY['SO5-1-u3-X12']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C9","difficulty":3,"kind":"mc","stem":"인권 소책자 4면의 제목과 어울리는 생활 장면은 어느 것인가요?","options":[{"t":"억울한 일을 겪은 사람이 재판을 받는다","correct":true},{"t":"어른이 선거 날 투표를 한다","mis":"SO5-1-u3-X12"},{"t":"살고 싶은 동네로 이사를 간다","mis":"SO5-1-u3-X12"},{"t":"모든 어린이가 학교에서 배운다","mis":"SO5-1-u3-X12"}],"explanation":["4면은 침해되면 바로잡아 달라는 면이에요.","재판을 받는 장면이에요.","국가에 요구해요."],"asset":{"type":"passage","lines":["1면 — 차별받지 않고 동등하게 대우받아요.","2면 — 국가의 간섭 없이 자유롭게 생각하고 행동해요.","3면 — 나라의 정치에 참여할 수 있어요.","4면 — 권리가 침해되면 국가에 바로잡아 달라고 해요.","5면 — 더 나은 삶을 살 수 있도록 국가에 요구해요."],"title":"인권 소책자 다섯 면의 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_challenge#5','soc',5,1,'u3','L04','g5_1_soc_u3_L04_challenge','lesson_challenge','SO5-1-u3-C9',3,'mc','auto','인권 소책자 한 면에 담을 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X12']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C9","difficulty":3,"kind":"mc","stem":"인권 소책자 한 면에 담을 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구의 시험 점수","correct":true},{"t":"면의 제목","mis":"SO5-1-u3-X12"},{"t":"헌법에 담긴 인권","mis":"SO5-1-u3-X12"},{"t":"인권이 실제 생활에 적용된 모습","mis":"SO5-1-u3-X12"}],"explanation":["소책자에는 인권을 담아요.","생활 모습과 그림도 담아요.","남의 점수는 담지 않아요."],"asset":{"type":"passage","lines":["1면 — 차별받지 않고 동등하게 대우받아요.","2면 — 국가의 간섭 없이 자유롭게 생각하고 행동해요.","3면 — 나라의 정치에 참여할 수 있어요.","4면 — 권리가 침해되면 국가에 바로잡아 달라고 해요.","5면 — 더 나은 삶을 살 수 있도록 국가에 요구해요."],"title":"인권 소책자 다섯 면의 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_challenge#6','soc',5,1,'u3','L04','g5_1_soc_u3_L04_challenge','lesson_challenge','SO5-1-u3-C9',3,'ox','auto','헌법에 담긴 인권은 책 속에만 있고 우리 생활에서는 찾아보기 어려워요.',ARRAY['SO5-1-u3-X12']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C9","difficulty":3,"kind":"ox","stem":"헌법에 담긴 인권은 책 속에만 있고 우리 생활에서는 찾아보기 어려워요.","answer":"X","reason_options":[{"t":"투표·이사·교육처럼 우리 주변에서 다양한 모습으로 보장되기 때문에","correct":true},{"t":"헌법은 생활과 관계없는 내용만 담고 있기 때문에","mis":"SO5-1-u3-X12"}],"mis":"SO5-1-u3-X12","explanation":["생활 속 다섯 장면을 보았어요.","주변 곳곳에 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 어른이 되어 선거 날 투표를 한다.","㉯ 살고 싶은 동네로 이사를 간다.","㉰ 남자든 여자든 같은 일에 같은 대우를 받는다.","㉱ 억울한 일을 겪어 재판을 받는다.","㉲ 모든 어린이가 학교에서 교육을 받는다."],"title":"생활 속 다섯 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_challenge#7','soc',5,1,'u3','L04','g5_1_soc_u3_L04_challenge','lesson_challenge','SO5-1-u3-C9',3,'error','auto','헌법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X11']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C9","difficulty":3,"kind":"error","stem":"헌법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유찬 — 「국가는 힘이 세니까 필요하면 국민의 인권을 마음대로 줄여도 돼.」","correct":true,"mis_target":"SO5-1-u3-X11"},{"t":"소율 — 「헌법은 국가 권력이 인권을 함부로 침해하지 못하게 해.」","mis":"SO5-1-u3-X11"},{"t":"민재 — 「헌법은 우리나라의 최고법이야.」","mis":"SO5-1-u3-X11"}],"explanation":["국가도 인권을 함부로 못 줄여요.","헌법이 막아 줘요.","유찬이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_challenge#8','soc',5,1,'u3','L04','g5_1_soc_u3_L04_challenge','lesson_challenge','SO5-1-u3-C9',4,'mc','auto','헌법에 담긴 인권을 직접 찾아보는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X26','SO5-1-u3-X06','SO5-1-u3-X11']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C9","difficulty":4,"kind":"mc","stem":"헌법에 담긴 인권을 직접 찾아보는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"국가 법령 정보 누리집에서 헌법을 검색하거나 책을 찾고 어른께 여쭤본다","correct":true},{"t":"조항 번호만 모두 외운다","mis":"SO5-1-u3-X26"},{"t":"친구가 말해 준 것만 믿는다","mis":"SO5-1-u3-X06"},{"t":"헌법은 어른만 볼 수 있어 찾지 않는다","mis":"SO5-1-u3-X11"}],"explanation":["누리집에서 찾아요.","책과 어른께 여쭙기도 해요.","외우기보다 찾아 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_challenge#9','soc',5,1,'u3','L04','g5_1_soc_u3_L04_challenge','lesson_challenge','SO5-1-u3-C8',4,'mc','auto','인권 소책자를 만들며 알게 된 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X10','SO5-1-u3-X11']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C8","difficulty":4,"kind":"mc","stem":"인권 소책자를 만들며 알게 된 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"헌법에 담긴 인권은 우리 주변에서 다양한 모습으로 보장되어 누구나 누린다","correct":true},{"t":"인권은 몇몇 사람만 누린다","mis":"SO5-1-u3-X10"},{"t":"헌법에는 인권과 상관없는 내용만 있다","mis":"SO5-1-u3-X11"},{"t":"인권은 노력해서 얻는 상이다","mis":"SO5-1-u3-X10"}],"explanation":["면마다 다른 인권이 짝을 이뤘어요.","생활 곳곳에 있어요.","누구나 누려요."],"asset":{"type":"passage","lines":["1면 — 차별받지 않고 동등하게 대우받아요.","2면 — 국가의 간섭 없이 자유롭게 생각하고 행동해요.","3면 — 나라의 정치에 참여할 수 있어요.","4면 — 권리가 침해되면 국가에 바로잡아 달라고 해요.","5면 — 더 나은 삶을 살 수 있도록 국가에 요구해요."],"title":"인권 소책자 다섯 면의 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L04_challenge#10','soc',5,1,'u3','L04','g5_1_soc_u3_L04_challenge','lesson_challenge','SO5-1-u3-C9',4,'essay','teacher','인권의 뜻과 특징 한 가지를 쓰고, 헌법에 인권을 정해 둔 까닭과 헌법이 보장하는 인권이 생활에 나타난 모습 하나를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u3-C9","difficulty":4,"kind":"essay","stem":"인권의 뜻과 특징 한 가지를 쓰고, 헌법에 인권을 정해 둔 까닭과 헌법이 보장하는 인권이 생활에 나타난 모습 하나를 쓰세요.","answer_guide":{"answer":"예: 인권은 사람이 태어나면서 당연히 가지는, 누구나 누려야 할 기본적인 권리이고, 성별·나이·국적에 관계없이 차별 없이 주어진다. 국가 권력이 개인의 인권을 함부로 침해할 수 없도록 최고법인 헌법에 정해 두었다. 모든 어린이가 학교에서 교육을 받는 것이 헌법이 보장하는 인권의 모습이다.","scoring_points":["인권의 뜻과 특징을 썼는가","헌법에 정한 까닭을 썼는가","생활 속 모습을 썼는가"]},"explanation":["뜻과 특징을 써요.","국가 권력을 막는 까닭을 써요.","생활 장면을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_basic#1','soc',5,1,'u3','L05','g5_1_soc_u3_L05_basic','lesson_basic','SO5-1-u3-C10',1,'mc','auto','친구의 사진을 허락 없이 공유하는 것은 무엇을 침해하는 일인가요?',ARRAY['SO5-1-u3-X05','SO5-1-u3-X12']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C10","difficulty":1,"kind":"mc","stem":"친구의 사진을 허락 없이 공유하는 것은 무엇을 침해하는 일인가요?","options":[{"t":"초상권","correct":true},{"t":"저작권","mis":"SO5-1-u3-X05"},{"t":"선거권","mis":"SO5-1-u3-X12"},{"t":"재산권","mis":"SO5-1-u3-X05"}],"explanation":["얼굴이 나온 사진이에요.","허락 없이 쓰면 안 돼요.","초상권 침해예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_basic#2','soc',5,1,'u3','L05','g5_1_soc_u3_L05_basic','lesson_basic','SO5-1-u3-C10',1,'mc','auto','인터넷에 다른 사람을 비방하는 글을 올리면 법을 어기는 까닭은 어느 것인가요?',ARRAY['SO5-1-u3-X13']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C10","difficulty":1,"kind":"mc","stem":"인터넷에 다른 사람을 비방하는 글을 올리면 법을 어기는 까닭은 어느 것인가요?","options":[{"t":"그 사람의 명예를 훼손하기 때문에","correct":true},{"t":"글씨가 작아지기 때문에","mis":"SO5-1-u3-X13"},{"t":"인터넷이 느려지기 때문에","mis":"SO5-1-u3-X13"},{"t":"글이 길어지기 때문에","mis":"SO5-1-u3-X13"}],"explanation":["헐뜯는 말은 상처가 돼요.","그 사람의 이름과 명예를 해쳐요.","바르고 고운 말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_basic#3','soc',5,1,'u3','L05','g5_1_soc_u3_L05_basic','lesson_basic','SO5-1-u3-C10',1,'ox','auto','횡단보도에서 보행 신호를 지키지 않으면 나뿐 아니라 다른 사람의 안전도 위협할 수 있어요.',ARRAY['SO5-1-u3-X13']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C10","difficulty":1,"kind":"ox","stem":"횡단보도에서 보행 신호를 지키지 않으면 나뿐 아니라 다른 사람의 안전도 위협할 수 있어요.","answer":"O","reason_options":[{"t":"갑자기 멈춘 차나 피하려는 사람까지 위험해지기 때문에","correct":true},{"t":"나만 다치고 다른 사람과는 관계없기 때문에","mis":"SO5-1-u3-X13"}],"mis":"SO5-1-u3-X13","explanation":["차와 사람이 함께 다녀요.","모두가 위험해져요.","파란불에 건너요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_basic#4','soc',5,1,'u3','L05','g5_1_soc_u3_L05_basic','lesson_basic','SO5-1-u3-C11',1,'sa','auto','사람들에게 무언가의 중요성을 알리고 함께 참여하도록 하는 활동을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO5-1-u3-C11","difficulty":1,"kind":"sa","stem":"사람들에게 무언가의 중요성을 알리고 함께 참여하도록 하는 활동을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["캠페인"],"explanation":["함께하자고 알려요.","해시태그를 붙여 올리기도 해요.","캠페인이에요."],"mis":"SO5-1-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_basic#5','soc',5,1,'u3','L05','g5_1_soc_u3_L05_basic','lesson_basic','SO5-1-u3-C10',2,'mc','auto','법을 어기는 세 장면에서 ㉢을 바르게 고친 행동은 어느 것인가요?',ARRAY['SO5-1-u3-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C10","difficulty":2,"kind":"mc","stem":"법을 어기는 세 장면에서 ㉢을 바르게 고친 행동은 어느 것인가요?","options":[{"t":"사진을 올리기 전에 친구에게 먼저 허락을 받는다","correct":true},{"t":"사진을 더 많이 올린다","mis":"SO5-1-u3-X13"},{"t":"얼굴만 작게 해서 올린다","mis":"SO5-1-u3-X13"},{"t":"다른 친구 사진으로 바꿔 올린다","mis":"SO5-1-u3-X13"}],"explanation":["허락 없이 올리면 초상권 침해예요.","먼저 물어봐요.","허락을 받고 올려요."],"asset":{"type":"passage","lines":["㉠ 누리집 게시판에 친구를 헐뜯는 글을 올렸다.","㉡ 빨간불인데 차가 없다며 횡단보도를 건넜다.","㉢ 친구 사진을 허락 없이 단체 대화방에 올렸다."],"title":"법을 어기는 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_basic#6','soc',5,1,'u3','L05','g5_1_soc_u3_L05_basic','lesson_basic','SO5-1-u3-C10',2,'mc','auto','법을 지키는 태도가 중요한 까닭으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X13']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C10","difficulty":2,"kind":"mc","stem":"법을 지키는 태도가 중요한 까닭으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"상을 받을 수 있기 때문에","correct":true},{"t":"다른 사람에게 피해를 주지 않기 때문에","mis":"SO5-1-u3-X13"},{"t":"나와 다른 사람의 권리를 보호하기 때문에","mis":"SO5-1-u3-X13"},{"t":"모두가 조화롭고 안정된 삶을 누리기 때문에","mis":"SO5-1-u3-X13"}],"explanation":["법을 지키는 건 상 때문이 아니에요.","나와 우리 모두를 위해서예요.","그래서 첫째 보기가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_basic#7','soc',5,1,'u3','L05','g5_1_soc_u3_L05_basic','lesson_basic','SO5-1-u3-C11',2,'mc','auto','인권을 존중해야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C11","difficulty":2,"kind":"mc","stem":"인권을 존중해야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나의 권리가 소중한 만큼 다른 사람의 권리도 소중하기 때문에","correct":true},{"t":"내 권리만 지키면 되기 때문에","mis":"SO5-1-u3-X14"},{"t":"힘이 센 사람의 권리가 더 크기 때문에","mis":"SO5-1-u3-X14"},{"t":"나이가 많을수록 권리가 커지기 때문에","mis":"SO5-1-u3-X14"}],"explanation":["인권은 모두의 권리예요.","나만큼 남도 소중해요.","그래서 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_basic#8','soc',5,1,'u3','L05','g5_1_soc_u3_L05_basic','lesson_basic','SO5-1-u3-C11',2,'mc','auto','인권을 존중하는 태도로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X14']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C11","difficulty":2,"kind":"mc","stem":"인권을 존중하는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"나와 생각이 다른 친구의 말도 끝까지 들어 준다","correct":true},{"t":"친구가 싫어하는 별명을 재미로 부른다","mis":"SO5-1-u3-X14"},{"t":"내 의견만 맞다고 밀어붙인다","mis":"SO5-1-u3-X14"},{"t":"나와 다른 친구는 모둠에서 뺀다","mis":"SO5-1-u3-X14"}],"explanation":["생각이 달라도 소중해요.","끝까지 들어 줘요.","존중하는 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_basic#9','soc',5,1,'u3','L05','g5_1_soc_u3_L05_basic','lesson_basic','SO5-1-u3-C11',2,'mc','auto','캠페인 게시판에서 하랑이가 은채에게 한 말은 캠페인의 어떤 모습인가요?',ARRAY['SO5-1-u3-X15']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C11","difficulty":2,"kind":"mc","stem":"캠페인 게시판에서 하랑이가 은채에게 한 말은 캠페인의 어떤 모습인가요?","options":[{"t":"친구의 다짐에 공감하며 소통하는 모습","correct":true},{"t":"공감 수를 세어 순위를 정하는 모습","mis":"SO5-1-u3-X15"},{"t":"내 카드를 더 많이 올리려는 모습","mis":"SO5-1-u3-X15"},{"t":"친구 글씨를 고쳐 주는 모습","mis":"SO5-1-u3-X15"}],"explanation":["좋은 다짐이라고 했어요.","나도 함께한대요.","공감하고 소통해요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"#신호는_약속 — 저는 파란불에만 건너겠습니다."},{"who":"도현","text":"#다름도_소중해 — 생각이 달라도 끝까지 들을게요."},{"who":"하랑","text":"은채야, 좋은 다짐이야! 나도 함께할게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_basic#10','soc',5,1,'u3','L05','g5_1_soc_u3_L05_basic','lesson_basic','SO5-1-u3-C11',3,'error','auto','인권 존중 점검표를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X15','SO5-1-u3-X14']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C11","difficulty":3,"kind":"error","stem":"인권 존중 점검표를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규민 — 「점검표는 「예」를 가장 많이 받은 사람이 이기는 거야.」","correct":true,"mis_target":"SO5-1-u3-X15"},{"t":"아윤 — 「잘 못 지킨 칸은 어떻게 지킬지 함께 이야기하자.」","mis":"SO5-1-u3-X15"},{"t":"로하 — 「친구의 권리도 내 권리만큼 소중히 여겨야 해.」","mis":"SO5-1-u3-X14"}],"explanation":["점검표는 겨루기가 아니에요.","못 지킨 부분을 함께 고민해요.","규민이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_challenge#1','soc',5,1,'u3','L05','g5_1_soc_u3_L05_challenge','lesson_challenge','SO5-1-u3-C10',2,'match','auto','법을 어기는 세 장면과 바르게 고친 행동을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u3-C10","difficulty":2,"kind":"match","stem":"법을 어기는 세 장면과 바르게 고친 행동을 알맞게 이으세요.","pairs":[{"l":"㉠ 헐뜯는 글","r":"바르고 고운 말 쓰기"},{"l":"㉡ 빨간불에 건너기","r":"파란불이 켜지면 건너기"},{"l":"㉢ 허락 없는 사진","r":"먼저 친구에게 허락 받기"}],"mis":"SO5-1-u3-X13","explanation":["비방 대신 고운 말이에요.","신호를 지켜요.","사진은 허락부터예요."],"asset":{"type":"passage","lines":["㉠ 누리집 게시판에 친구를 헐뜯는 글을 올렸다.","㉡ 빨간불인데 차가 없다며 횡단보도를 건넜다.","㉢ 친구 사진을 허락 없이 단체 대화방에 올렸다."],"title":"법을 어기는 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_challenge#2','soc',5,1,'u3','L05','g5_1_soc_u3_L05_challenge','lesson_challenge','SO5-1-u3-C10',2,'mc','auto','법을 어기는 세 장면에서 ㉡의 사람이 「차가 없었으니 괜찮다」고 했어요. 이 생각이 잘못된 까닭은 어느 것인가요?',ARRAY['SO5-1-u3-X01','SO5-1-u3-X13']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C10","difficulty":2,"kind":"mc","stem":"법을 어기는 세 장면에서 ㉡의 사람이 「차가 없었으니 괜찮다」고 했어요. 이 생각이 잘못된 까닭은 어느 것인가요?","options":[{"t":"언제 차가 올지 모르고 보는 사람도 따라 할 수 있어 모두의 안전을 위협하기 때문에","correct":true},{"t":"차가 없으면 법이 사라지기 때문에","mis":"SO5-1-u3-X01"},{"t":"신호등이 고장 나기 때문에","mis":"SO5-1-u3-X13"},{"t":"벌만 피하면 되기 때문에","mis":"SO5-1-u3-X13"}],"explanation":["차는 갑자기 올 수 있어요.","어린 동생이 따라 할 수도 있어요.","신호는 늘 지켜요."],"asset":{"type":"passage","lines":["㉠ 누리집 게시판에 친구를 헐뜯는 글을 올렸다.","㉡ 빨간불인데 차가 없다며 횡단보도를 건넜다.","㉢ 친구 사진을 허락 없이 단체 대화방에 올렸다."],"title":"법을 어기는 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_challenge#3','soc',5,1,'u3','L05','g5_1_soc_u3_L05_challenge','lesson_challenge','SO5-1-u3-C11',3,'mc','auto','캠페인을 할 때 해시태그(#)를 붙여 올리는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X15']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C11","difficulty":3,"kind":"mc","stem":"캠페인을 할 때 해시태그(#)를 붙여 올리는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 주제의 글을 쉽게 찾아 더 많은 사람이 함께 볼 수 있게 하려고","correct":true},{"t":"글을 길게 보이게 하려고","mis":"SO5-1-u3-X15"},{"t":"공감 수를 세어 순위를 정하려고","mis":"SO5-1-u3-X15"},{"t":"나만 알아볼 수 있게 하려고","mis":"SO5-1-u3-X15"}],"explanation":["#은 주제를 묶어 줘요.","많은 사람이 찾을 수 있어요.","함께 참여하게 돼요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"#신호는_약속 — 저는 파란불에만 건너겠습니다."},{"who":"도현","text":"#다름도_소중해 — 생각이 달라도 끝까지 들을게요."},{"who":"하랑","text":"은채야, 좋은 다짐이야! 나도 함께할게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_challenge#4','soc',5,1,'u3','L05','g5_1_soc_u3_L05_challenge','lesson_challenge','SO5-1-u3-C10',3,'mc','auto','과제에 다른 사람의 글을 넣으면서 출처를 밝히지 않았어요. 바른 태도로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X13']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C10","difficulty":3,"kind":"mc","stem":"과제에 다른 사람의 글을 넣으면서 출처를 밝히지 않았어요. 바른 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"어디에서 가져온 글인지 출처를 밝혀 적는다","correct":true},{"t":"들키지 않으면 괜찮다고 여긴다","mis":"SO5-1-u3-X13"},{"t":"글을 조금만 바꾸면 내 글이 된다고 여긴다","mis":"SO5-1-u3-X13"},{"t":"선생님만 모르면 된다고 여긴다","mis":"SO5-1-u3-X13"}],"explanation":["남이 만든 글이에요.","만든 사람의 권리를 지켜요.","출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_challenge#5','soc',5,1,'u3','L05','g5_1_soc_u3_L05_challenge','lesson_challenge','SO5-1-u3-C11',3,'ox','auto','힘이 센 친구의 권리가 약한 친구의 권리보다 더 커요.',ARRAY['SO5-1-u3-X14']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C11","difficulty":3,"kind":"ox","stem":"힘이 센 친구의 권리가 약한 친구의 권리보다 더 커요.","answer":"X","reason_options":[{"t":"인권은 누구에게나 똑같이 소중하기 때문에","correct":true},{"t":"힘이 셀수록 권리를 더 많이 가지기 때문에","mis":"SO5-1-u3-X14"}],"mis":"SO5-1-u3-X14","explanation":["권리는 힘으로 정하지 않아요.","누구에게나 같아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_challenge#6','soc',5,1,'u3','L05','g5_1_soc_u3_L05_challenge','lesson_challenge','SO5-1-u3-C10',3,'error','auto','법을 지키는 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X13']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C10","difficulty":3,"kind":"error","stem":"법을 지키는 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시후 — 「법은 벌을 안 받으려고 지키는 거니까 아무도 안 보면 안 지켜도 돼.」","correct":true,"mis_target":"SO5-1-u3-X13"},{"t":"하엘 — 「법을 지키면 다른 사람에게 피해를 주지 않아.」","mis":"SO5-1-u3-X13"},{"t":"도경 — 「법을 지키면 모두가 안정된 삶을 누려.」","mis":"SO5-1-u3-X13"}],"explanation":["법은 보는 사람이 없어도 지켜요.","모두를 위해서예요.","시후가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_challenge#7','soc',5,1,'u3','L05','g5_1_soc_u3_L05_challenge','lesson_challenge','SO5-1-u3-C11',3,'mc','auto','캠페인 게시판의 은채와 도현이 다짐에서 본받을 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X23','SO5-1-u3-X14','SO5-1-u3-X15']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C11","difficulty":3,"kind":"mc","stem":"캠페인 게시판의 은채와 도현이 다짐에서 본받을 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내가 생활에서 실제로 지킬 수 있는 일을 구체적으로 다짐했다","correct":true},{"t":"누구도 할 수 없는 큰일을 다짐했다","mis":"SO5-1-u3-X23"},{"t":"다른 친구가 지켜야 할 일만 적었다","mis":"SO5-1-u3-X14"},{"t":"공감을 많이 받으려고 짧게만 적었다","mis":"SO5-1-u3-X15"}],"explanation":["파란불에 건너기예요.","끝까지 들어 주기예요.","내가 할 수 있는 일이에요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"#신호는_약속 — 저는 파란불에만 건너겠습니다."},{"who":"도현","text":"#다름도_소중해 — 생각이 달라도 끝까지 들을게요."},{"who":"하랑","text":"은채야, 좋은 다짐이야! 나도 함께할게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_challenge#8','soc',5,1,'u3','L05','g5_1_soc_u3_L05_challenge','lesson_challenge','SO5-1-u3-C10',4,'mc','auto','법을 지키는 태도와 인권을 존중하는 태도의 관계를 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO5-1-u3-X13','SO5-1-u3-X14']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C10","difficulty":4,"kind":"mc","stem":"법을 지키는 태도와 인권을 존중하는 태도의 관계를 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"법을 지키면 남의 권리를 침해하지 않게 되어 인권 존중으로 이어진다","correct":true},{"t":"두 태도는 서로 아무 관계가 없다","mis":"SO5-1-u3-X13"},{"t":"법만 지키면 인권은 신경 쓰지 않아도 된다","mis":"SO5-1-u3-X14"},{"t":"인권을 존중하려면 법을 어겨도 된다","mis":"SO5-1-u3-X13"}],"explanation":["사진 허락은 법이자 존중이에요.","고운 말도 마찬가지예요.","둘이 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_challenge#9','soc',5,1,'u3','L05','g5_1_soc_u3_L05_challenge','lesson_challenge','SO5-1-u3-C11',4,'mc','auto','「인권 존중 점검표」를 가장 알맞게 쓰는 방법은 어느 것인가요?',ARRAY['SO5-1-u3-X15','SO5-1-u3-X14']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C11","difficulty":4,"kind":"mc","stem":"「인권 존중 점검표」를 가장 알맞게 쓰는 방법은 어느 것인가요?","options":[{"t":"잘 못 지킨 부분을 서로 이야기하고 어떻게 지킬지 함께 정해 실천한다","correct":true},{"t":"「예」의 개수를 세어 반 등수를 매긴다","mis":"SO5-1-u3-X15"},{"t":"점검표를 다 쓰면 바로 버린다","mis":"SO5-1-u3-X15"},{"t":"친구의 점검표만 고쳐 준다","mis":"SO5-1-u3-X14"}],"explanation":["개수가 중요하지 않아요.","함께 이야기해요.","실천으로 이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L05_challenge#10','soc',5,1,'u3','L05','g5_1_soc_u3_L05_challenge','lesson_challenge','SO5-1-u3-C10',4,'essay','teacher','법을 지키는 태도가 중요한 까닭 두 가지와 인권을 존중해야 하는 까닭을 쓰고, 캠페인에 올릴 나의 실천 다짐 한 문장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u3-C10","difficulty":4,"kind":"essay","stem":"법을 지키는 태도가 중요한 까닭 두 가지와 인권을 존중해야 하는 까닭을 쓰고, 캠페인에 올릴 나의 실천 다짐 한 문장을 쓰세요.","answer_guide":{"answer":"예: 법을 지키면 다른 사람에게 피해를 주지 않고, 나와 다른 사람의 권리를 보호할 수 있다. 인권은 모두가 누려야 할 권리이고 나의 권리가 소중한 만큼 다른 사람의 권리도 소중하므로 존중해야 한다. 다짐 — 저는 친구 사진을 올리기 전에 꼭 허락을 받겠습니다.","scoring_points":["법을 지키는 까닭 두 가지를 썼는가","인권을 존중하는 까닭을 썼는가","실천할 수 있는 다짐을 썼는가"]},"explanation":["까닭 둘을 써요.","나만큼 남도 소중해요.","내가 할 수 있는 다짐을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_basic#1','soc',5,1,'u3','L06','g5_1_soc_u3_L06_basic','lesson_basic','SO5-1-u3-C12',1,'mc','auto','성별·나이·신체적 특징·종교·국적 등으로 인권을 보호받지 못하는 것을 무엇이라고 하나요?',ARRAY['SO5-1-u3-X16']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C12","difficulty":1,"kind":"mc","stem":"성별·나이·신체적 특징·종교·국적 등으로 인권을 보호받지 못하는 것을 무엇이라고 하나요?","options":[{"t":"인권 침해","correct":true},{"t":"인권 존중","mis":"SO5-1-u3-X16"},{"t":"인권 교육","mis":"SO5-1-u3-X16"},{"t":"인권 보장","mis":"SO5-1-u3-X16"}],"explanation":["인권을 보호받지 못해요.","여러 까닭으로 일어나요.","인권 침해예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_basic#2','soc',5,1,'u3','L06','g5_1_soc_u3_L06_basic','lesson_basic','SO5-1-u3-C12',1,'mc','auto','동네에서 본 네 장면 가운데 ㉠에서 휠체어를 탄 사람이 들어가지 못한 까닭은 어느 것인가요?',ARRAY['SO5-1-u3-X18']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C12","difficulty":1,"kind":"mc","stem":"동네에서 본 네 장면 가운데 ㉠에서 휠체어를 탄 사람이 들어가지 못한 까닭은 어느 것인가요?","options":[{"t":"경사로가 없기 때문에","correct":true},{"t":"식당이 문을 닫았기 때문에","mis":"SO5-1-u3-X18"},{"t":"자리가 없기 때문에","mis":"SO5-1-u3-X18"},{"t":"음식이 다 팔렸기 때문에","mis":"SO5-1-u3-X18"}],"explanation":["계단뿐인 출입구예요.","휠체어가 오를 수 없어요.","시설 부족이에요."],"asset":{"type":"passage","lines":["㉠ 휠체어를 탄 사람이 계단뿐인 식당에 들어가지 못한다.","㉡ 단체 대화방에서 한 친구를 헐뜯는 말이 오간다.","㉢ 밤늦게까지 이어지는 공사장 소음에 잠을 못 잔다.","㉣ 친구들이 서로 생각이 달라도 끝까지 들어 준다."],"title":"동네에서 본 네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_basic#3','soc',5,1,'u3','L06','g5_1_soc_u3_L06_basic','lesson_basic','SO5-1-u3-C12',1,'ox','auto','단체 대화방에서 한 친구를 헐뜯는 말을 주고받는 것은 사이버 폭력으로 인권을 침해하는 일이에요.',ARRAY['SO5-1-u3-X16']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C12","difficulty":1,"kind":"ox","stem":"단체 대화방에서 한 친구를 헐뜯는 말을 주고받는 것은 사이버 폭력으로 인권을 침해하는 일이에요.","answer":"O","reason_options":[{"t":"온라인에서도 그 친구가 상처를 받고 인권을 보호받지 못하기 때문에","correct":true},{"t":"온라인 공간의 말은 장난이라 아무 상처도 주지 않기 때문에","mis":"SO5-1-u3-X16"}],"mis":"SO5-1-u3-X16","explanation":["온라인도 생활 공간이에요.","말로 상처를 줘요.","사이버 폭력이에요."],"asset":{"type":"passage","lines":["㉠ 휠체어를 탄 사람이 계단뿐인 식당에 들어가지 못한다.","㉡ 단체 대화방에서 한 친구를 헐뜯는 말이 오간다.","㉢ 밤늦게까지 이어지는 공사장 소음에 잠을 못 잔다.","㉣ 친구들이 서로 생각이 달라도 끝까지 들어 준다."],"title":"동네에서 본 네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_basic#4','soc',5,1,'u3','L06','g5_1_soc_u3_L06_basic','lesson_basic','SO5-1-u3-C12',1,'mc','auto','책상 서랍 속 일기장을 친구가 몰래 보는 일은 어떤 인권 침해인가요?',ARRAY['SO5-1-u3-X18']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C12","difficulty":1,"kind":"mc","stem":"책상 서랍 속 일기장을 친구가 몰래 보는 일은 어떤 인권 침해인가요?","options":[{"t":"사생활 침해","correct":true},{"t":"시설 부족","mis":"SO5-1-u3-X18"},{"t":"안전 문제","mis":"SO5-1-u3-X18"},{"t":"교통질서 위반","mis":"SO5-1-u3-X18"}],"explanation":["일기장은 나만의 것이에요.","몰래 보면 안 돼요.","사생활 침해예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_basic#5','soc',5,1,'u3','L06','g5_1_soc_u3_L06_basic','lesson_basic','SO5-1-u3-C12',2,'mc','auto','동네에서 본 네 장면 가운데 인권이 침해되는 모습이 아닌 것은 어느 것인가요?',ARRAY['SO5-1-u3-X16']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C12","difficulty":2,"kind":"mc","stem":"동네에서 본 네 장면 가운데 인권이 침해되는 모습이 아닌 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"SO5-1-u3-X16"},{"t":"㉡","mis":"SO5-1-u3-X16"},{"t":"㉢","mis":"SO5-1-u3-X16"}],"explanation":["㉠·㉡·㉢은 어려움을 겪어요.","㉣은 서로 존중해요.","존중은 인권을 지키는 모습이에요."],"asset":{"type":"passage","lines":["㉠ 휠체어를 탄 사람이 계단뿐인 식당에 들어가지 못한다.","㉡ 단체 대화방에서 한 친구를 헐뜯는 말이 오간다.","㉢ 밤늦게까지 이어지는 공사장 소음에 잠을 못 잔다.","㉣ 친구들이 서로 생각이 달라도 끝까지 들어 준다."],"title":"동네에서 본 네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_basic#6','soc',5,1,'u3','L06','g5_1_soc_u3_L06_basic','lesson_basic','SO5-1-u3-C12',2,'mc','auto','세 가지 사례 가운데 ㉮가 인권 침해인 까닭은 어느 것인가요?',ARRAY['SO5-1-u3-X18']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C12","difficulty":2,"kind":"mc","stem":"세 가지 사례 가운데 ㉮가 인권 침해인 까닭은 어느 것인가요?","options":[{"t":"외국인이라는 까닭으로 차별을 받았기 때문에","correct":true},{"t":"회사가 멀리 있기 때문에","mis":"SO5-1-u3-X18"},{"t":"일하는 시간이 짧기 때문에","mis":"SO5-1-u3-X18"},{"t":"월급날이 늦었기 때문에","mis":"SO5-1-u3-X18"}],"explanation":["똑같이 일했어요.","월급만 적게 받았어요.","국적으로 차별받았어요."],"asset":{"type":"passage","lines":["㉮ 다른 나라에서 온 사람이 똑같이 일하고 월급을 적게 받았다.","㉯ 집 앞에 높은 건물이 생겨 하루 종일 햇빛이 안 든다.","㉰ 쓰레기 냄새와 자동차 매연 때문에 늘 머리가 아프다."],"title":"세 가지 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_basic#7','soc',5,1,'u3','L06','g5_1_soc_u3_L06_basic','lesson_basic','SO5-1-u3-C12',2,'mc','auto','세 가지 사례 가운데 ㉯에서 보호받지 못한 권리는 어느 것인가요?',ARRAY['SO5-1-u3-X18']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C12","difficulty":2,"kind":"mc","stem":"세 가지 사례 가운데 ㉯에서 보호받지 못한 권리는 어느 것인가요?","options":[{"t":"햇빛을 받을 수 있는 권리","correct":true},{"t":"건물을 지을 수 있는 권리","mis":"SO5-1-u3-X18"},{"t":"이사를 갈 수 있는 권리","mis":"SO5-1-u3-X18"},{"t":"전등을 켤 수 있는 권리","mis":"SO5-1-u3-X18"}],"explanation":["높은 건물이 햇빛을 막아요.","하루 종일 어두워요.","햇빛을 받을 권리예요."],"asset":{"type":"passage","lines":["㉮ 다른 나라에서 온 사람이 똑같이 일하고 월급을 적게 받았다.","㉯ 집 앞에 높은 건물이 생겨 하루 종일 햇빛이 안 든다.","㉰ 쓰레기 냄새와 자동차 매연 때문에 늘 머리가 아프다."],"title":"세 가지 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_basic#8','soc',5,1,'u3','L06','g5_1_soc_u3_L06_basic','lesson_basic','SO5-1-u3-C12',2,'mc','auto','인권이 침해되었을 때 겪게 되는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X16','SO5-1-u3-X19']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C12","difficulty":2,"kind":"mc","stem":"인권이 침해되었을 때 겪게 되는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"잘못한 것이 없는데도 생활에서 어려움을 겪고 인간다운 삶을 누리지 못한다","correct":true},{"t":"더 많은 권리를 얻게 된다","mis":"SO5-1-u3-X16"},{"t":"아무런 어려움이 없다","mis":"SO5-1-u3-X16"},{"t":"법이 저절로 바뀐다","mis":"SO5-1-u3-X19"}],"explanation":["잘못이 없어도 어려움을 겪어요.","생활이 불편해져요.","인간다운 삶을 누리지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_basic#9','soc',5,1,'u3','L06','g5_1_soc_u3_L06_basic','lesson_basic','SO5-1-u3-C12',2,'ox','auto','텔레비전이나 신문 같은 미디어를 통해서도 인권 침해 사례를 만날 수 있어요.',ARRAY['SO5-1-u3-X17']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C12","difficulty":2,"kind":"ox","stem":"텔레비전이나 신문 같은 미디어를 통해서도 인권 침해 사례를 만날 수 있어요.","answer":"O","reason_options":[{"t":"임금 차별이나 악성 댓글처럼 미디어가 우리 주변의 침해를 알려 주기 때문에","correct":true},{"t":"미디어에는 인권과 관계없는 이야기만 나오기 때문에","mis":"SO5-1-u3-X17"}],"mis":"SO5-1-u3-X17","explanation":["뉴스에서 임금 차별을 봐요.","악성 댓글 기사도 있어요.","미디어로도 만나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_basic#10','soc',5,1,'u3','L06','g5_1_soc_u3_L06_basic','lesson_basic','SO5-1-u3-C12',3,'error','auto','인권 침해를 대하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X17','SO5-1-u3-X18']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C12","difficulty":3,"kind":"error","stem":"인권 침해를 대하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"해람 — 「인권 침해는 먼 나라에서나 일어나니까 우리 동네는 안 살펴봐도 돼.」","correct":true,"mis_target":"SO5-1-u3-X17"},{"t":"윤슬 — 「내가 한 행동 중에도 침해가 없었는지 떠올려 볼래.」","mis":"SO5-1-u3-X17"},{"t":"강준 — 「왜 인권 침해인지 까닭을 생각해 봐야 해.」","mis":"SO5-1-u3-X18"}],"explanation":["침해는 생활 곳곳에서 일어나요.","우리 동네도 살펴봐요.","해람이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_challenge#1','soc',5,1,'u3','L06','g5_1_soc_u3_L06_challenge','lesson_challenge','SO5-1-u3-C12',2,'match','auto','세 가지 사례와 보호받지 못한 권리를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u3-C12","difficulty":2,"kind":"match","stem":"세 가지 사례와 보호받지 못한 권리를 알맞게 이으세요.","pairs":[{"l":"㉮ 월급 차별","r":"차별받지 않고 동등하게 대우받을 권리"},{"l":"㉯ 높은 건물","r":"햇빛을 받을 수 있는 권리"},{"l":"㉰ 냄새와 매연","r":"건강하고 쾌적한 환경에서 생활할 권리"}],"mis":"SO5-1-u3-X18","explanation":["㉮는 국적 차별이에요.","㉯는 햇빛이에요.","㉰는 깨끗한 환경이에요."],"asset":{"type":"passage","lines":["㉮ 다른 나라에서 온 사람이 똑같이 일하고 월급을 적게 받았다.","㉯ 집 앞에 높은 건물이 생겨 하루 종일 햇빛이 안 든다.","㉰ 쓰레기 냄새와 자동차 매연 때문에 늘 머리가 아프다."],"title":"세 가지 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_challenge#2','soc',5,1,'u3','L06','g5_1_soc_u3_L06_challenge','lesson_challenge','SO5-1-u3-C12',2,'mc','auto','동네에서 본 네 장면 가운데 ㉢은 어떤 까닭의 인권 침해인가요?',ARRAY['SO5-1-u3-X18']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C12","difficulty":2,"kind":"mc","stem":"동네에서 본 네 장면 가운데 ㉢은 어떤 까닭의 인권 침해인가요?","options":[{"t":"안전 문제","correct":true},{"t":"사생활 침해","mis":"SO5-1-u3-X18"},{"t":"국적에 따른 차별","mis":"SO5-1-u3-X18"},{"t":"시설 부족","mis":"SO5-1-u3-X18"}],"explanation":["밤늦게까지 소음이 이어져요.","잠을 못 자 건강이 위협받아요.","안전 문제예요."],"asset":{"type":"passage","lines":["㉠ 휠체어를 탄 사람이 계단뿐인 식당에 들어가지 못한다.","㉡ 단체 대화방에서 한 친구를 헐뜯는 말이 오간다.","㉢ 밤늦게까지 이어지는 공사장 소음에 잠을 못 잔다.","㉣ 친구들이 서로 생각이 달라도 끝까지 들어 준다."],"title":"동네에서 본 네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_challenge#3','soc',5,1,'u3','L06','g5_1_soc_u3_L06_challenge','lesson_challenge','SO5-1-u3-C12',3,'mc','auto','세 가지 사례의 ㉰ 같은 일이 오래 이어질 때 생기기 쉬운 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X19','SO5-1-u3-X16']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C12","difficulty":3,"kind":"mc","stem":"세 가지 사례의 ㉰ 같은 일이 오래 이어질 때 생기기 쉬운 일로 알맞은 것은 어느 것인가요?","options":[{"t":"오염된 환경에서 아픈 사람이 늘어날 수 있다","correct":true},{"t":"공기가 저절로 맑아진다","mis":"SO5-1-u3-X19"},{"t":"아무 일도 생기지 않는다","mis":"SO5-1-u3-X16"},{"t":"냄새에 익숙해져 문제가 사라진다","mis":"SO5-1-u3-X19"}],"explanation":["냄새와 매연이 계속돼요.","건강이 나빠져요.","아픈 사람이 늘어요."],"asset":{"type":"passage","lines":["㉮ 다른 나라에서 온 사람이 똑같이 일하고 월급을 적게 받았다.","㉯ 집 앞에 높은 건물이 생겨 하루 종일 햇빛이 안 든다.","㉰ 쓰레기 냄새와 자동차 매연 때문에 늘 머리가 아프다."],"title":"세 가지 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_challenge#4','soc',5,1,'u3','L06','g5_1_soc_u3_L06_challenge','lesson_challenge','SO5-1-u3-C12',3,'mc','auto','키가 작다는 까닭으로 놀림을 받는 일이 인권 침해인 까닭은 어느 것인가요?',ARRAY['SO5-1-u3-X10','SO5-1-u3-X16','SO5-1-u3-X19']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C12","difficulty":3,"kind":"mc","stem":"키가 작다는 까닭으로 놀림을 받는 일이 인권 침해인 까닭은 어느 것인가요?","options":[{"t":"신체적 특징 때문에 존중받지 못하고 차별을 받기 때문에","correct":true},{"t":"키는 노력하면 바뀌기 때문에","mis":"SO5-1-u3-X10"},{"t":"놀림은 장난이라 괜찮기 때문에","mis":"SO5-1-u3-X16"},{"t":"놀린 사람만 불편하기 때문에","mis":"SO5-1-u3-X19"}],"explanation":["키는 신체적 특징이에요.","그 까닭으로 놀림받아요.","인권 침해예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_challenge#5','soc',5,1,'u3','L06','g5_1_soc_u3_L06_challenge','lesson_challenge','SO5-1-u3-C12',3,'mc','auto','지하철의 높낮이가 다양한 손잡이, 발로 여는 문, 승강기 점자 단추를 설치한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X21']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C12","difficulty":3,"kind":"mc","stem":"지하철의 높낮이가 다양한 손잡이, 발로 여는 문, 승강기 점자 단추를 설치한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"키가 작거나 장애가 있는 사람도 불편 없이 쓸 수 있게 인권을 보호하려고","correct":true},{"t":"보기 좋게 꾸미려고","mis":"SO5-1-u3-X21"},{"t":"물건값을 올리려고","mis":"SO5-1-u3-X21"},{"t":"어른만 쓰게 하려고","mis":"SO5-1-u3-X21"}],"explanation":["누구나 쓸 수 있게 만들었어요.","불편을 없애요.","인권을 보호하는 제품이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_challenge#6','soc',5,1,'u3','L06','g5_1_soc_u3_L06_challenge','lesson_challenge','SO5-1-u3-C12',3,'ox','auto','여자라는 까닭으로 함께 축구를 하지 못하게 하는 것은 인권 침해가 아니에요.',ARRAY['SO5-1-u3-X16']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C12","difficulty":3,"kind":"ox","stem":"여자라는 까닭으로 함께 축구를 하지 못하게 하는 것은 인권 침해가 아니에요.","answer":"X","reason_options":[{"t":"성별 때문에 함께할 기회를 빼앗는 차별이기 때문에","correct":true},{"t":"운동은 원래 남자만 하는 것이기 때문에","mis":"SO5-1-u3-X16"}],"mis":"SO5-1-u3-X16","explanation":["성별로 기회를 막았어요.","차별이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_challenge#7','soc',5,1,'u3','L06','g5_1_soc_u3_L06_challenge','lesson_challenge','SO5-1-u3-C12',3,'error','auto','동네에서 본 네 장면을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X19','SO5-1-u3-X18']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C12","difficulty":3,"kind":"error","stem":"동네에서 본 네 장면을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이든 — 「㉠은 휠체어를 탄 사람이 조심하지 않은 탓이야.」","correct":true,"mis_target":"SO5-1-u3-X19"},{"t":"채린 — 「㉠은 경사로가 없어 생긴 시설 부족이야.」","mis":"SO5-1-u3-X18"},{"t":"보민 — 「㉡은 사이버 폭력이야.」","mis":"SO5-1-u3-X18"}],"explanation":["잘못한 것이 없는 사람이에요.","시설이 부족했어요.","이든이가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 휠체어를 탄 사람이 계단뿐인 식당에 들어가지 못한다.","㉡ 단체 대화방에서 한 친구를 헐뜯는 말이 오간다.","㉢ 밤늦게까지 이어지는 공사장 소음에 잠을 못 잔다.","㉣ 친구들이 서로 생각이 달라도 끝까지 들어 준다."],"title":"동네에서 본 네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_challenge#8','soc',5,1,'u3','L06','g5_1_soc_u3_L06_challenge','lesson_challenge','SO5-1-u3-C12',4,'mc','auto','동네 살펴보기 판이 침해 자리를 미리 알려 주지 않고 하나하나 눌러 살펴보게 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X15','SO5-1-u3-X26','SO5-1-u3-X17']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C12","difficulty":4,"kind":"mc","stem":"동네 살펴보기 판이 침해 자리를 미리 알려 주지 않고 하나하나 눌러 살펴보게 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"일상생활 곳곳에서 인권 침해를 스스로 알아차리는 눈을 기르려고","correct":true},{"t":"자리를 누를 때마다 점수를 주려고","mis":"SO5-1-u3-X15"},{"t":"자리 이름을 외우게 하려고","mis":"SO5-1-u3-X26"},{"t":"침해 자리가 하나도 없어서","mis":"SO5-1-u3-X17"}],"explanation":["판은 답을 알려 주지 않았어요.","스스로 살펴봐야 해요.","알아차리는 눈이 첫걸음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_challenge#9','soc',5,1,'u3','L06','g5_1_soc_u3_L06_challenge','lesson_challenge','SO5-1-u3-C12',4,'mc','auto','「알아차리는 것이 첫걸음이다」라는 말에 맞는 행동으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X17','SO5-1-u3-X19']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C12","difficulty":4,"kind":"mc","stem":"「알아차리는 것이 첫걸음이다」라는 말에 맞는 행동으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내가 놀리는 말을 하거나 친구 물건을 허락 없이 본 적은 없는지 돌아본다","correct":true},{"t":"남이 침해한 일만 찾아 따진다","mis":"SO5-1-u3-X17"},{"t":"뉴스에 나온 일만 인권 침해로 여긴다","mis":"SO5-1-u3-X17"},{"t":"불편한 사람이 직접 말할 때까지 기다린다","mis":"SO5-1-u3-X19"}],"explanation":["내 행동도 살펴봐요.","놀림과 사생활도요.","알아차려야 바꿀 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L06_challenge#10','soc',5,1,'u3','L06','g5_1_soc_u3_L06_challenge','lesson_challenge','SO5-1-u3-C12',4,'essay','teacher','인권 침해의 뜻을 쓰고, 세 가지 사례 가운데 하나를 골라 왜 인권 침해인지와 이런 문제가 계속되면 어떤 일이 생길지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u3-C12","difficulty":4,"kind":"essay","stem":"인권 침해의 뜻을 쓰고, 세 가지 사례 가운데 하나를 골라 왜 인권 침해인지와 이런 문제가 계속되면 어떤 일이 생길지 쓰세요.","answer_guide":{"answer":"예: 인권 침해는 성별·나이·신체적 특징·종교·국적 등으로 인권을 보호받지 못하는 것이다. ㉮는 다른 나라에서 왔다는 까닭으로 똑같이 일하고도 월급을 적게 받은 차별이므로 인권 침해이다. 이런 일이 계속되면 외국인 근로자들이 불만을 품고 생활에 어려움을 겪는 사람이 늘어날 것이다.","scoring_points":["인권 침해의 뜻을 썼는가","고른 사례가 침해인 까닭을 썼는가","계속될 때 생길 일을 썼는가"]},"explanation":["뜻을 먼저 써요.","어떤 권리를 못 누렸는지 써요.","이어질 일까지 써요."],"asset":{"type":"passage","lines":["㉮ 다른 나라에서 온 사람이 똑같이 일하고 월급을 적게 받았다.","㉯ 집 앞에 높은 건물이 생겨 하루 종일 햇빛이 안 든다.","㉰ 쓰레기 냄새와 자동차 매연 때문에 늘 머리가 아프다."],"title":"세 가지 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_basic#1','soc',5,1,'u3','L07','g5_1_soc_u3_L07_basic','lesson_basic','SO5-1-u3-C13',1,'mc','auto','국회 도서관 이야기에서 찾을 수 있는 인권 침해 문제는 어느 것인가요?',ARRAY['SO5-1-u3-X18']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C13","difficulty":1,"kind":"mc","stem":"국회 도서관 이야기에서 찾을 수 있는 인권 침해 문제는 어느 것인가요?","options":[{"t":"나이가 어리다는 까닭으로 청소년의 도서관 이용을 막은 것","correct":true},{"t":"책이 너무 많은 것","mis":"SO5-1-u3-X18"},{"t":"도서관이 일찍 문을 닫는 것","mis":"SO5-1-u3-X18"},{"t":"전문 책이 어려운 것","mis":"SO5-1-u3-X18"}],"explanation":["누가 이용하지 못했나요?","청소년이에요.","나이로 막은 것이 문제예요."],"asset":{"type":"passage","lines":["어느 국회 도서관은 청소년이 들어오지 못하게 했다.","도서관은 법 만드는 일을 돕는 곳이라 업무에 방해가 되고,","어려운 전문 책이 많아 청소년에게 맞지 않는다고 했다.","한 청소년이 캠페인을 하고 국가 인권 위원회에 의견서를 냈다.","그 뒤 신청서를 한 번만 쓰면 누구나 이용할 수 있게 되었다."],"title":"국회 도서관 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_basic#2','soc',5,1,'u3','L07','g5_1_soc_u3_L07_basic','lesson_basic','SO5-1-u3-C13',1,'mc','auto','인권 침해 문제의 원인을 파악하면 좋은 점은 어느 것인가요?',ARRAY['SO5-1-u3-X19']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C13","difficulty":1,"kind":"mc","stem":"인권 침해 문제의 원인을 파악하면 좋은 점은 어느 것인가요?","options":[{"t":"해결 방법을 찾을 수 있다","correct":true},{"t":"문제가 저절로 사라진다","mis":"SO5-1-u3-X19"},{"t":"문제를 남에게 미룰 수 있다","mis":"SO5-1-u3-X19"},{"t":"문제를 잊어버릴 수 있다","mis":"SO5-1-u3-X19"}],"explanation":["무엇 때문인지 알아야 해요.","그래야 어디를 바꿀지 보여요.","해결의 지름길이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_basic#3','soc',5,1,'u3','L07','g5_1_soc_u3_L07_basic','lesson_basic','SO5-1-u3-C13',1,'ox','auto','해결 방법을 발표할 때는 그렇게 생각한 이유나 근거를 함께 말해야 해요.',ARRAY['SO5-1-u3-X20']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C13","difficulty":1,"kind":"ox","stem":"해결 방법을 발표할 때는 그렇게 생각한 이유나 근거를 함께 말해야 해요.","answer":"O","reason_options":[{"t":"근거가 있어야 친구들이 그 방법이 왜 효과적인지 판단할 수 있기 때문에","correct":true},{"t":"방법만 말하면 되고 이유는 필요 없기 때문에","mis":"SO5-1-u3-X20"}],"mis":"SO5-1-u3-X20","explanation":["방법만으로는 부족해요.","이유를 함께 말해요.","친구들이 판단할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_basic#4','soc',5,1,'u3','L07','g5_1_soc_u3_L07_basic','lesson_basic','SO5-1-u3-C13',1,'mc','auto','인권 보호를 위해 가져야 할 자세로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X17','SO5-1-u3-X22','SO5-1-u3-X19']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C13","difficulty":1,"kind":"mc","stem":"인권 보호를 위해 가져야 할 자세로 알맞은 것은 어느 것인가요?","options":[{"t":"인권 침해를 당한 사람의 어려움에 공감하고 그 입장을 존중한다","correct":true},{"t":"내 일이 아니면 모른 척한다","mis":"SO5-1-u3-X17"},{"t":"침해당한 사람이 혼자 해결하게 둔다","mis":"SO5-1-u3-X22"},{"t":"불편한 사람이 참으면 된다고 여긴다","mis":"SO5-1-u3-X19"}],"explanation":["어려움에 공감해요.","입장을 존중해요.","함께 해결에 관심을 가져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_basic#5','soc',5,1,'u3','L07','g5_1_soc_u3_L07_basic','lesson_basic','SO5-1-u3-C13',2,'mc','auto','국회 도서관 이야기에서 인권 침해 문제의 원인으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X19']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C13","difficulty":2,"kind":"mc","stem":"국회 도서관 이야기에서 인권 침해 문제의 원인으로 알맞은 것은 어느 것인가요?","options":[{"t":"청소년이 업무를 방해하고 전문 책은 안 읽을 것이라는 편견","correct":true},{"t":"청소년이 책을 싫어하기 때문","mis":"SO5-1-u3-X19"},{"t":"도서관에 의자가 없기 때문","mis":"SO5-1-u3-X19"},{"t":"청소년이 신청서를 잃어버렸기 때문","mis":"SO5-1-u3-X19"}],"explanation":["도서관이 밝힌 이유를 다시 읽어요.","확인하지 않고 미리 그렇게 여겼어요.","편견이 원인이에요."],"asset":{"type":"passage","lines":["어느 국회 도서관은 청소년이 들어오지 못하게 했다.","도서관은 법 만드는 일을 돕는 곳이라 업무에 방해가 되고,","어려운 전문 책이 많아 청소년에게 맞지 않는다고 했다.","한 청소년이 캠페인을 하고 국가 인권 위원회에 의견서를 냈다.","그 뒤 신청서를 한 번만 쓰면 누구나 이용할 수 있게 되었다."],"title":"국회 도서관 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_basic#6','soc',5,1,'u3','L07','g5_1_soc_u3_L07_basic','lesson_basic','SO5-1-u3-C13',2,'mc','auto','국회 도서관 이야기에서 청소년이 문제를 해결하려고 한 노력으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X19']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C13","difficulty":2,"kind":"mc","stem":"국회 도서관 이야기에서 청소년이 문제를 해결하려고 한 노력으로 알맞은 것은 어느 것인가요?","options":[{"t":"캠페인을 벌이고 국가 인권 위원회에 의견서를 냈다","correct":true},{"t":"도서관에 가지 않기로 했다","mis":"SO5-1-u3-X19"},{"t":"다른 도서관을 새로 지었다","mis":"SO5-1-u3-X19"},{"t":"혼자 책을 사서 읽었다","mis":"SO5-1-u3-X19"}],"explanation":["목소리를 냈어요.","의견서를 썼어요.","그 결과 누구나 이용하게 됐어요."],"asset":{"type":"passage","lines":["어느 국회 도서관은 청소년이 들어오지 못하게 했다.","도서관은 법 만드는 일을 돕는 곳이라 업무에 방해가 되고,","어려운 전문 책이 많아 청소년에게 맞지 않는다고 했다.","한 청소년이 캠페인을 하고 국가 인권 위원회에 의견서를 냈다.","그 뒤 신청서를 한 번만 쓰면 누구나 이용할 수 있게 되었다."],"title":"국회 도서관 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_basic#7','soc',5,1,'u3','L07','g5_1_soc_u3_L07_basic','lesson_basic','SO5-1-u3-C13',2,'mc','auto','별표 토의에서 별표를 줄 때 지켜야 할 규칙으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X20']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C13","difficulty":2,"kind":"mc","stem":"별표 토의에서 별표를 줄 때 지켜야 할 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 낸 해결 방법은 빼고 효과적인 것을 골라 준다","correct":true},{"t":"가장 먼저 나온 방법에 모두 준다","mis":"SO5-1-u3-X20"},{"t":"별표를 한 곳에 몰아서 준다","mis":"SO5-1-u3-X20"},{"t":"내가 낸 방법에 가장 많이 준다","mis":"SO5-1-u3-X20"}],"explanation":["내 것은 빼요.","셋·둘·하나로 나누어 줘요.","그래야 공정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_basic#8','soc',5,1,'u3','L07','g5_1_soc_u3_L07_basic','lesson_basic','SO5-1-u3-C13',2,'ox','auto','모둠 별표 토의 결과에서 모둠 의견으로 정해질 방법은 ①이에요.',ARRAY['SO5-1-u3-X20']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C13","difficulty":2,"kind":"ox","stem":"모둠 별표 토의 결과에서 모둠 의견으로 정해질 방법은 ①이에요.","answer":"O","reason_options":[{"t":"모둠원이 준 별표를 모았을 때 ①이 가장 많기 때문에","correct":true},{"t":"가장 먼저 적은 방법이 늘 모둠 의견이 되기 때문에","mis":"SO5-1-u3-X20"}],"mis":"SO5-1-u3-X20","explanation":["①은 별 4개예요.","가장 많이 받았어요.","모둠 의견이 돼요."],"asset":{"type":"passage","lines":["문제 — 키가 작다고 놀리는 일이 잦다.","방법 ① 놀림 대신 칭찬 한마디 주고받기 — ★★★ 4개","방법 ② 인권 이야기 시간 만들기 — ★★ 2개","방법 ③ 놀린 사람 이름 칠판에 적기 — ★ 1개"],"title":"모둠 별표 토의 결과(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_basic#9','soc',5,1,'u3','L07','g5_1_soc_u3_L07_basic','lesson_basic','SO5-1-u3-C13',2,'mc','auto','해결 방법을 찾을 때 알맞은 방법은 어느 것인가요?',ARRAY['SO5-1-u3-X20','SO5-1-u3-X19']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C13","difficulty":2,"kind":"mc","stem":"해결 방법을 찾을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"인터넷 검색이나 책을 활용해 각자 해결 방법을 두 가지씩 찾아 쓴다","correct":true},{"t":"한 사람이 정한 방법을 모두 따른다","mis":"SO5-1-u3-X20"},{"t":"원인을 정리하지 않고 바로 정한다","mis":"SO5-1-u3-X19"},{"t":"방법은 하나만 있으면 된다","mis":"SO5-1-u3-X20"}],"explanation":["여러 자료를 활용해요.","각자 두 가지씩 써요.","그다음 함께 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_basic#10','soc',5,1,'u3','L07','g5_1_soc_u3_L07_basic','lesson_basic','SO5-1-u3-C13',3,'error','auto','모둠 별표 토의 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X19']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C13","difficulty":3,"kind":"error","stem":"모둠 별표 토의 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태건 — 「방법 ③도 별을 받았으니 원인과 상관없이 좋은 방법이야.」","correct":true,"mis_target":"SO5-1-u3-X19"},{"t":"주하 — 「③은 놀린 사람을 망신 주는 거라 또 다른 침해가 돼.」","mis":"SO5-1-u3-X19"},{"t":"선율 — 「①은 놀림의 원인인 편견을 줄이는 방법이야.」","mis":"SO5-1-u3-X19"}],"explanation":["③은 또 다른 상처를 줘요.","원인을 줄이지 못해요.","태건이가 잘못 말했어요."],"asset":{"type":"passage","lines":["문제 — 키가 작다고 놀리는 일이 잦다.","방법 ① 놀림 대신 칭찬 한마디 주고받기 — ★★★ 4개","방법 ② 인권 이야기 시간 만들기 — ★★ 2개","방법 ③ 놀린 사람 이름 칠판에 적기 — ★ 1개"],"title":"모둠 별표 토의 결과(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_challenge#1','soc',5,1,'u3','L07','g5_1_soc_u3_L07_challenge','lesson_challenge','SO5-1-u3-C13',2,'sa','auto','청소년이 의견서를 낸 뒤, 인권 침해 사례를 조사하고 바로잡을 것을 권고한 국가 기관은 어디인가요? 「국가 ○○ 위원회」에서 ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u3-C13","difficulty":2,"kind":"sa","stem":"청소년이 의견서를 낸 뒤, 인권 침해 사례를 조사하고 바로잡을 것을 권고한 국가 기관은 어디인가요? 「국가 ○○ 위원회」에서 ○○에 들어갈 두 글자를 쓰세요.","answer":["인권"],"explanation":["인권 침해를 살피는 기관이에요.","나이에 따른 차별이라고 했어요.","국가 인권 위원회예요."],"mis":"SO5-1-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_challenge#2','soc',5,1,'u3','L07','g5_1_soc_u3_L07_challenge','lesson_challenge','SO5-1-u3-C13',2,'mc','auto','국회 도서관이 청소년에게 문을 열었을 때 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X18']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C13","difficulty":2,"kind":"mc","stem":"국회 도서관이 청소년에게 문을 열었을 때 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"청소년도 읽고 싶은 전문 책을 읽고 누구나 동등하게 이용할 수 있다","correct":true},{"t":"어른들이 더 이상 이용할 수 없다","mis":"SO5-1-u3-X18"},{"t":"도서관의 책이 줄어든다","mis":"SO5-1-u3-X18"},{"t":"청소년만 이용할 수 있게 된다","mis":"SO5-1-u3-X18"}],"explanation":["나이 제한이 없어졌어요.","전문 책을 읽을 수 있어요.","모두 동등하게 이용해요."],"asset":{"type":"passage","lines":["어느 국회 도서관은 청소년이 들어오지 못하게 했다.","도서관은 법 만드는 일을 돕는 곳이라 업무에 방해가 되고,","어려운 전문 책이 많아 청소년에게 맞지 않는다고 했다.","한 청소년이 캠페인을 하고 국가 인권 위원회에 의견서를 냈다.","그 뒤 신청서를 한 번만 쓰면 누구나 이용할 수 있게 되었다."],"title":"국회 도서관 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_challenge#3','soc',5,1,'u3','L07','g5_1_soc_u3_L07_challenge','lesson_challenge','SO5-1-u3-C13',3,'mc','auto','토의 차례를 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X20','SO5-1-u3-X19']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C13","difficulty":3,"kind":"mc","stem":"토의 차례를 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"문제 고르기 → 원인 정리 → 각자 방법 두 가지 → 별표로 모둠 의견 정하기","correct":true},{"t":"별표 주기 → 문제 고르기 → 원인 정리 → 방법 찾기","mis":"SO5-1-u3-X20"},{"t":"방법 찾기 → 별표 주기 → 원인 정리 → 문제 고르기","mis":"SO5-1-u3-X20"},{"t":"원인 정리 없이 문제 고르기 → 별표 주기","mis":"SO5-1-u3-X19"}],"explanation":["문제부터 골라요.","원인을 정리해요.","방법을 찾고 별표로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_challenge#4','soc',5,1,'u3','L07','g5_1_soc_u3_L07_challenge','lesson_challenge','SO5-1-u3-C13',3,'mc','auto','토의 종이 판에서 별표를 다시 나누어 주었더니 모둠 의견이 바뀌었어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X20']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C13","difficulty":3,"kind":"mc","stem":"토의 종이 판에서 별표를 다시 나누어 주었더니 모둠 의견이 바뀌었어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"모둠 의견은 각자 별표를 어떻게 나누어 주는지에 따라 정해지기 때문에","correct":true},{"t":"판이 정답을 미리 정해 두었기 때문에","mis":"SO5-1-u3-X20"},{"t":"별표의 개수가 늘어났기 때문에","mis":"SO5-1-u3-X20"},{"t":"가장 먼저 적은 방법이 이기기 때문에","mis":"SO5-1-u3-X20"}],"explanation":["판은 세기만 해요.","정해진 답이 없어요.","모두의 생각이 모여 정해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_challenge#5','soc',5,1,'u3','L07','g5_1_soc_u3_L07_challenge','lesson_challenge','SO5-1-u3-C13',3,'mc','auto','인권 보호를 위한 세 가지 자세 가운데 「국회 도서관 이야기의 청소년」이 가장 잘 보여 준 것은 어느 것인가요?',ARRAY['SO5-1-u3-X17','SO5-1-u3-X19','SO5-1-u3-X22']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C13","difficulty":3,"kind":"mc","stem":"인권 보호를 위한 세 가지 자세 가운데 「국회 도서관 이야기의 청소년」이 가장 잘 보여 준 것은 어느 것인가요?","options":[{"t":"스스로 인권을 지키려고 노력하는 자세","correct":true},{"t":"남의 일에 관심 두지 않는 자세","mis":"SO5-1-u3-X17"},{"t":"침해를 참고 견디는 자세","mis":"SO5-1-u3-X19"},{"t":"남에게 해결을 미루는 자세","mis":"SO5-1-u3-X22"}],"explanation":["직접 캠페인을 했어요.","의견서도 썼어요.","스스로 인권을 지켰어요."],"asset":{"type":"passage","lines":["어느 국회 도서관은 청소년이 들어오지 못하게 했다.","도서관은 법 만드는 일을 돕는 곳이라 업무에 방해가 되고,","어려운 전문 책이 많아 청소년에게 맞지 않는다고 했다.","한 청소년이 캠페인을 하고 국가 인권 위원회에 의견서를 냈다.","그 뒤 신청서를 한 번만 쓰면 누구나 이용할 수 있게 되었다."],"title":"국회 도서관 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_challenge#6','soc',5,1,'u3','L07','g5_1_soc_u3_L07_challenge','lesson_challenge','SO5-1-u3-C13',3,'ox','auto','인권 침해 문제를 해결하려면 침해를 당한 사람 혼자의 노력이면 충분해요.',ARRAY['SO5-1-u3-X19']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C13","difficulty":3,"kind":"ox","stem":"인권 침해 문제를 해결하려면 침해를 당한 사람 혼자의 노력이면 충분해요.","answer":"X","reason_options":[{"t":"주변 사람들의 관심과 공감, 사회의 도움이 함께 있어야 풀리기 때문에","correct":true},{"t":"침해는 당한 사람의 탓이므로 혼자 풀어야 하기 때문에","mis":"SO5-1-u3-X19"}],"mis":"SO5-1-u3-X19","explanation":["주변의 관심이 중요해요.","공감하고 함께해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_challenge#7','soc',5,1,'u3','L07','g5_1_soc_u3_L07_challenge','lesson_challenge','SO5-1-u3-C13',3,'error','auto','국회 도서관 이야기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C13","difficulty":3,"kind":"error","stem":"국회 도서관 이야기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"아라 — 「청소년이 도서관에 못 간 건 청소년이 책을 안 읽어서 생긴 일이야.」","correct":true,"mis_target":"SO5-1-u3-X19"},{"t":"동하 — 「원인은 확인도 안 해 본 편견이었어.」","mis":"SO5-1-u3-X19"},{"t":"리아 — 「캠페인과 의견서로 문제를 풀었어.」","mis":"SO5-1-u3-X19"}],"explanation":["청소년 탓이 아니에요.","미리 그렇게 여긴 편견이에요.","아라가 잘못 말했어요."],"asset":{"type":"passage","lines":["어느 국회 도서관은 청소년이 들어오지 못하게 했다.","도서관은 법 만드는 일을 돕는 곳이라 업무에 방해가 되고,","어려운 전문 책이 많아 청소년에게 맞지 않는다고 했다.","한 청소년이 캠페인을 하고 국가 인권 위원회에 의견서를 냈다.","그 뒤 신청서를 한 번만 쓰면 누구나 이용할 수 있게 되었다."],"title":"국회 도서관 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_challenge#8','soc',5,1,'u3','L07','g5_1_soc_u3_L07_challenge','lesson_challenge','SO5-1-u3-C13',4,'mc','auto','인권 침해 문제를 해결하는 과정을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u3-X19','SO5-1-u3-X20']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C13","difficulty":4,"kind":"mc","stem":"인권 침해 문제를 해결하는 과정을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"문제를 알아차리고 원인을 찾은 뒤, 근거를 들어 함께 방법을 정하고 실천한다","correct":true},{"t":"문제가 생기면 저절로 풀릴 때까지 기다린다","mis":"SO5-1-u3-X19"},{"t":"원인은 살피지 않고 가장 쉬운 방법을 고른다","mis":"SO5-1-u3-X19"},{"t":"한 사람이 정한 방법을 모두 따른다","mis":"SO5-1-u3-X20"}],"explanation":["알아차리기가 처음이에요.","원인을 찾아요.","함께 정하고 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_challenge#9','soc',5,1,'u3','L07','g5_1_soc_u3_L07_challenge','lesson_challenge','SO5-1-u3-C13',4,'mc','auto','모둠 별표 토의 결과에서 ①이 ③보다 좋은 방법인 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X20','SO5-1-u3-X19']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C13","difficulty":4,"kind":"mc","stem":"모둠 별표 토의 결과에서 ①이 ③보다 좋은 방법인 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"놀림의 원인인 편견을 줄이면서 누구에게도 상처를 주지 않기 때문에","correct":true},{"t":"글자 수가 더 많기 때문에","mis":"SO5-1-u3-X20"},{"t":"먼저 적은 방법이기 때문에","mis":"SO5-1-u3-X20"},{"t":"놀린 사람에게 벌을 주기 때문에","mis":"SO5-1-u3-X19"}],"explanation":["①은 칭찬을 주고받아요.","편견을 줄여요.","③은 또 다른 상처를 줘요."],"asset":{"type":"passage","lines":["문제 — 키가 작다고 놀리는 일이 잦다.","방법 ① 놀림 대신 칭찬 한마디 주고받기 — ★★★ 4개","방법 ② 인권 이야기 시간 만들기 — ★★ 2개","방법 ③ 놀린 사람 이름 칠판에 적기 — ★ 1개"],"title":"모둠 별표 토의 결과(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L07_challenge#10','soc',5,1,'u3','L07','g5_1_soc_u3_L07_challenge','lesson_challenge','SO5-1-u3-C13',4,'essay','teacher','국회 도서관 이야기에서 인권 침해 문제와 그 원인을 쓰고, 청소년의 노력과 그 결과를 쓴 뒤, 이 이야기에서 배울 수 있는 인권 보호의 자세 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u3-C13","difficulty":4,"kind":"essay","stem":"국회 도서관 이야기에서 인권 침해 문제와 그 원인을 쓰고, 청소년의 노력과 그 결과를 쓴 뒤, 이 이야기에서 배울 수 있는 인권 보호의 자세 한 가지를 쓰세요.","answer_guide":{"answer":"예: 나이가 어리다는 까닭으로 청소년의 국회 도서관 이용을 막은 것이 문제였고, 청소년이 업무를 방해하고 전문 책은 읽지 않을 것이라는 편견이 원인이었다. 청소년은 캠페인을 하고 국가 인권 위원회에 의견서를 내어, 신청서를 한 번만 쓰면 누구나 이용할 수 있게 되었다. 스스로 인권을 지키려고 노력하는 자세를 배울 수 있다.","scoring_points":["문제와 원인을 썼는가","노력과 결과를 썼는가","인권 보호의 자세를 썼는가"]},"explanation":["문제와 원인을 써요.","노력과 결과를 써요.","배울 자세를 써요."],"asset":{"type":"passage","lines":["어느 국회 도서관은 청소년이 들어오지 못하게 했다.","도서관은 법 만드는 일을 돕는 곳이라 업무에 방해가 되고,","어려운 전문 책이 많아 청소년에게 맞지 않는다고 했다.","한 청소년이 캠페인을 하고 국가 인권 위원회에 의견서를 냈다.","그 뒤 신청서를 한 번만 쓰면 누구나 이용할 수 있게 되었다."],"title":"국회 도서관 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_basic#1','soc',5,1,'u3','L08','g5_1_soc_u3_L08_basic','lesson_basic','SO5-1-u3-C14',1,'mc','auto','노인을 배려하려고 도서관에 마련해 둔 것은 어느 것인가요?',ARRAY['SO5-1-u3-X21']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C14","difficulty":1,"kind":"mc","stem":"노인을 배려하려고 도서관에 마련해 둔 것은 어느 것인가요?","options":[{"t":"큰 글자 도서","correct":true},{"t":"임산부 배려석","mis":"SO5-1-u3-X21"},{"t":"어린이 전용 세면대","mis":"SO5-1-u3-X21"},{"t":"옐로 카펫","mis":"SO5-1-u3-X21"}],"explanation":["작은 글씨는 읽기 어려워요.","글자를 크게 만들었어요.","큰 글자 도서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_basic#2','soc',5,1,'u3','L08','g5_1_soc_u3_L08_basic','lesson_basic','SO5-1-u3-C14',1,'mc','auto','시각 장애가 있는 사람이 계단을 안전하게 쓰도록 바닥에 깐 것은 어느 것인가요?',ARRAY['SO5-1-u3-X21']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C14","difficulty":1,"kind":"mc","stem":"시각 장애가 있는 사람이 계단을 안전하게 쓰도록 바닥에 깐 것은 어느 것인가요?","options":[{"t":"계단 점자 블록","correct":true},{"t":"복도 안전 손잡이","mis":"SO5-1-u3-X21"},{"t":"옐로 카펫","mis":"SO5-1-u3-X21"},{"t":"큰 글자 도서","mis":"SO5-1-u3-X21"}],"explanation":["발로 느낄 수 있어요.","계단을 알려 줘요.","점자 블록이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_basic#3','soc',5,1,'u3','L08','g5_1_soc_u3_L08_basic','lesson_basic','SO5-1-u3-C14',1,'sa','auto','질병·실업·장애·노령·빈곤으로 어려움에 처한 사람을 돕고 모든 국민의 인간다운 생활을 보장하려는 제도는 「사회 ○○ 제도」예요. ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u3-C14","difficulty":1,"kind":"sa","stem":"질병·실업·장애·노령·빈곤으로 어려움에 처한 사람을 돕고 모든 국민의 인간다운 생활을 보장하려는 제도는 「사회 ○○ 제도」예요. ○○에 들어갈 두 글자를 쓰세요.","answer":["보장"],"explanation":["국가가 마련한 제도예요.","어려운 사람을 도와요.","사회 보장 제도예요."],"mis":"SO5-1-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_basic#4','soc',5,1,'u3','L08','g5_1_soc_u3_L08_basic','lesson_basic','SO5-1-u3-C14',1,'ox','auto','횡단보도 앞의 옐로 카펫은 어린이 교통사고를 막으려고 만든 시설이에요.',ARRAY['SO5-1-u3-X21']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C14","difficulty":1,"kind":"ox","stem":"횡단보도 앞의 옐로 카펫은 어린이 교통사고를 막으려고 만든 시설이에요.","answer":"O","reason_options":[{"t":"바닥과 벽을 노랗게 칠해 기다리는 어린이가 운전자 눈에 잘 띄게 하기 때문에","correct":true},{"t":"건물을 예쁘게 꾸미려고 칠한 것이기 때문에","mis":"SO5-1-u3-X21"}],"mis":"SO5-1-u3-X21","explanation":["노란색은 눈에 잘 띄어요.","어린이를 지켜요.","교통사고 예방이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_basic#5','soc',5,1,'u3','L08','g5_1_soc_u3_L08_basic','lesson_basic','SO5-1-u3-C14',2,'match','auto','배려하는 시설과 물건을 그것으로 배려하는 사람과 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u3-C14","difficulty":2,"kind":"match","stem":"배려하는 시설과 물건을 그것으로 배려하는 사람과 알맞게 이으세요.","pairs":[{"l":"㉠ 전용 세면대","r":"어린이"},{"l":"㉡ 큰 글자 도서","r":"노인"},{"l":"㉢ 배려석","r":"임산부"},{"l":"㉤ 점자 블록","r":"시각 장애가 있는 사람"}],"mis":"SO5-1-u3-X21","explanation":["낮은 세면대는 어린이예요.","큰 글자는 노인이에요.","배려석은 임산부, 점자 블록은 시각 장애인이에요."],"asset":{"type":"passage","lines":["㉠ 어린이 전용 세면대","㉡ 도서관의 큰 글자 도서","㉢ 버스의 임산부 배려석","㉣ 횡단보도 앞 노란 옐로 카펫","㉤ 계단 바닥의 점자 블록"],"title":"배려하는 시설과 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_basic#6','soc',5,1,'u3','L08','g5_1_soc_u3_L08_basic','lesson_basic','SO5-1-u3-C14',2,'mc','auto','학교의 인권 보호 노력으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X22']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C14","difficulty":2,"kind":"mc","stem":"학교의 인권 보호 노력으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"학교 규칙은 선생님이 혼자서 정한다","correct":true},{"t":"인권 교육을 한다","mis":"SO5-1-u3-X22"},{"t":"경사로를 마련한다","mis":"SO5-1-u3-X22"},{"t":"계단 점자 블록을 깐다","mis":"SO5-1-u3-X22"}],"explanation":["학교 규칙은 함께 만들어요.","선생님·학생·학부모가요.","첫째 보기가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_basic#7','soc',5,1,'u3','L08','g5_1_soc_u3_L08_basic','lesson_basic','SO5-1-u3-C14',2,'mc','auto','국가의 인권 보호 노력으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X22']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C14","difficulty":2,"kind":"mc","stem":"국가의 인권 보호 노력으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"인권을 침해당한 사람이 혼자 힘으로 해결하도록 맡겨 둔다","correct":true},{"t":"인권 보호를 위한 법과 제도를 만든다","mis":"SO5-1-u3-X22"},{"t":"공공 편의 시설을 설치하고 관리한다","mis":"SO5-1-u3-X22"},{"t":"인권 교육과 캠페인 활동을 한다","mis":"SO5-1-u3-X22"}],"explanation":["국가는 침해된 사람을 도와요.","혼자 맡겨 두지 않아요.","첫째 보기가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_basic#8','soc',5,1,'u3','L08','g5_1_soc_u3_L08_basic','lesson_basic','SO5-1-u3-C14',2,'mc','auto','국가 인권 위원회가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X22']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C14","difficulty":2,"kind":"mc","stem":"국가 인권 위원회가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"인권 침해 사례를 조사해 인권이 침해된 사람을 돕는다","correct":true},{"t":"새로운 건물을 짓는다","mis":"SO5-1-u3-X22"},{"t":"학교 시험 문제를 낸다","mis":"SO5-1-u3-X22"},{"t":"놀이터를 청소한다","mis":"SO5-1-u3-X22"}],"explanation":["인권을 살피는 기관이에요.","침해 사례를 조사해요.","침해된 사람을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_basic#9','soc',5,1,'u3','L08','g5_1_soc_u3_L08_basic','lesson_basic','SO5-1-u3-C14',2,'mc','auto','무장애 통합 놀이터를 만든 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X24','SO5-1-u3-X21']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C14","difficulty":2,"kind":"mc","stem":"무장애 통합 놀이터를 만든 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"장애와 관계없이 모든 어린이가 동등하게 놀 권리를 누리게 하려고","correct":true},{"t":"장애가 있는 어린이만 놀게 하려고","mis":"SO5-1-u3-X24"},{"t":"놀이터를 더 작게 만들려고","mis":"SO5-1-u3-X21"},{"t":"어른만 쓰게 하려고","mis":"SO5-1-u3-X21"}],"explanation":["등받이 그네가 있어요.","휠체어로 탈 수 있어요.","모두 함께 놀 권리예요."],"asset":{"type":"passage","lines":["그네에 등받이와 안전띠가 있다.","휠체어나 유아차를 탄 채로 탈 수 있는 놀이기구가 있다.","놀이기구 사이에 턱 없는 넓은 길이 있다."],"title":"무장애 통합 놀이터의 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_basic#10','soc',5,1,'u3','L08','g5_1_soc_u3_L08_basic','lesson_basic','SO5-1-u3-C14',3,'error','auto','우리 사회의 인권 보호 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X22']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C14","difficulty":3,"kind":"error","stem":"우리 사회의 인권 보호 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"연우 — 「공공 편의 시설은 장애가 있는 사람만 쓸 수 있어.」","correct":true,"mis_target":"SO5-1-u3-X22"},{"t":"수안 — 「국가는 사회 보장 제도를 마련해 국민의 생활을 도와.」","mis":"SO5-1-u3-X22"},{"t":"예담 — 「학교는 학생들이 인권을 존중하도록 인권 교육을 해.」","mis":"SO5-1-u3-X22"}],"explanation":["공공 편의 시설은 모두를 위해요.","많은 사람이 편리하게 써요.","연우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_challenge#1','soc',5,1,'u3','L08','g5_1_soc_u3_L08_challenge','lesson_challenge','SO5-1-u3-C14',2,'mc','auto','배려하는 시설과 물건 다섯 가지의 공통점으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X21','SO5-1-u3-X22']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C14","difficulty":2,"kind":"mc","stem":"배려하는 시설과 물건 다섯 가지의 공통점으로 알맞은 것은 어느 것인가요?","options":[{"t":"사회적으로 보호가 필요한 사람을 배려해 인권을 보호하려고 마련했다","correct":true},{"t":"모두 같은 사람을 위한 것이다","mis":"SO5-1-u3-X21"},{"t":"보기 좋게 꾸미려고 만든 것이다","mis":"SO5-1-u3-X21"},{"t":"국가가 아니라 개인만 만든다","mis":"SO5-1-u3-X22"}],"explanation":["어린이·노인·임산부·장애인이에요.","보호가 필요한 사람이에요.","인권 보호를 위해서예요."],"asset":{"type":"passage","lines":["㉠ 어린이 전용 세면대","㉡ 도서관의 큰 글자 도서","㉢ 버스의 임산부 배려석","㉣ 횡단보도 앞 노란 옐로 카펫","㉤ 계단 바닥의 점자 블록"],"title":"배려하는 시설과 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_challenge#2','soc',5,1,'u3','L08','g5_1_soc_u3_L08_challenge','lesson_challenge','SO5-1-u3-C14',2,'mc','auto','노력의 주체와 그 노력을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X21']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C14","difficulty":2,"kind":"mc","stem":"노력의 주체와 그 노력을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"국가 — 법과 제도를 만들고 사회 보장 제도를 시행한다","correct":true},{"t":"학교 — 사회 보장 제도를 시행한다","mis":"SO5-1-u3-X21"},{"t":"국가 — 학급 회의로 학급 규칙을 정한다","mis":"SO5-1-u3-X21"},{"t":"학교 — 국가 인권 위원회를 만든다","mis":"SO5-1-u3-X21"}],"explanation":["학급 회의는 학교의 일이에요.","사회 보장 제도는 국가의 일이에요.","주체를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_challenge#3','soc',5,1,'u3','L08','g5_1_soc_u3_L08_challenge','lesson_challenge','SO5-1-u3-C14',3,'mc','auto','학교 답사 수첩을 채우려면 학교 현관에서만 살펴서는 안 되는 까닭은 어느 것인가요?',ARRAY['SO5-1-u3-X21']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C14","difficulty":3,"kind":"mc","stem":"학교 답사 수첩을 채우려면 학교 현관에서만 살펴서는 안 되는 까닭은 어느 것인가요?","options":[{"t":"인권 보호 시설이 학교 구석구석에 나뉘어 있어서 직접 돌아다녀야 보이기 때문에","correct":true},{"t":"우리 학교에는 시설이 하나도 없기 때문에","mis":"SO5-1-u3-X21"},{"t":"점자 블록은 눈에 보이지 않기 때문에","mis":"SO5-1-u3-X21"},{"t":"현관은 인권과 관계없는 곳이기 때문에","mis":"SO5-1-u3-X21"}],"explanation":["복도에도 계단에도 있어요.","한곳에 모여 있지 않아요.","구석구석 다녀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_challenge#4','soc',5,1,'u3','L08','g5_1_soc_u3_L08_challenge','lesson_challenge','SO5-1-u3-C14',3,'mc','auto','답사 수첩의 마지막 칸에 이미 찾은 경사로를 적으면 안 되는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X21']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C14","difficulty":3,"kind":"mc","stem":"답사 수첩의 마지막 칸에 이미 찾은 경사로를 적으면 안 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 칸은 우리 학교에 아직 없어서 새로 제안하고 싶은 것을 적는 칸이기 때문에","correct":true},{"t":"경사로는 인권 보호 시설이 아니기 때문에","mis":"SO5-1-u3-X21"},{"t":"경사로는 학교 밖에만 있기 때문에","mis":"SO5-1-u3-X21"},{"t":"경사로는 어른만 쓰기 때문에","mis":"SO5-1-u3-X21"}],"explanation":["경사로는 이미 있어요.","마지막 칸은 제안 칸이에요.","없는 것을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_challenge#5','soc',5,1,'u3','L08','g5_1_soc_u3_L08_challenge','lesson_challenge','SO5-1-u3-C14',3,'mc','auto','운동장 사용 시간을 학년별로 정한 학교 규칙이 인권 보호와 이어지는 까닭은 어느 것인가요?',ARRAY['SO5-1-u3-X22','SO5-1-u3-X21']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C14","difficulty":3,"kind":"mc","stem":"운동장 사용 시간을 학년별로 정한 학교 규칙이 인권 보호와 이어지는 까닭은 어느 것인가요?","options":[{"t":"모두가 안전하고 공평하게 운동장을 쓸 수 있게 하기 때문에","correct":true},{"t":"운동장을 한 학년만 쓰게 하려고","mis":"SO5-1-u3-X22"},{"t":"선생님이 쉬려고","mis":"SO5-1-u3-X22"},{"t":"운동장을 더 넓히려고","mis":"SO5-1-u3-X21"}],"explanation":["학년마다 시간을 나눠요.","서로 다치지 않아요.","공평하게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_challenge#6','soc',5,1,'u3','L08','g5_1_soc_u3_L08_challenge','lesson_challenge','SO5-1-u3-C14',3,'ox','auto','어린이는 학교 안에서만 인권을 보호받아요.',ARRAY['SO5-1-u3-X22']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C14","difficulty":3,"kind":"ox","stem":"어린이는 학교 안에서만 인권을 보호받아요.","answer":"X","reason_options":[{"t":"주변·학교·국가 곳곳에서 인권을 보호하려는 노력이 있기 때문에","correct":true},{"t":"학교 밖에는 인권 보호 노력이 없기 때문에","mis":"SO5-1-u3-X22"}],"mis":"SO5-1-u3-X22","explanation":["도서관·버스·횡단보도에도 있어요.","국가도 노력해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_challenge#7','soc',5,1,'u3','L08','g5_1_soc_u3_L08_challenge','lesson_challenge','SO5-1-u3-C14',3,'error','auto','무장애 통합 놀이터를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X24','SO5-1-u3-X21']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C14","difficulty":3,"kind":"error","stem":"무장애 통합 놀이터를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하민 — 「이 놀이터는 장애가 있는 어린이만 쓰는 곳이야.」","correct":true,"mis_target":"SO5-1-u3-X24"},{"t":"예솔 — 「휠체어를 탄 채로 탈 수 있는 놀이기구가 있어.」","mis":"SO5-1-u3-X21"},{"t":"정우 — 「모든 어린이가 함께 어울려 놀 수 있어.」","mis":"SO5-1-u3-X21"}],"explanation":["모든 어린이가 함께 놀아요.","장애와 관계없어요.","하민이가 잘못 말했어요."],"asset":{"type":"passage","lines":["그네에 등받이와 안전띠가 있다.","휠체어나 유아차를 탄 채로 탈 수 있는 놀이기구가 있다.","놀이기구 사이에 턱 없는 넓은 길이 있다."],"title":"무장애 통합 놀이터의 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_challenge#8','soc',5,1,'u3','L08','g5_1_soc_u3_L08_challenge','lesson_challenge','SO5-1-u3-C14',4,'mc','auto','우리 사회의 인권 보호 노력을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u3-X22','SO5-1-u3-X24']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C14","difficulty":4,"kind":"mc","stem":"우리 사회의 인권 보호 노력을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"주변의 배려 시설, 학교의 시설·교육·규칙, 국가의 법·제도·편의 시설이 함께 인간다운 생활을 지킨다","correct":true},{"t":"국가만 노력하고 학교와 주변은 아무것도 하지 않는다","mis":"SO5-1-u3-X22"},{"t":"인권 보호는 시설을 짓는 것만으로 끝난다","mis":"SO5-1-u3-X22"},{"t":"인권은 어린이만 보호받는다","mis":"SO5-1-u3-X24"}],"explanation":["주변이 노력해요.","학교와 국가도 노력해요.","함께 인간다운 생활을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_challenge#9','soc',5,1,'u3','L08','g5_1_soc_u3_L08_challenge','lesson_challenge','SO5-1-u3-C14',4,'mc','auto','사회 보장 제도가 인권 보호와 이어지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X22','SO5-1-u3-X21']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C14","difficulty":4,"kind":"mc","stem":"사회 보장 제도가 인권 보호와 이어지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어려움에 처한 사람도 인간다운 생활을 할 수 있도록 국가가 돕기 때문에","correct":true},{"t":"돈이 많은 사람만 돕기 때문에","mis":"SO5-1-u3-X22"},{"t":"어려운 사람이 혼자 견디게 하기 때문에","mis":"SO5-1-u3-X22"},{"t":"학교 시설을 고치는 제도이기 때문에","mis":"SO5-1-u3-X21"}],"explanation":["질병·실업·노령의 어려움이에요.","국가가 도와요.","인간다운 생활을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L08_challenge#10','soc',5,1,'u3','L08','g5_1_soc_u3_L08_challenge','lesson_challenge','SO5-1-u3-C14',4,'essay','teacher','우리 사회가 인권을 보호하는 노력을 주변·학교·국가로 나누어 하나씩 쓰고, 우리 학교에 새로 제안하고 싶은 인권 보호 시설과 그 쓰임새를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u3-C14","difficulty":4,"kind":"essay","stem":"우리 사회가 인권을 보호하는 노력을 주변·학교·국가로 나누어 하나씩 쓰고, 우리 학교에 새로 제안하고 싶은 인권 보호 시설과 그 쓰임새를 쓰세요.","answer_guide":{"answer":"예: 주변에는 노인을 위한 도서관의 큰 글자 도서가 있다. 학교는 선생님·학생·학부모가 함께 인권 보호 규칙을 만든다. 국가는 사회 보장 제도를 시행한다. 우리 학교에 음성 지원 안내판을 제안한다 — 시각 장애가 있는 사람이 학교의 주요 시설을 소리로 알 수 있다.","scoring_points":["주변·학교·국가의 노력을 하나씩 썼는가","제안할 시설을 썼는가","그 시설의 쓰임새를 썼는가"]},"explanation":["세 곳으로 나누어요.","없는 시설을 제안해요.","누구를 위해 쓰이는지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_basic#1','soc',5,1,'u3','L09','g5_1_soc_u3_L09_basic','lesson_basic','SO5-1-u3-C15',1,'mc','auto','우리가 생활 속에서 실천할 수 있는 인권 보호 활동으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X17','SO5-1-u3-X14']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C15","difficulty":1,"kind":"mc","stem":"우리가 생활 속에서 실천할 수 있는 인권 보호 활동으로 알맞은 것은 어느 것인가요?","options":[{"t":"인권을 존중하는 말 사용하기","correct":true},{"t":"침해를 보고도 못 본 척하기","mis":"SO5-1-u3-X17"},{"t":"나와 다른 사람 멀리하기","mis":"SO5-1-u3-X14"},{"t":"내 인권만 챙기기","mis":"SO5-1-u3-X14"}],"explanation":["말 한마디도 실천이에요.","봉사 활동과 캠페인도 있어요.","존중하는 말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_basic#2','soc',5,1,'u3','L09','g5_1_soc_u3_L09_basic','lesson_basic','SO5-1-u3-C15',1,'mc','auto','인권 사진전에서 사진은 어떻게 찍어야 하나요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C15","difficulty":1,"kind":"mc","stem":"인권 사진전에서 사진은 어떻게 찍어야 하나요?","options":[{"t":"인권이 침해되는 모습과 보호되는 모습이 대조되게 찍는다","correct":true},{"t":"멀리서 흐리게 찍는다","mis":"SO5-1-u3-X23"},{"t":"예쁜 곳만 골라 찍는다","mis":"SO5-1-u3-X23"},{"t":"사람이 없는 곳만 찍는다","mis":"SO5-1-u3-X23"}],"explanation":["두 모습을 나란히 놓아요.","견주면 잘 보여요.","대조되게 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_basic#3','soc',5,1,'u3','L09','g5_1_soc_u3_L09_basic','lesson_basic','SO5-1-u3-C15',1,'ox','auto','인권 보호는 큰일을 할 수 있을 때까지 기다렸다가 한꺼번에 하는 것이 좋아요.',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C15","difficulty":1,"kind":"ox","stem":"인권 보호는 큰일을 할 수 있을 때까지 기다렸다가 한꺼번에 하는 것이 좋아요.","answer":"X","reason_options":[{"t":"생활 속 작은 일부터 바로 실천해야 인권을 존중하는 사회를 만들 수 있기 때문에","correct":true},{"t":"작은 실천은 인권과 아무 관계가 없기 때문에","mis":"SO5-1-u3-X23"}],"mis":"SO5-1-u3-X23","explanation":["큰일을 기다리지 않아요.","작은 일부터 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_basic#4','soc',5,1,'u3','L09','g5_1_soc_u3_L09_basic','lesson_basic','SO5-1-u3-C15',1,'sa','auto','어린이·노인·장애인처럼 보호가 필요한 사람들이 사회에 잘 적응하도록 돕는 직업은 무엇인가요? 「사회 ○○사」에서 ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO5-1-u3-C15","difficulty":1,"kind":"sa","stem":"어린이·노인·장애인처럼 보호가 필요한 사람들이 사회에 잘 적응하도록 돕는 직업은 무엇인가요? 「사회 ○○사」에서 ○○에 들어갈 두 글자를 쓰세요.","answer":["복지"],"explanation":["학교·병원·국가기관에서 일해요.","상담하고 안내해요.","사회 복지사예요."],"mis":"SO5-1-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_basic#5','soc',5,1,'u3','L09','g5_1_soc_u3_L09_basic','lesson_basic','SO5-1-u3-C15',2,'mc','auto','교과서에서 소개한 인권 보호 실천 방법 세 가지에 들지 않는 것은 어느 것인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C15","difficulty":2,"kind":"mc","stem":"교과서에서 소개한 인권 보호 실천 방법 세 가지에 들지 않는 것은 어느 것인가요?","options":[{"t":"인권 운동회 열기","correct":true},{"t":"인권 사진전","mis":"SO5-1-u3-X23"},{"t":"인권 포스터 전시회","mis":"SO5-1-u3-X23"},{"t":"인권 손수 제작물 전시회","mis":"SO5-1-u3-X23"}],"explanation":["사진전·포스터·손수 제작물이에요.","모둠이 하나를 골라요.","운동회는 들지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_basic#6','soc',5,1,'u3','L09','g5_1_soc_u3_L09_basic','lesson_basic','SO5-1-u3-C15',2,'mc','auto','인권 사진전 차례 카드에서 가장 먼저 할 일은 어느 것인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C15","difficulty":2,"kind":"mc","stem":"인권 사진전 차례 카드에서 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"SO5-1-u3-X23"},{"t":"㉰","mis":"SO5-1-u3-X23"},{"t":"㉱","mis":"SO5-1-u3-X23"}],"explanation":["무엇을 찍을지 먼저 정해요.","그다음 찍어요.","㉯가 처음이에요."],"asset":{"type":"passage","lines":["㉮ 사진을 출력해 종이에 붙이고 제목을 정한다.","㉯ 어떤 장면을 찍을지 모둠에서 정한다.","㉰ 완성한 사진전을 게시하고 누리집에 올린다.","㉱ 침해와 보호가 대조되게 사진을 찍는다."],"title":"인권 사진전 차례 카드(섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_basic#7','soc',5,1,'u3','L09','g5_1_soc_u3_L09_basic','lesson_basic','SO5-1-u3-C15',2,'mc','auto','인권 사진전 차례 카드에서 가장 마지막에 할 일은 어느 것인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C15","difficulty":2,"kind":"mc","stem":"인권 사진전 차례 카드에서 가장 마지막에 할 일은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"SO5-1-u3-X23"},{"t":"㉯","mis":"SO5-1-u3-X23"},{"t":"㉱","mis":"SO5-1-u3-X23"}],"explanation":["다 만든 뒤에 해요.","많은 사람에게 알려요.","게시하고 누리집에 올려요."],"asset":{"type":"passage","lines":["㉮ 사진을 출력해 종이에 붙이고 제목을 정한다.","㉯ 어떤 장면을 찍을지 모둠에서 정한다.","㉰ 완성한 사진전을 게시하고 누리집에 올린다.","㉱ 침해와 보호가 대조되게 사진을 찍는다."],"title":"인권 사진전 차례 카드(섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_basic#8','soc',5,1,'u3','L09','g5_1_soc_u3_L09_basic','lesson_basic','SO5-1-u3-C15',2,'mc','auto','인권 사진전 한 칸에 사진과 함께 적은 두 가지는 어느 것인가요?',ARRAY['SO5-1-u3-X23','SO5-1-u3-X15']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C15","difficulty":2,"kind":"mc","stem":"인권 사진전 한 칸에 사진과 함께 적은 두 가지는 어느 것인가요?","options":[{"t":"보호 방법과 찍은 까닭","correct":true},{"t":"찍은 사람의 키와 몸무게","mis":"SO5-1-u3-X23"},{"t":"사진기 이름과 값","mis":"SO5-1-u3-X23"},{"t":"친구들의 점수","mis":"SO5-1-u3-X15"}],"explanation":["경사로를 놓으면 된대요.","자유롭게 다니면 좋겠대요.","보호 방법과 까닭이에요."],"asset":{"type":"passage","lines":["사진 — 출입구에 계단만 있어 휠체어가 들어가지 못한다.","보호 방법 — 경사로를 놓으면 편하게 드나들 수 있다.","찍은 까닭 — 휠체어를 탄 사람도 자유롭게 다니면 좋겠다."],"title":"인권 사진전 한 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_basic#9','soc',5,1,'u3','L09','g5_1_soc_u3_L09_basic','lesson_basic','SO5-1-u3-C15',2,'mc','auto','인권 보호를 실천할 때 필요한 마음가짐으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X14','SO5-1-u3-X17','SO5-1-u3-X23']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C15","difficulty":2,"kind":"mc","stem":"인권 보호를 실천할 때 필요한 마음가짐으로 알맞은 것은 어느 것인가요?","options":[{"t":"나의 인권이 소중한 만큼 다른 사람의 인권도 소중하다","correct":true},{"t":"내 인권을 먼저 다 챙긴 뒤에 남을 생각한다","mis":"SO5-1-u3-X14"},{"t":"남의 인권은 그 사람이 알아서 지킨다","mis":"SO5-1-u3-X17"},{"t":"인권은 어른들이 지켜 준다","mis":"SO5-1-u3-X23"}],"explanation":["나와 남 모두 소중해요.","함께 지켜요.","그것이 실천의 바탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_basic#10','soc',5,1,'u3','L09','g5_1_soc_u3_L09_basic','lesson_basic','SO5-1-u3-C15',3,'error','auto','인권 ○✕ 퀴즈를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X16','SO5-1-u3-X21','SO5-1-u3-X22']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C15","difficulty":3,"kind":"error","stem":"인권 ○✕ 퀴즈를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서율 — 「인권 보호를 하려면 편견과 차별을 가져야 해.」","correct":true,"mis_target":"SO5-1-u3-X16"},{"t":"유나 — 「경사로와 점자 블록은 인권 보호 시설이야.」","mis":"SO5-1-u3-X21"},{"t":"도겸 — 「국가는 인권 보호를 위한 법과 제도를 만들어.」","mis":"SO5-1-u3-X22"}],"explanation":["편견과 차별은 침해의 원인이에요.","버려야 할 것이에요.","서율이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_challenge#1','soc',5,1,'u3','L09','g5_1_soc_u3_L09_challenge','lesson_challenge','SO5-1-u3-C15',2,'sa','auto','인권 사진전 차례 카드를 일의 차례대로 늘어놓아 기호를 쓰세요(예: ㉮㉯㉰㉱).','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u3-C15","difficulty":2,"kind":"sa","stem":"인권 사진전 차례 카드를 일의 차례대로 늘어놓아 기호를 쓰세요(예: ㉮㉯㉰㉱).","answer":["㉯㉱㉮㉰","㉯ ㉱ ㉮ ㉰","㉯-㉱-㉮-㉰","㉯→㉱→㉮→㉰","㉯,㉱,㉮,㉰"],"explanation":["정하고 찍어요.","붙이고 제목을 달아요.","마지막에 알려요."],"asset":{"type":"passage","lines":["㉮ 사진을 출력해 종이에 붙이고 제목을 정한다.","㉯ 어떤 장면을 찍을지 모둠에서 정한다.","㉰ 완성한 사진전을 게시하고 누리집에 올린다.","㉱ 침해와 보호가 대조되게 사진을 찍는다."],"title":"인권 사진전 차례 카드(섞임)"},"mis":"SO5-1-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_challenge#2','soc',5,1,'u3','L09','g5_1_soc_u3_L09_challenge','lesson_challenge','SO5-1-u3-C15',2,'mc','auto','인권 포스터를 만들 때 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C15","difficulty":2,"kind":"mc","stem":"인권 포스터를 만들 때 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"짝과 넣을 문구와 그림을 생각하고 포스터 아래에 설명 글을 쓴다","correct":true},{"t":"아무 그림이나 크게 그린다","mis":"SO5-1-u3-X23"},{"t":"글씨만 빼곡히 쓴다","mis":"SO5-1-u3-X23"},{"t":"완성한 포스터를 혼자 간직한다","mis":"SO5-1-u3-X23"}],"explanation":["문구와 그림을 정해요.","설명 글도 써요.","다른 모둠에 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_challenge#3','soc',5,1,'u3','L09','g5_1_soc_u3_L09_challenge','lesson_challenge','SO5-1-u3-C15',3,'mc','auto','차례표에서 「사진을 출력해 종이에 붙이고 제목을 정한다」를 첫 걸음으로 세울 수 없는 까닭은 어느 것인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C15","difficulty":3,"kind":"mc","stem":"차례표에서 「사진을 출력해 종이에 붙이고 제목을 정한다」를 첫 걸음으로 세울 수 없는 까닭은 어느 것인가요?","options":[{"t":"찍을 장면을 정하고 사진을 찍어야 붙일 사진이 생기기 때문에","correct":true},{"t":"그 걸음은 차례표에 없기 때문에","mis":"SO5-1-u3-X23"},{"t":"사진 붙이기는 인권과 관계없기 때문에","mis":"SO5-1-u3-X23"},{"t":"제목은 정하지 않아도 되기 때문에","mis":"SO5-1-u3-X23"}],"explanation":["앞 걸음이 있어야 해요.","찍기 전엔 붙일 사진이 없어요.","차례가 있어요."],"asset":{"type":"passage","lines":["㉮ 사진을 출력해 종이에 붙이고 제목을 정한다.","㉯ 어떤 장면을 찍을지 모둠에서 정한다.","㉰ 완성한 사진전을 게시하고 누리집에 올린다.","㉱ 침해와 보호가 대조되게 사진을 찍는다."],"title":"인권 사진전 차례 카드(섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_challenge#4','soc',5,1,'u3','L09','g5_1_soc_u3_L09_challenge','lesson_challenge','SO5-1-u3-C15',3,'mc','auto','사진전·포스터·손수 제작물 세 활동의 마지막 걸음이 닮은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C15","difficulty":3,"kind":"mc","stem":"사진전·포스터·손수 제작물 세 활동의 마지막 걸음이 닮은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"만든 것을 많은 사람이 보아야 인권 보호의 중요성을 알릴 수 있기 때문에","correct":true},{"t":"마지막 걸음은 원래 다 같기 때문에","mis":"SO5-1-u3-X23"},{"t":"세 활동 모두 사진을 쓰기 때문에","mis":"SO5-1-u3-X23"},{"t":"세 활동을 같은 날 해야 하기 때문에","mis":"SO5-1-u3-X23"}],"explanation":["게시하거나 누리집에 올려요.","많은 사람이 봐요.","중요성이 퍼져 나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_challenge#5','soc',5,1,'u3','L09','g5_1_soc_u3_L09_challenge','lesson_challenge','SO5-1-u3-C15',3,'mc','auto','인권 사진전 한 칸의 사진처럼 「출입구에 계단만 있는 모습」과 대조되게 찍을 보호의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C15","difficulty":3,"kind":"mc","stem":"인권 사진전 한 칸의 사진처럼 「출입구에 계단만 있는 모습」과 대조되게 찍을 보호의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"경사로가 놓여 휠체어를 탄 사람이 드나드는 출입구","correct":true},{"t":"계단이 더 높아진 출입구","mis":"SO5-1-u3-X23"},{"t":"문이 닫힌 출입구","mis":"SO5-1-u3-X23"},{"t":"사람이 아무도 없는 출입구","mis":"SO5-1-u3-X23"}],"explanation":["침해와 보호를 견줘요.","경사로가 보호의 모습이에요.","대조가 분명해져요."],"asset":{"type":"passage","lines":["사진 — 출입구에 계단만 있어 휠체어가 들어가지 못한다.","보호 방법 — 경사로를 놓으면 편하게 드나들 수 있다.","찍은 까닭 — 휠체어를 탄 사람도 자유롭게 다니면 좋겠다."],"title":"인권 사진전 한 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_challenge#6','soc',5,1,'u3','L09','g5_1_soc_u3_L09_challenge','lesson_challenge','SO5-1-u3-C15',3,'ox','auto','나의 인권을 가장 먼저 다 보호한 다음에야 다른 사람의 인권에 관심을 가질 수 있어요.',ARRAY['SO5-1-u3-X14']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C15","difficulty":3,"kind":"ox","stem":"나의 인권을 가장 먼저 다 보호한 다음에야 다른 사람의 인권에 관심을 가질 수 있어요.","answer":"X","reason_options":[{"t":"나의 인권이 소중한 만큼 다른 사람의 인권도 소중해 함께 지켜야 하기 때문에","correct":true},{"t":"다른 사람의 인권은 나와 관계없기 때문에","mis":"SO5-1-u3-X14"}],"mis":"SO5-1-u3-X14","explanation":["차례가 있는 게 아니에요.","함께 소중해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_challenge#7','soc',5,1,'u3','L09','g5_1_soc_u3_L09_challenge','lesson_challenge','SO5-1-u3-C15',3,'error','auto','생활 속 인권 보호 실천을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C15","difficulty":3,"kind":"error","stem":"생활 속 인권 보호 실천을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「나는 아직 어리니까 커서 큰일을 할 수 있을 때 실천할래.」","correct":true,"mis_target":"SO5-1-u3-X23"},{"t":"하율 — 「오늘부터 친구에게 존중하는 말을 쓸래.」","mis":"SO5-1-u3-X23"},{"t":"지한 — 「이웃 돕기 봉사 활동에 참여해 볼래.」","mis":"SO5-1-u3-X23"}],"explanation":["어려도 할 수 있어요.","작은 일부터예요.","태오가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_challenge#8','soc',5,1,'u3','L09','g5_1_soc_u3_L09_challenge','lesson_challenge','SO5-1-u3-C15',4,'mc','auto','모둠이 인권 보호 실천 방법을 고를 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['SO5-1-u3-X20','SO5-1-u3-X23']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C15","difficulty":4,"kind":"mc","stem":"모둠이 인권 보호 실천 방법을 고를 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"모둠별로 토의해 세 활동 가운데 하나를 고르고 차례대로 실천한다","correct":true},{"t":"한 사람이 정해 다른 모둠원은 따른다","mis":"SO5-1-u3-X20"},{"t":"세 활동을 한꺼번에 차례 없이 한다","mis":"SO5-1-u3-X23"},{"t":"가장 쉬운 걸음만 골라서 한다","mis":"SO5-1-u3-X23"}],"explanation":["함께 토의해요.","하나를 골라요.","차례대로 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_challenge#9','soc',5,1,'u3','L09','g5_1_soc_u3_L09_challenge','lesson_challenge','SO5-1-u3-C15',4,'mc','auto','인권 보호 실천과 인권을 존중하는 사회의 관계를 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C15","difficulty":4,"kind":"mc","stem":"인권 보호 실천과 인권을 존중하는 사회의 관계를 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"내가 할 수 있는 일을 찾아 꾸준히 실천하면 모든 사람의 인권을 존중하는 사회를 만들어 갈 수 있다","correct":true},{"t":"인권을 존중하는 사회는 저절로 만들어진다","mis":"SO5-1-u3-X23"},{"t":"실천은 어른들만 하면 된다","mis":"SO5-1-u3-X23"},{"t":"한 번 실천하면 다시는 하지 않아도 된다","mis":"SO5-1-u3-X23"}],"explanation":["사회는 저절로 안 바뀌어요.","모두가 꾸준히 해요.","작은 실천이 모여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L09_challenge#10','soc',5,1,'u3','L09','g5_1_soc_u3_L09_challenge','lesson_challenge','SO5-1-u3-C15',4,'essay','teacher','인권 보호 실천 방법 세 가지 가운데 하나를 골라 차례를 쓰고, 그 활동으로 알리고 싶은 내용과 내가 생활 속에서 바로 실천할 일 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u3-C15","difficulty":4,"kind":"essay","stem":"인권 보호 실천 방법 세 가지 가운데 하나를 골라 차례를 쓰고, 그 활동으로 알리고 싶은 내용과 내가 생활 속에서 바로 실천할 일 한 가지를 쓰세요.","answer_guide":{"answer":"예: 인권 사진전을 골랐다. 찍을 장면을 정하고, 침해와 보호가 대조되게 사진을 찍고, 종이에 붙여 제목과 보호 방법·찍은 까닭을 쓴 뒤, 게시하고 학교 누리집에 올린다. 계단만 있는 출입구와 경사로가 있는 출입구를 견주어 누구나 자유롭게 다닐 권리를 알리고 싶다. 나는 오늘부터 친구에게 존중하는 말을 쓰겠다.","scoring_points":["고른 활동의 차례를 썼는가","알리고 싶은 내용을 썼는가","바로 실천할 일을 썼는가"]},"explanation":["차례대로 써요.","알릴 내용을 써요.","작은 실천을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_basic#1','soc',5,1,'u3','L10','g5_1_soc_u3_L10_basic','lesson_basic','SO5-1-u3-C16',1,'mc','auto','「장애물 없는 생활 환경 인증 제도」는 무엇을 평가하는 제도인가요?',ARRAY['SO5-1-u3-X24']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C16","difficulty":1,"kind":"mc","stem":"「장애물 없는 생활 환경 인증 제도」는 무엇을 평가하는 제도인가요?","options":[{"t":"모든 사람이 건물이나 시설을 불편 없이 이용하도록 설계하고 관리하는지","correct":true},{"t":"학교의 성적","mis":"SO5-1-u3-X24"},{"t":"새 건물을 못 짓게 하는 일","mis":"SO5-1-u3-X24"},{"t":"장애가 있는 사람만 들어갈 건물","mis":"SO5-1-u3-X24"}],"explanation":["건물과 시설을 살펴요.","누구나 불편 없이요.","그것을 평가해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_basic#2','soc',5,1,'u3','L10','g5_1_soc_u3_L10_basic','lesson_basic','SO5-1-u3-C16',1,'mc','auto','학교 시설 네 갈래 가운데 세면대가 드는 갈래는 어느 것인가요?',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C16","difficulty":1,"kind":"mc","stem":"학교 시설 네 갈래 가운데 세면대가 드는 갈래는 어느 것인가요?","options":[{"t":"위생 시설","correct":true},{"t":"내부 시설","mis":"SO5-1-u3-X25"},{"t":"안내 시설","mis":"SO5-1-u3-X25"},{"t":"기타 시설","mis":"SO5-1-u3-X25"}],"explanation":["화장실·변기·세면대예요.","깨끗하게 씻는 곳이에요.","위생 시설이에요."],"asset":{"type":"passage","lines":["내부 시설 — 교실 출입문, 복도, 계단, 경사로, 승강기","위생 시설 — 화장실 출입문, 대변기, 소변기, 세면대","안내 시설 — 안내판, 점자 블록","기타 시설 — 급식실, 강당, 장애인 전용 주차 구역"],"title":"학교 시설 네 갈래"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_basic#3','soc',5,1,'u3','L10','g5_1_soc_u3_L10_basic','lesson_basic','SO5-1-u3-C16',1,'mc','auto','학교 시설 네 갈래 가운데 승강기가 드는 갈래는 어느 것인가요?',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C16","difficulty":1,"kind":"mc","stem":"학교 시설 네 갈래 가운데 승강기가 드는 갈래는 어느 것인가요?","options":[{"t":"내부 시설","correct":true},{"t":"위생 시설","mis":"SO5-1-u3-X25"},{"t":"안내 시설","mis":"SO5-1-u3-X25"},{"t":"기타 시설","mis":"SO5-1-u3-X25"}],"explanation":["출입문·복도·계단과 함께예요.","건물 안을 오가요.","내부 시설이에요."],"asset":{"type":"passage","lines":["내부 시설 — 교실 출입문, 복도, 계단, 경사로, 승강기","위생 시설 — 화장실 출입문, 대변기, 소변기, 세면대","안내 시설 — 안내판, 점자 블록","기타 시설 — 급식실, 강당, 장애인 전용 주차 구역"],"title":"학교 시설 네 갈래"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_basic#4','soc',5,1,'u3','L10','g5_1_soc_u3_L10_basic','lesson_basic','SO5-1-u3-C16',1,'ox','auto','장애물 없는 생활 환경 인증 제도는 법에 근거해 시행하는 제도예요.',ARRAY['SO5-1-u3-X24']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C16","difficulty":1,"kind":"ox","stem":"장애물 없는 생활 환경 인증 제도는 법에 근거해 시행하는 제도예요.","answer":"O","reason_options":[{"t":"모든 사람이 편리하게 생활하도록 우리 사회가 법으로 정해 시행하기 때문에","correct":true},{"t":"학교마다 마음대로 정한 약속이기 때문에","mis":"SO5-1-u3-X24"}],"mis":"SO5-1-u3-X24","explanation":["인권을 지키려고 법과 제도를 만들어요.","이 제도도 그 하나예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_basic#5','soc',5,1,'u3','L10','g5_1_soc_u3_L10_basic','lesson_basic','SO5-1-u3-C16',2,'mc','auto','이 제도로 학교가 달라진 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X24']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C16","difficulty":2,"kind":"mc","stem":"이 제도로 학교가 달라진 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"시각 장애가 있는 사람이 안전하게 드나들도록 현관에 점자 블록을 깔았다","correct":true},{"t":"현관 계단을 더 높였다","mis":"SO5-1-u3-X24"},{"t":"안내판 글자를 모두 지웠다","mis":"SO5-1-u3-X24"},{"t":"교실 문을 더 좁혔다","mis":"SO5-1-u3-X24"}],"explanation":["점자 블록을 깔았어요.","문의 폭도 정했어요.","누구나 편하게 드나들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_basic#6','soc',5,1,'u3','L10','g5_1_soc_u3_L10_basic','lesson_basic','SO5-1-u3-C16',2,'mc','auto','학교 시설을 네 갈래로 나누어 살펴보면 좋은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C16","difficulty":2,"kind":"mc","stem":"학교 시설을 네 갈래로 나누어 살펴보면 좋은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"기준이 있어 빠뜨리는 곳 없이 꼼꼼하게 살펴볼 수 있기 때문에","correct":true},{"t":"갈래가 많을수록 점수를 받기 때문에","mis":"SO5-1-u3-X25"},{"t":"한 갈래만 보면 되기 때문에","mis":"SO5-1-u3-X25"},{"t":"살펴볼 곳이 줄어들기 때문에","mis":"SO5-1-u3-X25"}],"explanation":["어디를 볼지 분명해져요.","빠뜨리는 곳이 줄어요.","꼼꼼하게 살펴요."],"asset":{"type":"passage","lines":["내부 시설 — 교실 출입문, 복도, 계단, 경사로, 승강기","위생 시설 — 화장실 출입문, 대변기, 소변기, 세면대","안내 시설 — 안내판, 점자 블록","기타 시설 — 급식실, 강당, 장애인 전용 주차 구역"],"title":"학교 시설 네 갈래"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_basic#7','soc',5,1,'u3','L10','g5_1_soc_u3_L10_basic','lesson_basic','SO5-1-u3-C16',2,'mc','auto','제안서 한 줄의 세 칸에서 「무엇을 위해」 칸이 하는 일은 어느 것인가요?',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C16","difficulty":2,"kind":"mc","stem":"제안서 한 줄의 세 칸에서 「무엇을 위해」 칸이 하는 일은 어느 것인가요?","options":[{"t":"그 시설이 누구에게 어떤 도움이 되는지 밝힌다","correct":true},{"t":"시설의 값을 적는다","mis":"SO5-1-u3-X25"},{"t":"시설을 놓을 곳을 적는다","mis":"SO5-1-u3-X25"},{"t":"제안한 사람 이름을 적는다","mis":"SO5-1-u3-X25"}],"explanation":["어디에는 자리예요.","무엇을은 시설이에요.","무엇을 위해는 도움이에요."],"asset":{"type":"passage","lines":["어디에 — 강당의 무대에","무엇을 — 오르내리는 경사로와 벽 안전 손잡이를","무엇을 위해 — 누구나 무대에 설 수 있도록"],"title":"제안서 한 줄의 세 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_basic#8','soc',5,1,'u3','L10','g5_1_soc_u3_L10_basic','lesson_basic','SO5-1-u3-C16',2,'mc','auto','친구들이 각자 제안한 시설을 학급 전체가 함께 나누면 좋은 까닭은 어느 것인가요?',ARRAY['SO5-1-u3-X24','SO5-1-u3-X15']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C16","difficulty":2,"kind":"mc","stem":"친구들이 각자 제안한 시설을 학급 전체가 함께 나누면 좋은 까닭은 어느 것인가요?","options":[{"t":"내가 미처 보지 못한 곳을 친구가 보았다는 것을 알게 되기 때문에","correct":true},{"t":"가장 좋은 제안 하나만 남기려고","mis":"SO5-1-u3-X24"},{"t":"제안 수를 겨루려고","mis":"SO5-1-u3-X15"},{"t":"발표 시간을 줄이려고","mis":"SO5-1-u3-X24"}],"explanation":["여럿의 눈으로 봐요.","못 본 곳이 보여요.","모두가 편한 학교에 가까워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_basic#9','soc',5,1,'u3','L10','g5_1_soc_u3_L10_basic','lesson_basic','SO5-1-u3-C16',2,'ox','auto','제안한 내용이 실현된 모습을 그림으로 나타내면 무엇이 어떻게 달라지는지 한눈에 볼 수 있어요.',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C16","difficulty":2,"kind":"ox","stem":"제안한 내용이 실현된 모습을 그림으로 나타내면 무엇이 어떻게 달라지는지 한눈에 볼 수 있어요.","answer":"O","reason_options":[{"t":"글로만 쓴 제안도 그림으로 그리면 바뀐 모습이 눈에 보이기 때문에","correct":true},{"t":"그림은 제안과 아무 관계가 없기 때문에","mis":"SO5-1-u3-X25"}],"mis":"SO5-1-u3-X25","explanation":["강당 무대의 경사로를 그려요.","바뀐 모습이 보여요.","사회와 미술이 만나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_basic#10','soc',5,1,'u3','L10','g5_1_soc_u3_L10_basic','lesson_basic','SO5-1-u3-C16',3,'error','auto','인증 제도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X24']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C16","difficulty":3,"kind":"error","stem":"인증 제도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「이 제도는 장애가 있는 사람만을 위한 거야.」","correct":true,"mis_target":"SO5-1-u3-X24"},{"t":"시윤 — 「어린이·노인·임산부 모두를 위한 제도야.」","mis":"SO5-1-u3-X24"},{"t":"민결 — 「건물을 편하게 쓰도록 설계하고 관리하는지 평가해.」","mis":"SO5-1-u3-X24"}],"explanation":["모든 사람을 위한 제도예요.","어린이도 노인도요.","라온이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_challenge#1','soc',5,1,'u3','L10','g5_1_soc_u3_L10_challenge','lesson_challenge','SO5-1-u3-C16',2,'match','auto','학교 시설과 네 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u3-C16","difficulty":2,"kind":"match","stem":"학교 시설과 네 갈래를 알맞게 이으세요.","pairs":[{"l":"경사로","r":"내부 시설"},{"l":"소변기","r":"위생 시설"},{"l":"안내판","r":"안내 시설"},{"l":"장애인 전용 주차 구역","r":"기타 시설"}],"mis":"SO5-1-u3-X25","explanation":["경사로는 건물 안 오가는 시설이에요.","소변기는 위생이에요.","안내판은 안내, 주차 구역은 기타예요."],"asset":{"type":"passage","lines":["내부 시설 — 교실 출입문, 복도, 계단, 경사로, 승강기","위생 시설 — 화장실 출입문, 대변기, 소변기, 세면대","안내 시설 — 안내판, 점자 블록","기타 시설 — 급식실, 강당, 장애인 전용 주차 구역"],"title":"학교 시설 네 갈래"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_challenge#2','soc',5,1,'u3','L10','g5_1_soc_u3_L10_challenge','lesson_challenge','SO5-1-u3-C16',2,'mc','auto','제안서에서 「강당의 무대에」를 골랐을 때 어울리는 시설은 어느 것인가요?',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C16","difficulty":2,"kind":"mc","stem":"제안서에서 「강당의 무대에」를 골랐을 때 어울리는 시설은 어느 것인가요?","options":[{"t":"오르내리는 경사로와 벽 안전 손잡이","correct":true},{"t":"음성 지원 학교 안내판","mis":"SO5-1-u3-X25"},{"t":"장애인 전용 화장실","mis":"SO5-1-u3-X25"},{"t":"교실 문턱 없애기","mis":"SO5-1-u3-X25"}],"explanation":["무대는 오르내리는 곳이에요.","경사로가 필요해요.","손잡이도 함께요."],"asset":{"type":"passage","lines":["어디에 — 강당의 무대에","무엇을 — 오르내리는 경사로와 벽 안전 손잡이를","무엇을 위해 — 누구나 무대에 설 수 있도록"],"title":"제안서 한 줄의 세 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_challenge#3','soc',5,1,'u3','L10','g5_1_soc_u3_L10_challenge','lesson_challenge','SO5-1-u3-C16',3,'mc','auto','제안서 판이 세 칸이 다 채워진 뒤에야 맞다·아니다를 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C16","difficulty":3,"kind":"mc","stem":"제안서 판이 세 칸이 다 채워진 뒤에야 맞다·아니다를 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"어디에·무엇을·무엇을 위해가 모두 모여야 제안 한 줄이 되기 때문에","correct":true},{"t":"판이 고장 났기 때문에","mis":"SO5-1-u3-X25"},{"t":"조각을 세 개까지만 고를 수 있기 때문에","mis":"SO5-1-u3-X25"},{"t":"제안에는 옳고 그름이 하나도 없기 때문에","mis":"SO5-1-u3-X25"}],"explanation":["「강당의 무대에」만으로는 부족해요.","시설만으로도 부족해요.","세 칸이 모여야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_challenge#4','soc',5,1,'u3','L10','g5_1_soc_u3_L10_challenge','lesson_challenge','SO5-1-u3-C16',3,'mc','auto','제안서를 내기 전에는 이미 고른 칸도 몇 번이든 바꿀 수 있었던 까닭은 어느 것인가요?',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C16","difficulty":3,"kind":"mc","stem":"제안서를 내기 전에는 이미 고른 칸도 몇 번이든 바꿀 수 있었던 까닭은 어느 것인가요?","options":[{"t":"더 알맞은 것이 떠오르면 제안을 얼마든지 고쳐 쓸 수 있기 때문에","correct":true},{"t":"판이 정답을 모르기 때문에","mis":"SO5-1-u3-X25"},{"t":"조각이 모자라기 때문에","mis":"SO5-1-u3-X25"},{"t":"한 번 고르면 원래 못 바꾸기 때문에","mis":"SO5-1-u3-X25"}],"explanation":["제안은 한 번에 완성되지 않아요.","더 살펴보며 고쳐요.","내기 전까지 고칠 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_challenge#5','soc',5,1,'u3','L10','g5_1_soc_u3_L10_challenge','lesson_challenge','SO5-1-u3-C16',3,'mc','auto','「우리 학교 복도에 점자 블록을 설치하면 좋겠습니다.」라는 제안에 덧붙이면 좋은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X25','SO5-1-u3-X24']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C16","difficulty":3,"kind":"mc","stem":"「우리 학교 복도에 점자 블록을 설치하면 좋겠습니다.」라는 제안에 덧붙이면 좋은 것은 어느 것인가요?","options":[{"t":"시각 장애가 있는 사람이 복도를 안전하게 다닐 수 있도록","correct":true},{"t":"복도 바닥 색을 바꾸려고","mis":"SO5-1-u3-X25"},{"t":"점자 블록 값이 싸서","mis":"SO5-1-u3-X25"},{"t":"내가 불편해서","mis":"SO5-1-u3-X24"}],"explanation":["어디에·무엇을은 있어요.","무엇을 위해가 빠졌어요.","누구에게 어떤 도움인지 덧붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_challenge#6','soc',5,1,'u3','L10','g5_1_soc_u3_L10_challenge','lesson_challenge','SO5-1-u3-C16',3,'ox','auto','내가 불편하지 않은 곳은 학교 시설을 살펴볼 때 빼도 돼요.',ARRAY['SO5-1-u3-X24']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C16","difficulty":3,"kind":"ox","stem":"내가 불편하지 않은 곳은 학교 시설을 살펴볼 때 빼도 돼요.","answer":"X","reason_options":[{"t":"나에게 편한 곳도 누군가에게는 불편할 수 있기 때문에","correct":true},{"t":"불편은 나만 느끼는 것이기 때문에","mis":"SO5-1-u3-X24"}],"mis":"SO5-1-u3-X24","explanation":["나에게 편한 것이 모두에게 편하지 않아요.","함께 살펴봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_challenge#7','soc',5,1,'u3','L10','g5_1_soc_u3_L10_challenge','lesson_challenge','SO5-1-u3-C16',3,'error','auto','제안하기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C16","difficulty":3,"kind":"error","stem":"제안하기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은호 — 「「경사로를 설치합니다」 한 마디면 제안이 다 된 거야.」","correct":true,"mis_target":"SO5-1-u3-X25"},{"t":"채운 — 「어디에 설치할지도 써야 해.」","mis":"SO5-1-u3-X25"},{"t":"나래 — 「누구를 위한 것인지도 밝혀야 해.」","mis":"SO5-1-u3-X25"}],"explanation":["어디에가 빠졌어요.","무엇을 위해도 빠졌어요.","은호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_challenge#8','soc',5,1,'u3','L10','g5_1_soc_u3_L10_challenge','lesson_challenge','SO5-1-u3-C16',4,'mc','auto','이 활동에서 기를 수 있는 힘을 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u3-X26','SO5-1-u3-X25','SO5-1-u3-X24']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C16","difficulty":4,"kind":"mc","stem":"이 활동에서 기를 수 있는 힘을 바르게 말한 것은 어느 것인가요?","options":[{"t":"시설을 꼼꼼히 살피는 비판적 사고력과, 배운 것과 찾은 것을 이어 제안하는 창의적 사고력","correct":true},{"t":"법 이름을 많이 외우는 힘","mis":"SO5-1-u3-X26"},{"t":"빨리 그리는 힘","mis":"SO5-1-u3-X25"},{"t":"남의 제안을 그대로 따르는 힘","mis":"SO5-1-u3-X24"}],"explanation":["꼼꼼히 살펴요.","새롭게 제안해요.","두 힘을 길러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_challenge#9','soc',5,1,'u3','L10','g5_1_soc_u3_L10_challenge','lesson_challenge','SO5-1-u3-C16',4,'mc','auto','이 단원에서 배운 인권과 「장애물 없는 생활 환경 인증 제도」의 관계를 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO5-1-u3-X24']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C16","difficulty":4,"kind":"mc","stem":"이 단원에서 배운 인권과 「장애물 없는 생활 환경 인증 제도」의 관계를 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"누구나 누려야 할 인권을 지키려고 만든 법과 제도 가운데 하나이다","correct":true},{"t":"인권과 관계없이 건물을 예쁘게 하려는 제도이다","mis":"SO5-1-u3-X24"},{"t":"장애가 있는 사람만 인권을 누리게 하는 제도이다","mis":"SO5-1-u3-X24"},{"t":"법이 아니라 학교마다 정한 약속이다","mis":"SO5-1-u3-X24"}],"explanation":["인권은 누구나 누려요.","그 권리를 지키려고 법과 제도를 만들어요.","이 제도도 그 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_L10_challenge#10','soc',5,1,'u3','L10','g5_1_soc_u3_L10_challenge','lesson_challenge','SO5-1-u3-C16',4,'essay','teacher','우리 학교에 제안하고 싶은 시설 하나를 어디에·무엇을·무엇을 위해의 세 칸으로 쓰고, 그 시설이 네 갈래 가운데 어디에 드는지와 실현된 모습을 그림으로 그린다면 어떤 장면일지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u3-C16","difficulty":4,"kind":"essay","stem":"우리 학교에 제안하고 싶은 시설 하나를 어디에·무엇을·무엇을 위해의 세 칸으로 쓰고, 그 시설이 네 갈래 가운데 어디에 드는지와 실현된 모습을 그림으로 그린다면 어떤 장면일지 쓰세요.","answer_guide":{"answer":"예: 어디에 — 강당의 무대에, 무엇을 — 오르내리는 경사로와 벽 안전 손잡이를, 무엇을 위해 — 휠체어를 탄 사람도 무대에 설 수 있도록. 강당은 기타 시설에 든다. 그림 — 휠체어를 탄 친구가 경사로로 무대에 올라 함께 발표하는 장면.","scoring_points":["세 칸을 모두 썼는가","네 갈래 가운데 알맞은 갈래를 썼는가","실현된 장면을 썼는가"]},"explanation":["세 칸을 채워요.","갈래를 찾아요.","바뀐 모습을 그려요."],"asset":{"type":"passage","lines":["어디에 — 강당의 무대에","무엇을 — 오르내리는 경사로와 벽 안전 손잡이를","무엇을 위해 — 누구나 무대에 설 수 있도록"],"title":"제안서 한 줄의 세 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#1','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C1',1,'mc','auto','하윤이네 반 인권 탐사 일지 ①에서 민규를 말린 까닭과 이어지는 것은 어느 것인가요?',ARRAY['SO5-1-u3-X01']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C1","difficulty":1,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ①에서 민규를 말린 까닭과 이어지는 것은 어느 것인가요?","options":[{"t":"자전거를 탄 채 횡단보도를 건너지 않도록 정한 법","correct":true},{"t":"양심에 맡긴 예절","mis":"SO5-1-u3-X01"},{"t":"학교 학급 규칙","mis":"SO5-1-u3-X01"},{"t":"친구끼리의 약속","mis":"SO5-1-u3-X01"}],"explanation":["건너는 사람이 다칠 수 있어요.","법으로 정해져 있어요.","내려서 끌고 건너요."],"asset":{"type":"passage","lines":["① 등굣길 — 민규가 자전거를 탄 채 횡단보도로 들어가려 했다.","녹색 어머니회 분이 「내려서 끌고 건너요」 하고 말렸다.","교문 앞에서 하윤이는 떨어진 휴지를 주워 쓰레기통에 넣었다.","아무도 시키지 않았지만 그냥 그렇게 하고 싶었다."],"title":"하윤이네 반 인권 탐사 일지 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#2','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C2',1,'mc','auto','하윤이네 반 인권 탐사 일지 ①에서 하윤이가 휴지를 주운 일은 어느 쪽에 가까운가요?',ARRAY['SO5-1-u3-X01']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C2","difficulty":1,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ①에서 하윤이가 휴지를 주운 일은 어느 쪽에 가까운가요?","options":[{"t":"양심에 따라 스스로 지킨 일","correct":true},{"t":"어기면 국가가 벌을 주는 법","mis":"SO5-1-u3-X01"},{"t":"재판으로 정한 일","mis":"SO5-1-u3-X01"},{"t":"국가가 강제로 시킨 일","mis":"SO5-1-u3-X01"}],"explanation":["아무도 시키지 않았어요.","그냥 하고 싶었어요.","양심에 따른 일이에요."],"asset":{"type":"passage","lines":["① 등굣길 — 민규가 자전거를 탄 채 횡단보도로 들어가려 했다.","녹색 어머니회 분이 「내려서 끌고 건너요」 하고 말렸다.","교문 앞에서 하윤이는 떨어진 휴지를 주워 쓰레기통에 넣었다.","아무도 시키지 않았지만 그냥 그렇게 하고 싶었다."],"title":"하윤이네 반 인권 탐사 일지 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#3','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C3',1,'mc','auto','하윤이네 반 인권 탐사 일지 ②에서 모둠이 조사한 법이 지켜 주는 것은 어느 것인가요?',ARRAY['SO5-1-u3-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C3","difficulty":1,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ②에서 모둠이 조사한 법이 지켜 주는 것은 어느 것인가요?","options":[{"t":"급식의 영양과 안전","correct":true},{"t":"놀이터의 안전","mis":"SO5-1-u3-X05"},{"t":"건물의 안전","mis":"SO5-1-u3-X05"},{"t":"창작물을 만든 사람의 권리","mis":"SO5-1-u3-X05"}],"explanation":["주제가 급식이에요.","영양과 안전을 정했어요.","「학교 급식법」이에요."],"asset":{"type":"passage","lines":["② 사회 시간 — 모둠마다 궁금한 법을 하나씩 조사했다.","우리 모둠 주제는 「급식」, 생활 법령 누리집에서 찾았다.","급식의 영양과 안전을 정한 법이 있었다.","찾은 내용을 내 말로 간추려 발표 종이에 적었다."],"title":"하윤이네 반 인권 탐사 일지 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#4','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C6',1,'mc','auto','하윤이네 반 인권 탐사 일지 ③에서 사촌 언니의 일은 법의 어떤 역할을 보여 주나요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C6","difficulty":1,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ③에서 사촌 언니의 일은 법의 어떤 역할을 보여 주나요?","options":[{"t":"개인의 권리를 보호한다","correct":true},{"t":"사회 질서를 유지한다","mis":"SO5-1-u3-X08"},{"t":"공정한 경제 질서를 지킨다","mis":"SO5-1-u3-X08"},{"t":"거리를 깨끗하게 한다","mis":"SO5-1-u3-X08"}],"explanation":["허락 없이 사진을 올렸어요.","법원이 배상하게 했어요.","개인의 권리 보호예요."],"asset":{"type":"passage","lines":["③ 사촌 언니 이야기 — 누군가 언니 사진을 허락 없이 올렸다.","언니는 손해 배상을 청구했고 법원이 배상하게 판결했다.","그날 저녁 뉴스에서는 소방차 전용 구역 이야기가 나왔다.","그 구역에 차를 세우면 과태료를 낸다고 했다."],"title":"하윤이네 반 인권 탐사 일지 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#5','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C8',1,'mc','auto','인권은 언제부터 주어지나요?',ARRAY['SO5-1-u3-X10']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C8","difficulty":1,"kind":"mc","stem":"인권은 언제부터 주어지나요?","options":[{"t":"태어나는 순간부터","correct":true},{"t":"어른이 된 뒤부터","mis":"SO5-1-u3-X10"},{"t":"학교에 들어간 뒤부터","mis":"SO5-1-u3-X10"},{"t":"일을 해서 돈을 번 뒤부터","mis":"SO5-1-u3-X10"}],"explanation":["사람이면 누구나예요.","나이와 관계없어요.","태어나면서부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#6','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C9',1,'mc','auto','하윤이네 반 인권 탐사 일지 ④에서 할머니가 투표하신 일은 헌법이 보장하는 어떤 모습인가요?',ARRAY['SO5-1-u3-X12']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C9","difficulty":1,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ④에서 할머니가 투표하신 일은 헌법이 보장하는 어떤 모습인가요?","options":[{"t":"국가의 정치에 참여하기","correct":true},{"t":"자유롭게 이사하기","mis":"SO5-1-u3-X12"},{"t":"침해되면 국가에 요구하기","mis":"SO5-1-u3-X12"},{"t":"동등하게 대우받기","mis":"SO5-1-u3-X12"}],"explanation":["선거 날 투표했어요.","나라의 일을 정해요.","정치 참여예요."],"asset":{"type":"passage","lines":["④ 주말 — 할머니는 선거 날 투표하러 가셨다.","삼촌은 일터 가까운 동네로 이사를 했다.","나는 반 친구들과 인권 소책자를 만들었다.","헌법에 담긴 인권이 우리 가족 생활 곳곳에 있었다."],"title":"하윤이네 반 인권 탐사 일지 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#7','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C12',1,'mc','auto','하윤이네 반 인권 탐사 일지 ⑤에서 빵집에 휠체어가 들어가지 못한 까닭은 어떤 인권 침해인가요?',ARRAY['SO5-1-u3-X18']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C12","difficulty":1,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑤에서 빵집에 휠체어가 들어가지 못한 까닭은 어떤 인권 침해인가요?","options":[{"t":"시설 부족","correct":true},{"t":"사생활 침해","mis":"SO5-1-u3-X18"},{"t":"사이버 폭력","mis":"SO5-1-u3-X18"},{"t":"국적에 따른 차별","mis":"SO5-1-u3-X18"}],"explanation":["입구가 계단뿐이에요.","경사로가 없어요.","시설 부족이에요."],"asset":{"type":"passage","lines":["⑤ 동네 탐사 — 빵집 입구가 계단뿐이라 휠체어가 못 들어갔다.","공사장 소음이 밤늦게까지 이어져 이웃이 잠을 못 잔다.","이웃 아저씨는 다른 나라에서 왔다고 월급을 적게 받는다.","놀이터에서는 아이들이 차례를 지키며 서로 양보했다."],"title":"하윤이네 반 인권 탐사 일지 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#8','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C14',1,'mc','auto','하윤이네 반 인권 탐사 일지 ⑦에서 큰 글자 도서로 배려하는 사람은 누구인가요?',ARRAY['SO5-1-u3-X21']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C14","difficulty":1,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑦에서 큰 글자 도서로 배려하는 사람은 누구인가요?","options":[{"t":"노인","correct":true},{"t":"어린이","mis":"SO5-1-u3-X21"},{"t":"임산부","mis":"SO5-1-u3-X21"},{"t":"운전자","mis":"SO5-1-u3-X21"}],"explanation":["작은 글씨가 어려워요.","글자를 크게 했어요.","노인을 배려해요."],"asset":{"type":"passage","lines":["⑦ 배려 찾기 — 도서관에서 큰 글자 도서를, 횡단보도에서 옐로 카펫을 봤다.","학교에서는 계단 점자 블록과 경사로를 찾았다.","복지관에서 사회 복지사 선생님을 만나 하는 일을 들었다.","어려운 사람의 생활을 돕는 나라의 제도도 알게 되었다."],"title":"하윤이네 반 인권 탐사 일지 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#9','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C2',2,'mc','auto','하윤이네 반 인권 탐사 일지 ①의 두 일을 견준 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C2","difficulty":2,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ①의 두 일을 견준 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"자전거 일은 법이 필요한 일이고, 휴지 줍기는 양심에 맡긴 일이다","correct":true},{"t":"두 일 모두 법으로 정한 일이다","mis":"SO5-1-u3-X03"},{"t":"두 일 모두 양심에 맡긴 일이다","mis":"SO5-1-u3-X03"},{"t":"휴지 줍기만 법으로 정한 일이다","mis":"SO5-1-u3-X03"}],"explanation":["자전거는 다칠 수 있어요.","휴지는 스스로 해요.","서로 달라요."],"asset":{"type":"passage","lines":["① 등굣길 — 민규가 자전거를 탄 채 횡단보도로 들어가려 했다.","녹색 어머니회 분이 「내려서 끌고 건너요」 하고 말렸다.","교문 앞에서 하윤이는 떨어진 휴지를 주워 쓰레기통에 넣었다.","아무도 시키지 않았지만 그냥 그렇게 하고 싶었다."],"title":"하윤이네 반 인권 탐사 일지 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#10','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C5',2,'mc','auto','법이 없다면 생길 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X07']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C5","difficulty":2,"kind":"mc","stem":"법이 없다면 생길 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"다툼이 생겨도 해결할 기준이 없어 갈등이 커진다","correct":true},{"t":"모두가 더 사이좋게 지낸다","mis":"SO5-1-u3-X07"},{"t":"아무 일도 달라지지 않는다","mis":"SO5-1-u3-X07"},{"t":"법이 없어도 질서가 저절로 지켜진다","mis":"SO5-1-u3-X07"}],"explanation":["기준이 사라져요.","다툼이 풀리지 않아요.","갈등이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#11','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C6',2,'match','auto','하윤이네 반 인권 탐사 일지 ③과 생활 속에서 법이 하는 일을 그 역할과 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SO5-1-u3-C6","difficulty":2,"kind":"match","stem":"하윤이네 반 인권 탐사 일지 ③과 생활 속에서 법이 하는 일을 그 역할과 알맞게 이으세요.","pairs":[{"l":"사진 무단 게시에 배상 판결","r":"개인의 권리 보호"},{"l":"소방차 전용 구역 과태료","r":"사회 질서 유지"},{"l":"개인 안심 번호","r":"개인 정보 보호"},{"l":"공정한 거래","r":"경제 질서 유지"}],"mis":"SO5-1-u3-X08","explanation":["한 사람을 지키면 권리 보호예요.","모두를 지키면 질서 유지예요.","역할을 나누어요."],"asset":{"type":"passage","lines":["③ 사촌 언니 이야기 — 누군가 언니 사진을 허락 없이 올렸다.","언니는 손해 배상을 청구했고 법원이 배상하게 판결했다.","그날 저녁 뉴스에서는 소방차 전용 구역 이야기가 나왔다.","그 구역에 차를 세우면 과태료를 낸다고 했다."],"title":"하윤이네 반 인권 탐사 일지 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#12','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C10',2,'mc','auto','친구 사진을 단체 대화방에 올리고 싶을 때 바른 행동은 어느 것인가요?',ARRAY['SO5-1-u3-X13']::text[],false,'{"seq":12,"concept":"SO5-1-u3-C10","difficulty":2,"kind":"mc","stem":"친구 사진을 단체 대화방에 올리고 싶을 때 바른 행동은 어느 것인가요?","options":[{"t":"먼저 친구에게 허락을 받는다","correct":true},{"t":"얼굴만 가리고 마음대로 올린다","mis":"SO5-1-u3-X13"},{"t":"친한 친구니까 그냥 올린다","mis":"SO5-1-u3-X13"},{"t":"들키지 않게 빨리 지운다","mis":"SO5-1-u3-X13"}],"explanation":["허락이 먼저예요.","초상권을 지켜요.","그다음 올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#13','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C11',2,'mc','auto','캠페인 활동을 하는 목적으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X15']::text[],false,'{"seq":13,"concept":"SO5-1-u3-C11","difficulty":2,"kind":"mc","stem":"캠페인 활동을 하는 목적으로 알맞은 것은 어느 것인가요?","options":[{"t":"중요성을 알리고 함께 참여하도록 한다","correct":true},{"t":"공감 수로 순위를 정한다","mis":"SO5-1-u3-X15"},{"t":"혼자 알고 있는다","mis":"SO5-1-u3-X15"},{"t":"글씨를 예쁘게 쓴다","mis":"SO5-1-u3-X15"}],"explanation":["알리는 활동이에요.","함께 참여해요.","그것이 목적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#14','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C12',2,'mc','auto','하윤이네 반 인권 탐사 일지 ⑤에서 이웃 아저씨가 보호받지 못한 권리는 어느 것인가요?',ARRAY['SO5-1-u3-X18']::text[],false,'{"seq":14,"concept":"SO5-1-u3-C12","difficulty":2,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑤에서 이웃 아저씨가 보호받지 못한 권리는 어느 것인가요?","options":[{"t":"차별받지 않고 동등하게 대우받을 권리","correct":true},{"t":"햇빛을 받을 권리","mis":"SO5-1-u3-X18"},{"t":"이사를 갈 권리","mis":"SO5-1-u3-X18"},{"t":"투표할 권리","mis":"SO5-1-u3-X18"}],"explanation":["다른 나라에서 왔어요.","월급을 적게 받아요.","국적 차별이에요."],"asset":{"type":"passage","lines":["⑤ 동네 탐사 — 빵집 입구가 계단뿐이라 휠체어가 못 들어갔다.","공사장 소음이 밤늦게까지 이어져 이웃이 잠을 못 잔다.","이웃 아저씨는 다른 나라에서 왔다고 월급을 적게 받는다.","놀이터에서는 아이들이 차례를 지키며 서로 양보했다."],"title":"하윤이네 반 인권 탐사 일지 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#15','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C13',2,'mc','auto','하윤이네 반 인권 탐사 일지 ⑥에서 모둠 의견으로 정해질 방법은 어느 것인가요?',ARRAY['SO5-1-u3-X20']::text[],false,'{"seq":15,"concept":"SO5-1-u3-C13","difficulty":2,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑥에서 모둠 의견으로 정해질 방법은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"SO5-1-u3-X20"},{"t":"㉰","mis":"SO5-1-u3-X20"},{"t":"정할 수 없다","mis":"SO5-1-u3-X20"}],"explanation":["별을 모아 봐요.","㉮가 5개로 가장 많아요.","㉮가 모둠 의견이에요."],"asset":{"type":"passage","lines":["⑥ 학급 토의 — 문제: 전학 온 친구의 말투를 흉내 내며 놀린다.","원인: 「다른 말투는 이상하다」는 생각.","방법 ㉮ 여러 지역 말 알아보기 시간 — 별 5개","방법 ㉯ 놀린 친구를 일주일 동안 혼자 앉게 하기 — 별 1개","방법 ㉰ 서로의 고향 이야기 나누기 — 별 3개"],"title":"하윤이네 반 인권 탐사 일지 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#16','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C16',2,'mc','auto','하윤이네 반 인권 탐사 일지 ⑧의 제안은 학교 시설 네 갈래 가운데 어디에 드나요?',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":16,"concept":"SO5-1-u3-C16","difficulty":2,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑧의 제안은 학교 시설 네 갈래 가운데 어디에 드나요?","options":[{"t":"기타 시설","correct":true},{"t":"위생 시설","mis":"SO5-1-u3-X25"},{"t":"안내 시설","mis":"SO5-1-u3-X25"},{"t":"학교 밖 시설","mis":"SO5-1-u3-X25"}],"explanation":["강당 무대예요.","강당은 기타 시설이에요.","급식실·주차 구역과 함께예요."],"asset":{"type":"passage","lines":["⑧ 별빛초 제안 — 강당 무대는 계단뿐이라 휠체어로 오를 수 없다.","우리 모둠 제안: 강당 무대에 경사로와 안전 손잡이를","휠체어를 탄 친구도 무대에서 발표할 수 있도록.","실현된 모습을 그림으로 그려 학급에 게시했다."],"title":"하윤이네 반 인권 탐사 일지 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#17','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C7',3,'mc','auto','하윤이네 반 인권 탐사 일지 ③의 두 이야기를 견줄 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":17,"concept":"SO5-1-u3-C7","difficulty":3,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ③의 두 이야기를 견줄 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"언니 일은 개인의 권리 보호이고, 뉴스는 사회 질서 유지이다","correct":true},{"t":"두 이야기 모두 개인 정보 보호이다","mis":"SO5-1-u3-X08"},{"t":"두 이야기 모두 교통질서 유지이다","mis":"SO5-1-u3-X08"},{"t":"언니 일은 질서 유지, 뉴스는 권리 보호이다","mis":"SO5-1-u3-X08"}],"explanation":["언니 한 사람을 지켰어요.","뉴스는 모두의 안전이에요.","역할이 달라요."],"asset":{"type":"passage","lines":["③ 사촌 언니 이야기 — 누군가 언니 사진을 허락 없이 올렸다.","언니는 손해 배상을 청구했고 법원이 배상하게 판결했다.","그날 저녁 뉴스에서는 소방차 전용 구역 이야기가 나왔다.","그 구역에 차를 세우면 과태료를 낸다고 했다."],"title":"하윤이네 반 인권 탐사 일지 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#18','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C9',3,'match','auto','하윤이네 반 인권 탐사 일지 ④와 생활 속 장면을 헌법의 인권 보장 모습과 알맞게 이으세요.','{}'::text[],false,'{"seq":18,"concept":"SO5-1-u3-C9","difficulty":3,"kind":"match","stem":"하윤이네 반 인권 탐사 일지 ④와 생활 속 장면을 헌법의 인권 보장 모습과 알맞게 이으세요.","pairs":[{"l":"할머니의 투표","r":"정치에 참여하기"},{"l":"삼촌의 이사","r":"자유롭게 행동하기"},{"l":"억울한 일의 재판","r":"침해되면 국가에 요구하기"},{"l":"모든 어린이의 교육","r":"더 나은 삶을 요구하기"}],"mis":"SO5-1-u3-X12","explanation":["투표는 정치 참여예요.","이사는 자유예요.","재판과 교육도 짝을 찾아요."],"asset":{"type":"passage","lines":["④ 주말 — 할머니는 선거 날 투표하러 가셨다.","삼촌은 일터 가까운 동네로 이사를 했다.","나는 반 친구들과 인권 소책자를 만들었다.","헌법에 담긴 인권이 우리 가족 생활 곳곳에 있었다."],"title":"하윤이네 반 인권 탐사 일지 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#19','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C13',3,'mc','auto','하윤이네 반 인권 탐사 일지 ⑥에서 ㉯ 방법이 별을 적게 받은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X20','SO5-1-u3-X19']::text[],false,'{"seq":19,"concept":"SO5-1-u3-C13","difficulty":3,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑥에서 ㉯ 방법이 별을 적게 받은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"놀린 친구를 혼자 앉게 해 또 다른 상처를 주고 원인인 편견은 줄이지 못하기 때문에","correct":true},{"t":"글자 수가 적기 때문에","mis":"SO5-1-u3-X20"},{"t":"가장 늦게 나온 방법이기 때문에","mis":"SO5-1-u3-X20"},{"t":"놀린 친구를 벌주는 것이 가장 좋기 때문에","mis":"SO5-1-u3-X19"}],"explanation":["또 다른 상처예요.","편견은 그대로예요.","그래서 별이 적어요."],"asset":{"type":"passage","lines":["⑥ 학급 토의 — 문제: 전학 온 친구의 말투를 흉내 내며 놀린다.","원인: 「다른 말투는 이상하다」는 생각.","방법 ㉮ 여러 지역 말 알아보기 시간 — 별 5개","방법 ㉯ 놀린 친구를 일주일 동안 혼자 앉게 하기 — 별 1개","방법 ㉰ 서로의 고향 이야기 나누기 — 별 3개"],"title":"하윤이네 반 인권 탐사 일지 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#20','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C14',3,'mc','auto','하윤이네 반 인권 탐사 일지 ⑦에 나온 것들을 노력의 주체로 바르게 나눈 것은 어느 것인가요?',ARRAY['SO5-1-u3-X21']::text[],false,'{"seq":20,"concept":"SO5-1-u3-C14","difficulty":3,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑦에 나온 것들을 노력의 주체로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"큰 글자 도서·옐로 카펫은 주변, 점자 블록·경사로는 학교, 어려운 사람을 돕는 제도는 국가","correct":true},{"t":"모두 학교의 노력이다","mis":"SO5-1-u3-X21"},{"t":"모두 국가의 노력이다","mis":"SO5-1-u3-X21"},{"t":"경사로는 국가, 제도는 학교의 노력이다","mis":"SO5-1-u3-X21"}],"explanation":["주변의 배려 시설이에요.","학교의 인권 보호 시설이에요.","국가의 제도예요."],"asset":{"type":"passage","lines":["⑦ 배려 찾기 — 도서관에서 큰 글자 도서를, 횡단보도에서 옐로 카펫을 봤다.","학교에서는 계단 점자 블록과 경사로를 찾았다.","복지관에서 사회 복지사 선생님을 만나 하는 일을 들었다.","어려운 사람의 생활을 돕는 나라의 제도도 알게 되었다."],"title":"하윤이네 반 인권 탐사 일지 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#21','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C15',3,'mc','auto','하윤이네 반이 인권 사진전을 한다면 하윤이네 반 인권 탐사 일지 ⑤의 빵집과 대조되게 찍을 사진으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":21,"concept":"SO5-1-u3-C15","difficulty":3,"kind":"mc","stem":"하윤이네 반이 인권 사진전을 한다면 하윤이네 반 인권 탐사 일지 ⑤의 빵집과 대조되게 찍을 사진으로 알맞은 것은 어느 것인가요?","options":[{"t":"경사로가 있어 휠체어로 드나드는 가게 입구","correct":true},{"t":"계단이 더 높은 가게 입구","mis":"SO5-1-u3-X23"},{"t":"문이 닫힌 가게","mis":"SO5-1-u3-X23"},{"t":"사람이 없는 거리","mis":"SO5-1-u3-X23"}],"explanation":["침해와 보호를 견줘요.","경사로가 보호예요.","대조되게 찍어요."],"asset":{"type":"passage","lines":["⑤ 동네 탐사 — 빵집 입구가 계단뿐이라 휠체어가 못 들어갔다.","공사장 소음이 밤늦게까지 이어져 이웃이 잠을 못 잔다.","이웃 아저씨는 다른 나라에서 왔다고 월급을 적게 받는다.","놀이터에서는 아이들이 차례를 지키며 서로 양보했다."],"title":"하윤이네 반 인권 탐사 일지 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#22','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C16',3,'mc','auto','하윤이네 반 인권 탐사 일지 ⑧에서 제안을 그림으로 그려 게시한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X15','SO5-1-u3-X25']::text[],false,'{"seq":22,"concept":"SO5-1-u3-C16","difficulty":3,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑧에서 제안을 그림으로 그려 게시한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실현되면 무엇이 어떻게 달라지는지 한눈에 보여 주고 함께 생각을 나누려고","correct":true},{"t":"그림 점수를 받으려고","mis":"SO5-1-u3-X15"},{"t":"글을 쓰기 싫어서","mis":"SO5-1-u3-X25"},{"t":"제안 수를 겨루려고","mis":"SO5-1-u3-X15"}],"explanation":["바뀐 모습이 보여요.","학급이 함께 봐요.","생각을 나눠요."],"asset":{"type":"passage","lines":["⑧ 별빛초 제안 — 강당 무대는 계단뿐이라 휠체어로 오를 수 없다.","우리 모둠 제안: 강당 무대에 경사로와 안전 손잡이를","휠체어를 탄 친구도 무대에서 발표할 수 있도록.","실현된 모습을 그림으로 그려 학급에 게시했다."],"title":"하윤이네 반 인권 탐사 일지 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#23','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C1',4,'mc','auto','「법과 인권의 보장」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u3-X10','SO5-1-u3-X26','SO5-1-u3-X19']::text[],false,'{"seq":23,"concept":"SO5-1-u3-C1","difficulty":4,"kind":"mc","stem":"「법과 인권의 보장」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"법은 권리를 지키고 질서를 유지하며, 헌법이 보장하는 인권이 침해될 때 원인을 찾아 함께 해결하고 생활 속에서 보호를 실천한다","correct":true},{"t":"법은 어른의 일이고 인권은 어른만 누린다","mis":"SO5-1-u3-X10"},{"t":"법과 인권은 이름과 조항을 외우면 된다","mis":"SO5-1-u3-X26"},{"t":"인권 침해는 저절로 사라지므로 기다리면 된다","mis":"SO5-1-u3-X19"}],"explanation":["법의 뜻과 역할이에요.","헌법과 인권이에요.","해결하고 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#24','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C2',4,'essay','teacher','하윤이네 반 인권 탐사 일지 ①의 두 일을 견주어 법과 양심에 따른 약속의 차이를 쓰고, 법이 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u3-C2","difficulty":4,"kind":"essay","stem":"하윤이네 반 인권 탐사 일지 ①의 두 일을 견주어 법과 양심에 따른 약속의 차이를 쓰고, 법이 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 자전거를 탄 채 횡단보도를 건너는 일은 사람을 다치게 할 수 있어 법으로 정해져 있고 어기면 국가의 제재를 받는다. 휴지를 줍는 일은 양심에 따라 스스로 지키는 약속이라 안 해도 제재가 없다. 법은 문제가 생겼을 때 사람들 사이의 갈등이나 다툼을 해결하는 기준이 되므로 필요하다.","scoring_points":["자전거 일을 법과 이어 썼는가","휴지 줍기를 양심과 이어 썼는가","법이 필요한 까닭을 썼는가"]},"explanation":["두 일을 견줘요.","제재가 있는지 봐요.","기준이 되는 까닭을 써요."],"asset":{"type":"passage","lines":["① 등굣길 — 민규가 자전거를 탄 채 횡단보도로 들어가려 했다.","녹색 어머니회 분이 「내려서 끌고 건너요」 하고 말렸다.","교문 앞에서 하윤이는 떨어진 휴지를 주워 쓰레기통에 넣었다.","아무도 시키지 않았지만 그냥 그렇게 하고 싶었다."],"title":"하윤이네 반 인권 탐사 일지 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_a#25','soc',5,1,'u3','','g5_1_soc_u3_review_a','unit_review','SO5-1-u3-C12',4,'essay','teacher','하윤이네 반 인권 탐사 일지 ⑤에서 인권 침해 두 가지를 찾아 각각 어떤 권리를 보호받지 못했는지 쓰고, 이런 일이 계속되면 생길 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u3-C12","difficulty":4,"kind":"essay","stem":"하윤이네 반 인권 탐사 일지 ⑤에서 인권 침해 두 가지를 찾아 각각 어떤 권리를 보호받지 못했는지 쓰고, 이런 일이 계속되면 생길 일을 쓰세요.","answer_guide":{"answer":"예: 빵집 입구가 계단뿐이라 휠체어를 탄 사람이 들어가지 못한 것은 시설 부족으로 누구나 자유롭게 드나들 권리를 보호받지 못한 것이다. 이웃 아저씨가 다른 나라에서 왔다고 월급을 적게 받는 것은 차별받지 않고 동등하게 대우받을 권리를 보호받지 못한 것이다. 이런 일이 계속되면 생활에 불편함을 겪고 인간다운 삶을 누리지 못하는 사람이 늘어날 것이다.","scoring_points":["침해 두 가지를 찾았는가","보호받지 못한 권리를 썼는가","계속될 때 생길 일을 썼는가"]},"explanation":["두 가지를 찾아요.","어떤 권리인지 써요.","이어질 일을 써요."],"asset":{"type":"passage","lines":["⑤ 동네 탐사 — 빵집 입구가 계단뿐이라 휠체어가 못 들어갔다.","공사장 소음이 밤늦게까지 이어져 이웃이 잠을 못 잔다.","이웃 아저씨는 다른 나라에서 왔다고 월급을 적게 받는다.","놀이터에서는 아이들이 차례를 지키며 서로 양보했다."],"title":"하윤이네 반 인권 탐사 일지 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#1','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C1',1,'sa','auto','법을 어겼을 때 국가가 하는 처벌이나 금지를 두 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u3-C1","difficulty":1,"kind":"sa","stem":"법을 어겼을 때 국가가 하는 처벌이나 금지를 두 글자로 무엇이라고 하나요?","answer":["제재"],"explanation":["국가가 해요.","처벌이나 금지예요.","제재예요."],"mis":"SO5-1-u3-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#2','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C2',1,'ox','auto','웃어른께 인사하지 않으면 국가로부터 제재를 받아요.',ARRAY['SO5-1-u3-X03']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C2","difficulty":1,"kind":"ox","stem":"웃어른께 인사하지 않으면 국가로부터 제재를 받아요.","answer":"X","reason_options":[{"t":"인사는 위험한 일이 아니라 양심에 따라 스스로 지키는 예절이기 때문에","correct":true},{"t":"인사는 법으로 반드시 정해 둔 일이기 때문에","mis":"SO5-1-u3-X03"}],"mis":"SO5-1-u3-X03","explanation":["인사는 좋은 예절이에요.","하지만 법은 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#3','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C4',1,'mc','auto','병원에서 의사에게 진찰을 받는 일과 이어지는 법은 어느 것인가요?',ARRAY['SO5-1-u3-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C4","difficulty":1,"kind":"mc","stem":"병원에서 의사에게 진찰을 받는 일과 이어지는 법은 어느 것인가요?","options":[{"t":"「의료법」","correct":true},{"t":"「건축법」","mis":"SO5-1-u3-X05"},{"t":"「저작권법」","mis":"SO5-1-u3-X05"},{"t":"「소방 기본법」","mis":"SO5-1-u3-X05"}],"explanation":["진찰은 의료예요.","병원의 일이에요.","「의료법」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#4','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C7',1,'mc','auto','하윤이네 반 인권 탐사 일지 ③의 뉴스에 나온 법은 어떤 역할을 하나요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C7","difficulty":1,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ③의 뉴스에 나온 법은 어떤 역할을 하나요?","options":[{"t":"사회 질서를 유지한다","correct":true},{"t":"개인 정보를 보호한다","mis":"SO5-1-u3-X08"},{"t":"창작물을 보호한다","mis":"SO5-1-u3-X08"},{"t":"개인 사이의 다툼을 해결한다","mis":"SO5-1-u3-X08"}],"explanation":["소방차 길을 지켜요.","모두의 안전이에요.","사회 질서 유지예요."],"asset":{"type":"passage","lines":["③ 사촌 언니 이야기 — 누군가 언니 사진을 허락 없이 올렸다.","언니는 손해 배상을 청구했고 법원이 배상하게 판결했다.","그날 저녁 뉴스에서는 소방차 전용 구역 이야기가 나왔다.","그 구역에 차를 세우면 과태료를 낸다고 했다."],"title":"하윤이네 반 인권 탐사 일지 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#5','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C8',1,'ox','auto','인권은 다른 사람이 힘이나 권력으로 함부로 빼앗을 수 없어요.',ARRAY['SO5-1-u3-X10']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C8","difficulty":1,"kind":"ox","stem":"인권은 다른 사람이 힘이나 권력으로 함부로 빼앗을 수 없어요.","answer":"O","reason_options":[{"t":"사람이면 누구나 누려야 할 기본적인 권리이기 때문에","correct":true},{"t":"힘이 센 사람은 빼앗을 수 있기 때문에","mis":"SO5-1-u3-X10"}],"mis":"SO5-1-u3-X10","explanation":["기본적인 권리예요.","빼앗을 수 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#6','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C9',1,'mc','auto','하윤이네 반 인권 탐사 일지 ④에서 삼촌이 이사한 일은 헌법이 보장하는 어떤 모습인가요?',ARRAY['SO5-1-u3-X12']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C9","difficulty":1,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ④에서 삼촌이 이사한 일은 헌법이 보장하는 어떤 모습인가요?","options":[{"t":"국가의 간섭 없이 자유롭게 행동하기","correct":true},{"t":"국가의 정치에 참여하기","mis":"SO5-1-u3-X12"},{"t":"더 나은 삶을 국가에 요구하기","mis":"SO5-1-u3-X12"},{"t":"재판을 받기","mis":"SO5-1-u3-X12"}],"explanation":["살고 싶은 곳으로 옮겼어요.","나라가 막지 않아요.","자유예요."],"asset":{"type":"passage","lines":["④ 주말 — 할머니는 선거 날 투표하러 가셨다.","삼촌은 일터 가까운 동네로 이사를 했다.","나는 반 친구들과 인권 소책자를 만들었다.","헌법에 담긴 인권이 우리 가족 생활 곳곳에 있었다."],"title":"하윤이네 반 인권 탐사 일지 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#7','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C12',1,'mc','auto','하윤이네 반 인권 탐사 일지 ⑤에서 인권이 침해되는 모습이 아닌 것은 어느 것인가요?',ARRAY['SO5-1-u3-X16']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C12","difficulty":1,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑤에서 인권이 침해되는 모습이 아닌 것은 어느 것인가요?","options":[{"t":"아이들이 차례를 지키며 서로 양보한 일","correct":true},{"t":"계단뿐인 빵집 입구","mis":"SO5-1-u3-X16"},{"t":"밤늦게까지 이어지는 공사장 소음","mis":"SO5-1-u3-X16"},{"t":"다른 나라에서 왔다고 적게 주는 월급","mis":"SO5-1-u3-X16"}],"explanation":["양보는 존중이에요.","침해가 아니에요.","나머지는 침해예요."],"asset":{"type":"passage","lines":["⑤ 동네 탐사 — 빵집 입구가 계단뿐이라 휠체어가 못 들어갔다.","공사장 소음이 밤늦게까지 이어져 이웃이 잠을 못 잔다.","이웃 아저씨는 다른 나라에서 왔다고 월급을 적게 받는다.","놀이터에서는 아이들이 차례를 지키며 서로 양보했다."],"title":"하윤이네 반 인권 탐사 일지 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#8','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C14',1,'mc','auto','하윤이네 반 인권 탐사 일지 ⑦에서 옐로 카펫을 만든 까닭은 어느 것인가요?',ARRAY['SO5-1-u3-X21']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C14","difficulty":1,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑦에서 옐로 카펫을 만든 까닭은 어느 것인가요?","options":[{"t":"어린이 교통사고를 막으려고","correct":true},{"t":"길을 예쁘게 꾸미려고","mis":"SO5-1-u3-X21"},{"t":"차가 빨리 달리게 하려고","mis":"SO5-1-u3-X21"},{"t":"주차 구역을 넓히려고","mis":"SO5-1-u3-X21"}],"explanation":["노란색이 눈에 띄어요.","어린이를 지켜요.","사고를 막아요."],"asset":{"type":"passage","lines":["⑦ 배려 찾기 — 도서관에서 큰 글자 도서를, 횡단보도에서 옐로 카펫을 봤다.","학교에서는 계단 점자 블록과 경사로를 찾았다.","복지관에서 사회 복지사 선생님을 만나 하는 일을 들었다.","어려운 사람의 생활을 돕는 나라의 제도도 알게 되었다."],"title":"하윤이네 반 인권 탐사 일지 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#9','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C1',2,'error','auto','하윤이네 반 인권 탐사 일지 ①을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X01','SO5-1-u3-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C1","difficulty":2,"kind":"error","stem":"하윤이네 반 인권 탐사 일지 ①을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「하윤이가 휴지를 안 주웠다면 나라에서 제재를 받았을 거야.」","correct":true,"mis_target":"SO5-1-u3-X01"},{"t":"세온 — 「자전거를 끌고 건너는 건 법을 지키는 거야.」","mis":"SO5-1-u3-X03"},{"t":"태하 — 「휴지 줍기는 양심에 따라 한 일이야.」","mis":"SO5-1-u3-X01"}],"explanation":["휴지 줍기는 양심의 일이에요.","제재가 없어요.","지아가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 등굣길 — 민규가 자전거를 탄 채 횡단보도로 들어가려 했다.","녹색 어머니회 분이 「내려서 끌고 건너요」 하고 말렸다.","교문 앞에서 하윤이는 떨어진 휴지를 주워 쓰레기통에 넣었다.","아무도 시키지 않았지만 그냥 그렇게 하고 싶었다."],"title":"하윤이네 반 인권 탐사 일지 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#10','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C5',2,'ox','auto','법은 누구에게나 똑같이 적용되어야 해요.',ARRAY['SO5-1-u3-X09']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C5","difficulty":2,"kind":"ox","stem":"법은 누구에게나 똑같이 적용되어야 해요.","answer":"O","reason_options":[{"t":"사람마다 다르면 다툼을 해결하는 기준이 될 수 없기 때문에","correct":true},{"t":"힘이 센 사람은 법을 덜 지켜도 되기 때문에","mis":"SO5-1-u3-X09"}],"mis":"SO5-1-u3-X09","explanation":["기준은 같아야 해요.","누구에게나요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#11','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C7',2,'mc','auto','어린이 보호 구역을 정해 둔 법이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":11,"concept":"SO5-1-u3-C7","difficulty":2,"kind":"mc","stem":"어린이 보호 구역을 정해 둔 법이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"사고를 예방해 사회 질서를 유지한다","correct":true},{"t":"개인 정보를 보호한다","mis":"SO5-1-u3-X08"},{"t":"창작물을 보호한다","mis":"SO5-1-u3-X08"},{"t":"재판으로 다툼을 해결한다","mis":"SO5-1-u3-X08"}],"explanation":["차가 천천히 달려요.","사고를 막아요.","사회 질서 유지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#12','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C10',2,'ox','auto','보는 사람이 없으면 빨간불에 횡단보도를 건너도 괜찮아요.',ARRAY['SO5-1-u3-X13']::text[],false,'{"seq":12,"concept":"SO5-1-u3-C10","difficulty":2,"kind":"ox","stem":"보는 사람이 없으면 빨간불에 횡단보도를 건너도 괜찮아요.","answer":"X","reason_options":[{"t":"신호는 벌 때문이 아니라 나와 남의 안전을 위해 지키는 것이기 때문에","correct":true},{"t":"벌만 받지 않으면 되기 때문에","mis":"SO5-1-u3-X13"}],"mis":"SO5-1-u3-X13","explanation":["안전은 언제나 중요해요.","보는 사람이 없어도요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#13','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C11',2,'ox','auto','인권 존중 점검표에서는 「예」를 몇 개 받았는지가 가장 중요해요.',ARRAY['SO5-1-u3-X15']::text[],false,'{"seq":13,"concept":"SO5-1-u3-C11","difficulty":2,"kind":"ox","stem":"인권 존중 점검표에서는 「예」를 몇 개 받았는지가 가장 중요해요.","answer":"X","reason_options":[{"t":"잘 못 지킨 부분을 함께 이야기하고 방법을 찾는 것이 중요하기 때문에","correct":true},{"t":"「예」가 많으면 상을 받기 때문에","mis":"SO5-1-u3-X15"}],"mis":"SO5-1-u3-X15","explanation":["개수가 아니에요.","함께 이야기해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#14','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C12',2,'mc','auto','하윤이네 반 인권 탐사 일지 ⑤에서 공사장 소음은 어떤 까닭의 인권 침해인가요?',ARRAY['SO5-1-u3-X18']::text[],false,'{"seq":14,"concept":"SO5-1-u3-C12","difficulty":2,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑤에서 공사장 소음은 어떤 까닭의 인권 침해인가요?","options":[{"t":"안전 문제","correct":true},{"t":"사생활 침해","mis":"SO5-1-u3-X18"},{"t":"국적 차별","mis":"SO5-1-u3-X18"},{"t":"시설 부족","mis":"SO5-1-u3-X18"}],"explanation":["밤늦게까지 시끄러워요.","잠과 건강을 해쳐요.","안전 문제예요."],"asset":{"type":"passage","lines":["⑤ 동네 탐사 — 빵집 입구가 계단뿐이라 휠체어가 못 들어갔다.","공사장 소음이 밤늦게까지 이어져 이웃이 잠을 못 잔다.","이웃 아저씨는 다른 나라에서 왔다고 월급을 적게 받는다.","놀이터에서는 아이들이 차례를 지키며 서로 양보했다."],"title":"하윤이네 반 인권 탐사 일지 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#15','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C13',2,'mc','auto','하윤이네 반 인권 탐사 일지 ⑥에서 정리한 원인과 이어지는 것은 어느 것인가요?',ARRAY['SO5-1-u3-X19']::text[],false,'{"seq":15,"concept":"SO5-1-u3-C13","difficulty":2,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑥에서 정리한 원인과 이어지는 것은 어느 것인가요?","options":[{"t":"다른 말투를 이상하게 여기는 편견","correct":true},{"t":"전학 온 친구의 말투","mis":"SO5-1-u3-X19"},{"t":"반 친구 수","mis":"SO5-1-u3-X19"},{"t":"토의 시간","mis":"SO5-1-u3-X19"}],"explanation":["말투가 문제가 아니에요.","이상하다는 생각이에요.","편견이 원인이에요."],"asset":{"type":"passage","lines":["⑥ 학급 토의 — 문제: 전학 온 친구의 말투를 흉내 내며 놀린다.","원인: 「다른 말투는 이상하다」는 생각.","방법 ㉮ 여러 지역 말 알아보기 시간 — 별 5개","방법 ㉯ 놀린 친구를 일주일 동안 혼자 앉게 하기 — 별 1개","방법 ㉰ 서로의 고향 이야기 나누기 — 별 3개"],"title":"하윤이네 반 인권 탐사 일지 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#16','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C16',2,'mc','auto','하윤이네 반 인권 탐사 일지 ⑧의 제안에서 「무엇을 위해」에 해당하는 것은 어느 것인가요?',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":16,"concept":"SO5-1-u3-C16","difficulty":2,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑧의 제안에서 「무엇을 위해」에 해당하는 것은 어느 것인가요?","options":[{"t":"휠체어를 탄 친구도 무대에서 발표할 수 있도록","correct":true},{"t":"강당 무대에","mis":"SO5-1-u3-X25"},{"t":"경사로와 안전 손잡이를","mis":"SO5-1-u3-X25"},{"t":"그림으로 그려 게시했다","mis":"SO5-1-u3-X25"}],"explanation":["어디에는 강당 무대예요.","무엇을은 경사로예요.","무엇을 위해는 발표할 수 있도록이에요."],"asset":{"type":"passage","lines":["⑧ 별빛초 제안 — 강당 무대는 계단뿐이라 휠체어로 오를 수 없다.","우리 모둠 제안: 강당 무대에 경사로와 안전 손잡이를","휠체어를 탄 친구도 무대에서 발표할 수 있도록.","실현된 모습을 그림으로 그려 학급에 게시했다."],"title":"하윤이네 반 인권 탐사 일지 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#17','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C6',3,'error','auto','하윤이네 반 인권 탐사 일지 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X07','SO5-1-u3-X08']::text[],false,'{"seq":17,"concept":"SO5-1-u3-C6","difficulty":3,"kind":"error","stem":"하윤이네 반 인권 탐사 일지 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「언니는 법이 없어도 사진을 올린 사람이 알아서 배상했을 거야.」","correct":true,"mis_target":"SO5-1-u3-X07"},{"t":"라임 — 「법원 판결이 언니 권리를 지켜 줬어.」","mis":"SO5-1-u3-X08"},{"t":"기윤 — 「과태료 법은 소방차 길을 지켜 줘.」","mis":"SO5-1-u3-X08"}],"explanation":["법이 기준이 됐어요.","판결로 배상했어요.","은솔이가 잘못 말했어요."],"asset":{"type":"passage","lines":["③ 사촌 언니 이야기 — 누군가 언니 사진을 허락 없이 올렸다.","언니는 손해 배상을 청구했고 법원이 배상하게 판결했다.","그날 저녁 뉴스에서는 소방차 전용 구역 이야기가 나왔다.","그 구역에 차를 세우면 과태료를 낸다고 했다."],"title":"하윤이네 반 인권 탐사 일지 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#18','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C9',3,'error','auto','하윤이네 반 인권 탐사 일지 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X12']::text[],false,'{"seq":18,"concept":"SO5-1-u3-C9","difficulty":3,"kind":"error","stem":"하윤이네 반 인권 탐사 일지 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"선우 — 「헌법은 책에만 있고 우리 가족 생활과는 관계없어.」","correct":true,"mis_target":"SO5-1-u3-X12"},{"t":"예나 — 「할머니의 투표는 헌법이 보장하는 정치 참여야.」","mis":"SO5-1-u3-X12"},{"t":"도율 — 「삼촌의 이사는 자유롭게 행동할 수 있는 모습이야.」","mis":"SO5-1-u3-X12"}],"explanation":["가족 생활 곳곳에 있어요.","투표·이사가 그 예예요.","선우가 잘못 말했어요."],"asset":{"type":"passage","lines":["④ 주말 — 할머니는 선거 날 투표하러 가셨다.","삼촌은 일터 가까운 동네로 이사를 했다.","나는 반 친구들과 인권 소책자를 만들었다.","헌법에 담긴 인권이 우리 가족 생활 곳곳에 있었다."],"title":"하윤이네 반 인권 탐사 일지 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#19','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C12',3,'mc','auto','하윤이네 반 인권 탐사 일지 ⑥의 문제가 인권 침해인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X19','SO5-1-u3-X16','SO5-1-u3-X17']::text[],false,'{"seq":19,"concept":"SO5-1-u3-C12","difficulty":3,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑥의 문제가 인권 침해인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사는 지역이 다르다는 까닭으로 친구를 존중하지 않고 놀리기 때문에","correct":true},{"t":"말투는 바꾸면 그만이기 때문에","mis":"SO5-1-u3-X19"},{"t":"흉내는 재미있는 놀이이기 때문에","mis":"SO5-1-u3-X16"},{"t":"전학 온 친구만 불편하기 때문에","mis":"SO5-1-u3-X17"}],"explanation":["다름을 놀렸어요.","존중받지 못했어요.","인권 침해예요."],"asset":{"type":"passage","lines":["⑥ 학급 토의 — 문제: 전학 온 친구의 말투를 흉내 내며 놀린다.","원인: 「다른 말투는 이상하다」는 생각.","방법 ㉮ 여러 지역 말 알아보기 시간 — 별 5개","방법 ㉯ 놀린 친구를 일주일 동안 혼자 앉게 하기 — 별 1개","방법 ㉰ 서로의 고향 이야기 나누기 — 별 3개"],"title":"하윤이네 반 인권 탐사 일지 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#20','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C14',3,'error','auto','하윤이네 반 인권 탐사 일지 ⑦을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X22','SO5-1-u3-X21']::text[],false,'{"seq":20,"concept":"SO5-1-u3-C14","difficulty":3,"kind":"error","stem":"하윤이네 반 인권 탐사 일지 ⑦을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「나라의 제도는 어려운 사람이 스스로 이겨 내라고 맡겨 두는 거야.」","correct":true,"mis_target":"SO5-1-u3-X22"},{"t":"리안 — 「사회 보장 제도는 어려운 사람의 생활을 도와.」","mis":"SO5-1-u3-X22"},{"t":"보아 — 「옐로 카펫은 어린이를 지켜.」","mis":"SO5-1-u3-X21"}],"explanation":["국가가 도와요.","맡겨 두지 않아요.","서준이가 잘못 말했어요."],"asset":{"type":"passage","lines":["⑦ 배려 찾기 — 도서관에서 큰 글자 도서를, 횡단보도에서 옐로 카펫을 봤다.","학교에서는 계단 점자 블록과 경사로를 찾았다.","복지관에서 사회 복지사 선생님을 만나 하는 일을 들었다.","어려운 사람의 생활을 돕는 나라의 제도도 알게 되었다."],"title":"하윤이네 반 인권 탐사 일지 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#21','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C15',3,'error','auto','인권 보호 실천을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":21,"concept":"SO5-1-u3-C15","difficulty":3,"kind":"error","stem":"인권 보호 실천을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지환 — 「사진전은 다 만들면 우리끼리만 보고 치우면 돼.」","correct":true,"mis_target":"SO5-1-u3-X23"},{"t":"나윤 — 「다 만들면 게시하고 누리집에 올리자.」","mis":"SO5-1-u3-X23"},{"t":"찬희 — 「찍을 장면부터 정해야 해.」","mis":"SO5-1-u3-X23"}],"explanation":["많은 사람이 봐야 해요.","알리는 것이 마지막이에요.","지환이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#22','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C16',3,'error','auto','하윤이네 반 인권 탐사 일지 ⑧을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X24','SO5-1-u3-X25']::text[],false,'{"seq":22,"concept":"SO5-1-u3-C16","difficulty":3,"kind":"error","stem":"하윤이네 반 인권 탐사 일지 ⑧을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은재 — 「나는 무대에 잘 오르니까 경사로는 필요 없는 제안이야.」","correct":true,"mis_target":"SO5-1-u3-X24"},{"t":"하솔 — 「휠체어를 탄 친구에게는 꼭 필요해.」","mis":"SO5-1-u3-X24"},{"t":"예준 — 「어디에·무엇을·무엇을 위해가 다 들어 있어.」","mis":"SO5-1-u3-X25"}],"explanation":["나에게 편해도 누군가는 불편해요.","모두를 위한 제안이에요.","은재가 잘못 말했어요."],"asset":{"type":"passage","lines":["⑧ 별빛초 제안 — 강당 무대는 계단뿐이라 휠체어로 오를 수 없다.","우리 모둠 제안: 강당 무대에 경사로와 안전 손잡이를","휠체어를 탄 친구도 무대에서 발표할 수 있도록.","실현된 모습을 그림으로 그려 학급에 게시했다."],"title":"하윤이네 반 인권 탐사 일지 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#23','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C12',4,'mc','auto','하윤이네 반 인권 탐사 일지 ⑤~⑧을 차례로 이어 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO5-1-u3-X17','SO5-1-u3-X22','SO5-1-u3-X23']::text[],false,'{"seq":23,"concept":"SO5-1-u3-C12","difficulty":4,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ⑤~⑧을 차례로 이어 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"주변의 인권 침해를 알아차리고 원인을 찾아 해결하며, 사회의 노력을 살펴 우리도 제안하고 실천해야 한다","correct":true},{"t":"침해는 남의 일이니 알아차릴 필요가 없다","mis":"SO5-1-u3-X17"},{"t":"국가가 다 하니 우리는 할 일이 없다","mis":"SO5-1-u3-X22"},{"t":"제안은 어른만 할 수 있다","mis":"SO5-1-u3-X23"}],"explanation":["⑤는 알아차리기예요.","⑥은 해결, ⑦은 사회의 노력이에요.","⑧은 우리의 제안과 실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#24','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C6',4,'essay','teacher','하윤이네 반 인권 탐사 일지 ③의 두 이야기에서 법이 한 일을 각각 쓰고, 법의 두 역할과 이어 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u3-C6","difficulty":4,"kind":"essay","stem":"하윤이네 반 인권 탐사 일지 ③의 두 이야기에서 법이 한 일을 각각 쓰고, 법의 두 역할과 이어 설명하세요.","answer_guide":{"answer":"예: 사촌 언니 이야기에서 법은 허락 없이 사진을 올린 사람이 배상하게 하여 언니의 초상권을 지켰다. 이것은 개인의 권리를 보호하는 역할이다. 뉴스의 법은 소방차 전용 구역에 차를 세우면 과태료를 내게 해 불이 났을 때 모두의 안전을 지킨다. 이것은 사회 질서를 유지하는 역할이다.","scoring_points":["언니 이야기의 법이 한 일을 썼는가","뉴스의 법이 한 일을 썼는가","두 역할과 바르게 이었는가"]},"explanation":["언니 한 사람을 지켰어요.","모두의 안전을 지켜요.","역할과 이어요."],"asset":{"type":"passage","lines":["③ 사촌 언니 이야기 — 누군가 언니 사진을 허락 없이 올렸다.","언니는 손해 배상을 청구했고 법원이 배상하게 판결했다.","그날 저녁 뉴스에서는 소방차 전용 구역 이야기가 나왔다.","그 구역에 차를 세우면 과태료를 낸다고 했다."],"title":"하윤이네 반 인권 탐사 일지 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_b#25','soc',5,1,'u3','','g5_1_soc_u3_review_b','unit_review','SO5-1-u3-C13',4,'essay','teacher','하윤이네 반 인권 탐사 일지 ⑥의 토의에서 원인과 모둠 의견을 쓰고, ㉯가 좋은 방법이 아닌 까닭과 내가 더할 해결 방법 한 가지를 근거와 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u3-C13","difficulty":4,"kind":"essay","stem":"하윤이네 반 인권 탐사 일지 ⑥의 토의에서 원인과 모둠 의견을 쓰고, ㉯가 좋은 방법이 아닌 까닭과 내가 더할 해결 방법 한 가지를 근거와 함께 쓰세요.","answer_guide":{"answer":"예: 원인은 다른 말투를 이상하게 보는 편견이고, 별을 가장 많이 받은 ㉮ 여러 지역 말 알아보기 시간이 모둠 의견이다. ㉯는 놀린 친구에게 또 다른 상처를 주고 편견은 줄이지 못해 좋은 방법이 아니다. 나는 반 친구들이 고향 말로 인사 한마디씩 해 보는 날을 제안한다. 서로의 말을 직접 들어 보면 다르다는 것이 재미있고 소중하다고 느껴 편견이 줄어들기 때문이다.","scoring_points":["원인과 모둠 의견을 썼는가","㉯가 좋지 않은 까닭을 썼는가","내 방법을 근거와 함께 썼는가"]},"explanation":["원인과 의견을 써요.","또 다른 상처예요.","근거를 함께 써요."],"asset":{"type":"passage","lines":["⑥ 학급 토의 — 문제: 전학 온 친구의 말투를 흉내 내며 놀린다.","원인: 「다른 말투는 이상하다」는 생각.","방법 ㉮ 여러 지역 말 알아보기 시간 — 별 5개","방법 ㉯ 놀린 친구를 일주일 동안 혼자 앉게 하기 — 별 1개","방법 ㉰ 서로의 고향 이야기 나누기 — 별 3개"],"title":"하윤이네 반 인권 탐사 일지 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#1','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C1',1,'ox','auto','법은 사회 구성원이 지키고 싶을 때만 지키면 되는 규범이에요.',ARRAY['SO5-1-u3-X01']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C1","difficulty":1,"kind":"ox","stem":"법은 사회 구성원이 지키고 싶을 때만 지키면 되는 규범이에요.","answer":"X","reason_options":[{"t":"법은 반드시 지켜야 하는 강제성이 있기 때문에","correct":true},{"t":"법은 양심에 따라 고르는 것이기 때문에","mis":"SO5-1-u3-X01"}],"mis":"SO5-1-u3-X01","explanation":["법은 반드시 지켜요.","강제성이 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#2','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C2',1,'mc','auto','일상의 약속이나 규칙을 지키는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X01','SO5-1-u3-X13']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C2","difficulty":1,"kind":"mc","stem":"일상의 약속이나 규칙을 지키는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"양심에 따라 자율적으로 지킨다","correct":true},{"t":"국가가 처벌하니까 지킨다","mis":"SO5-1-u3-X01"},{"t":"어른이 볼 때만 지킨다","mis":"SO5-1-u3-X13"},{"t":"지키지 않아도 된다","mis":"SO5-1-u3-X01"}],"explanation":["약속은 스스로 지켜요.","양심에 따라요.","자율적으로 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#3','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C4',1,'ox','auto','우리 사회의 많은 일은 법에 따라 이루어지고 있어요.',ARRAY['SO5-1-u3-X04']::text[],false,'{"seq":3,"concept":"SO5-1-u3-C4","difficulty":1,"kind":"ox","stem":"우리 사회의 많은 일은 법에 따라 이루어지고 있어요.","answer":"O","reason_options":[{"t":"등굣길·급식·병원처럼 생활 곳곳에 법이 적용되기 때문에","correct":true},{"t":"법은 법원 안에서만 쓰이기 때문에","mis":"SO5-1-u3-X04"}],"mis":"SO5-1-u3-X04","explanation":["생활 곳곳에 법이 있어요.","많은 일이 법에 따라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#4','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C7',1,'ox','auto','교통질서를 유지하는 것은 법의 역할 가운데 하나예요.',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C7","difficulty":1,"kind":"ox","stem":"교통질서를 유지하는 것은 법의 역할 가운데 하나예요.","answer":"O","reason_options":[{"t":"사고를 막아 모두가 안전하게 다니게 하기 때문에","correct":true},{"t":"교통은 법과 관계없는 일이기 때문에","mis":"SO5-1-u3-X08"}],"mis":"SO5-1-u3-X08","explanation":["도로 위 질서예요.","사고를 막아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#5','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C8',1,'sa','auto','사람이라면 누구나 누려야 할 기본적인 권리를 두 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u3-C8","difficulty":1,"kind":"sa","stem":"사람이라면 누구나 누려야 할 기본적인 권리를 두 글자로 무엇이라고 하나요?","answer":["인권"],"explanation":["사람의 권리예요.","누구나 누려요.","인권이에요."],"mis":"SO5-1-u3-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#6','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C9',1,'ox','auto','헌법은 우리나라의 최고법이에요.',ARRAY['SO5-1-u3-X11']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C9","difficulty":1,"kind":"ox","stem":"헌법은 우리나라의 최고법이에요.","answer":"O","reason_options":[{"t":"나라 운영 원칙과 국민의 권리를 담아 다른 법의 바탕이 되기 때문에","correct":true},{"t":"가장 최근에 만든 법이기 때문에","mis":"SO5-1-u3-X11"}],"mis":"SO5-1-u3-X11","explanation":["가장 높은 법이에요.","다른 법의 바탕이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#7','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C12',1,'ox','auto','인권 침해는 우리 동네에서는 일어나지 않아요.',ARRAY['SO5-1-u3-X17']::text[],false,'{"seq":7,"concept":"SO5-1-u3-C12","difficulty":1,"kind":"ox","stem":"인권 침해는 우리 동네에서는 일어나지 않아요.","answer":"X","reason_options":[{"t":"일상생활 곳곳에서 인권 침해가 일어나기 때문에","correct":true},{"t":"인권 침해는 먼 나라에서만 일어나기 때문에","mis":"SO5-1-u3-X17"}],"mis":"SO5-1-u3-X17","explanation":["하윤이 동네에도 있었어요.","생활 곳곳이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["⑤ 동네 탐사 — 빵집 입구가 계단뿐이라 휠체어가 못 들어갔다.","공사장 소음이 밤늦게까지 이어져 이웃이 잠을 못 잔다.","이웃 아저씨는 다른 나라에서 왔다고 월급을 적게 받는다.","놀이터에서는 아이들이 차례를 지키며 서로 양보했다."],"title":"하윤이네 반 인권 탐사 일지 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#8','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C14',1,'ox','auto','학교에 경사로와 계단 점자 블록을 두는 것은 인권 보호 노력이에요.',ARRAY['SO5-1-u3-X21']::text[],false,'{"seq":8,"concept":"SO5-1-u3-C14","difficulty":1,"kind":"ox","stem":"학교에 경사로와 계단 점자 블록을 두는 것은 인권 보호 노력이에요.","answer":"O","reason_options":[{"t":"휠체어를 탄 사람과 시각 장애가 있는 사람도 안전하게 다니게 하기 때문에","correct":true},{"t":"보기 좋게 꾸미려는 것이기 때문에","mis":"SO5-1-u3-X21"}],"mis":"SO5-1-u3-X21","explanation":["누구나 다니게 해요.","인권 보호 시설이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["⑦ 배려 찾기 — 도서관에서 큰 글자 도서를, 횡단보도에서 옐로 카펫을 봤다.","학교에서는 계단 점자 블록과 경사로를 찾았다.","복지관에서 사회 복지사 선생님을 만나 하는 일을 들었다.","어려운 사람의 생활을 돕는 나라의 제도도 알게 되었다."],"title":"하윤이네 반 인권 탐사 일지 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#9','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C2',2,'ox','auto','약속이나 규칙을 지키지 않는 사람이 많아지면 다툼과 피해가 생겨서 법을 만들기도 해요.',ARRAY['SO5-1-u3-X01']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C2","difficulty":2,"kind":"ox","stem":"약속이나 규칙을 지키지 않는 사람이 많아지면 다툼과 피해가 생겨서 법을 만들기도 해요.","answer":"O","reason_options":[{"t":"어기면 벌을 주는 기준이 있어야 모두가 지키기 때문에","correct":true},{"t":"법은 약속과 아무 관계 없이 생기기 때문에","mis":"SO5-1-u3-X01"}],"mis":"SO5-1-u3-X01","explanation":["다툼과 피해가 생겨요.","기준이 필요해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#10','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C5',2,'error','auto','법이 필요한 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X07']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C5","difficulty":2,"kind":"error","stem":"법이 필요한 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「법은 많을수록 좋으니까 무조건 많이 만들어야 해.」","correct":true,"mis_target":"SO5-1-u3-X07"},{"t":"지율 — 「법은 갈등을 해결하는 기준이 돼.」","mis":"SO5-1-u3-X07"},{"t":"수호 — 「법이 없다면 어떻게 될지 생각해 보면 법이 하는 일이 보여.」","mis":"SO5-1-u3-X07"}],"explanation":["수가 많다고 좋은 게 아니에요.","기준이 되는 것이 중요해요.","하람이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#11','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C6',2,'ox','auto','하윤이네 반 인권 탐사 일지 ③에서 법은 개인의 권리만 지키고 사회 질서와는 관계가 없어요.',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":11,"concept":"SO5-1-u3-C6","difficulty":2,"kind":"ox","stem":"하윤이네 반 인권 탐사 일지 ③에서 법은 개인의 권리만 지키고 사회 질서와는 관계가 없어요.","answer":"X","reason_options":[{"t":"뉴스의 소방차 전용 구역 이야기처럼 사회 질서도 함께 지키기 때문에","correct":true},{"t":"법은 한 가지 역할만 하기 때문에","mis":"SO5-1-u3-X08"}],"mis":"SO5-1-u3-X08","explanation":["언니 일은 권리 보호예요.","뉴스는 질서 유지예요.","그래서 X예요."],"asset":{"type":"passage","lines":["③ 사촌 언니 이야기 — 누군가 언니 사진을 허락 없이 올렸다.","언니는 손해 배상을 청구했고 법원이 배상하게 판결했다.","그날 저녁 뉴스에서는 소방차 전용 구역 이야기가 나왔다.","그 구역에 차를 세우면 과태료를 낸다고 했다."],"title":"하윤이네 반 인권 탐사 일지 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#12','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C10',2,'error','auto','하윤이네 반에서 법을 지키는 까닭을 두고 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X13']::text[],false,'{"seq":12,"concept":"SO5-1-u3-C10","difficulty":2,"kind":"error","stem":"하윤이네 반에서 법을 지키는 까닭을 두고 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도진 — 「법은 상을 받으려고 지키는 거야.」","correct":true,"mis_target":"SO5-1-u3-X13"},{"t":"혜온 — 「나와 다른 사람의 권리를 보호하려고 지켜.」","mis":"SO5-1-u3-X13"},{"t":"주안 — 「모두가 안정된 삶을 누리려고 지켜.」","mis":"SO5-1-u3-X13"}],"explanation":["상 때문이 아니에요.","모두를 위해서예요.","도진이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#13','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C11',2,'error','auto','인권 존중을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X14']::text[],false,'{"seq":13,"concept":"SO5-1-u3-C11","difficulty":2,"kind":"error","stem":"인권 존중을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"루아 — 「내 권리가 가장 중요하니까 친구 권리는 나중에 생각해.」","correct":true,"mis_target":"SO5-1-u3-X14"},{"t":"이현 — 「친구가 싫어하는 별명은 부르지 않을래.」","mis":"SO5-1-u3-X14"},{"t":"다솜 — 「생각이 달라도 끝까지 들어 줄래.」","mis":"SO5-1-u3-X14"}],"explanation":["나만큼 친구도 소중해요.","함께 존중해요.","루아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#14','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C12',2,'error','auto','하윤이네 반 인권 탐사 일지 ⑤를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X19','SO5-1-u3-X18']::text[],false,'{"seq":14,"concept":"SO5-1-u3-C12","difficulty":2,"kind":"error","stem":"하윤이네 반 인권 탐사 일지 ⑤를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예서 — 「빵집 입구 일은 휠체어를 탄 사람이 다른 가게에 가면 그만이야.」","correct":true,"mis_target":"SO5-1-u3-X19"},{"t":"하진 — 「경사로가 없어서 생긴 시설 부족이야.」","mis":"SO5-1-u3-X18"},{"t":"민아 — 「월급 차별은 국적에 따른 차별이야.」","mis":"SO5-1-u3-X18"}],"explanation":["누구나 들어갈 권리가 있어요.","시설이 부족한 거예요.","예서가 잘못 말했어요."],"asset":{"type":"passage","lines":["⑤ 동네 탐사 — 빵집 입구가 계단뿐이라 휠체어가 못 들어갔다.","공사장 소음이 밤늦게까지 이어져 이웃이 잠을 못 잔다.","이웃 아저씨는 다른 나라에서 왔다고 월급을 적게 받는다.","놀이터에서는 아이들이 차례를 지키며 서로 양보했다."],"title":"하윤이네 반 인권 탐사 일지 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#15','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C13',2,'ox','auto','별표 토의에서는 내가 낸 해결 방법에도 별표를 줄 수 있어요.',ARRAY['SO5-1-u3-X20']::text[],false,'{"seq":15,"concept":"SO5-1-u3-C13","difficulty":2,"kind":"ox","stem":"별표 토의에서는 내가 낸 해결 방법에도 별표를 줄 수 있어요.","answer":"X","reason_options":[{"t":"내가 낸 방법은 빼고 다른 방법 가운데서 골라야 공정하기 때문에","correct":true},{"t":"내 방법이 가장 좋기 때문에","mis":"SO5-1-u3-X20"}],"mis":"SO5-1-u3-X20","explanation":["내 것은 빼요.","공정하게 골라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#16','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C16',2,'ox','auto','장애물 없는 생활 환경 인증 제도는 어린이·노인·임산부를 포함한 모든 사람을 위한 제도예요.',ARRAY['SO5-1-u3-X24']::text[],false,'{"seq":16,"concept":"SO5-1-u3-C16","difficulty":2,"kind":"ox","stem":"장애물 없는 생활 환경 인증 제도는 어린이·노인·임산부를 포함한 모든 사람을 위한 제도예요.","answer":"O","reason_options":[{"t":"누구나 건물과 시설을 불편 없이 쓰게 하려는 제도이기 때문에","correct":true},{"t":"장애가 있는 사람만 위한 제도이기 때문에","mis":"SO5-1-u3-X24"}],"mis":"SO5-1-u3-X24","explanation":["모든 사람이에요.","불편 없이요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#17','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C7',3,'ox','auto','소방차 전용 구역 과태료 법은 차 주인 한 사람의 편의를 지키려고 만든 법이에요.',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":17,"concept":"SO5-1-u3-C7","difficulty":3,"kind":"ox","stem":"소방차 전용 구역 과태료 법은 차 주인 한 사람의 편의를 지키려고 만든 법이에요.","answer":"X","reason_options":[{"t":"불이 났을 때 모두의 안전을 지키는 사회 질서를 위한 법이기 때문에","correct":true},{"t":"차 주인이 편하게 주차하도록 돕는 법이기 때문에","mis":"SO5-1-u3-X08"}],"mis":"SO5-1-u3-X08","explanation":["소방차가 빨리 가야 해요.","모두의 안전이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["③ 사촌 언니 이야기 — 누군가 언니 사진을 허락 없이 올렸다.","언니는 손해 배상을 청구했고 법원이 배상하게 판결했다.","그날 저녁 뉴스에서는 소방차 전용 구역 이야기가 나왔다.","그 구역에 차를 세우면 과태료를 낸다고 했다."],"title":"하윤이네 반 인권 탐사 일지 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#18','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C9',3,'ox','auto','국가는 힘이 세기 때문에 필요하면 국민의 인권을 마음대로 줄일 수 있어요.',ARRAY['SO5-1-u3-X11']::text[],false,'{"seq":18,"concept":"SO5-1-u3-C9","difficulty":3,"kind":"ox","stem":"국가는 힘이 세기 때문에 필요하면 국민의 인권을 마음대로 줄일 수 있어요.","answer":"X","reason_options":[{"t":"헌법이 국가 권력도 인권을 함부로 침해하지 못하게 막기 때문에","correct":true},{"t":"국가는 헌법을 지키지 않아도 되기 때문에","mis":"SO5-1-u3-X11"}],"mis":"SO5-1-u3-X11","explanation":["헌법이 막아요.","국가도 함부로 못 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#19','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C13',3,'error','auto','하윤이네 반 인권 탐사 일지 ⑥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X19']::text[],false,'{"seq":19,"concept":"SO5-1-u3-C13","difficulty":3,"kind":"error","stem":"하윤이네 반 인권 탐사 일지 ⑥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「전학 온 친구가 말투를 고치면 다 해결되는 일이야.」","correct":true,"mis_target":"SO5-1-u3-X19"},{"t":"소이 — 「다른 말투를 이상하게 보는 편견이 원인이야.」","mis":"SO5-1-u3-X19"},{"t":"재하 — 「㉮는 편견을 줄이는 방법이야.」","mis":"SO5-1-u3-X19"}],"explanation":["친구 탓이 아니에요.","편견이 원인이에요.","하준이가 잘못 말했어요."],"asset":{"type":"passage","lines":["⑥ 학급 토의 — 문제: 전학 온 친구의 말투를 흉내 내며 놀린다.","원인: 「다른 말투는 이상하다」는 생각.","방법 ㉮ 여러 지역 말 알아보기 시간 — 별 5개","방법 ㉯ 놀린 친구를 일주일 동안 혼자 앉게 하기 — 별 1개","방법 ㉰ 서로의 고향 이야기 나누기 — 별 3개"],"title":"하윤이네 반 인권 탐사 일지 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#20','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C14',3,'ox','auto','학교 규칙은 선생님과 학생, 학부모가 함께 만들어요.',ARRAY['SO5-1-u3-X22']::text[],false,'{"seq":20,"concept":"SO5-1-u3-C14","difficulty":3,"kind":"ox","stem":"학교 규칙은 선생님과 학생, 학부모가 함께 만들어요.","answer":"O","reason_options":[{"t":"모두가 안전하고 평등하게 생활하도록 함께 정하기 때문에","correct":true},{"t":"선생님이 혼자 정하기 때문에","mis":"SO5-1-u3-X22"}],"mis":"SO5-1-u3-X22","explanation":["함께 만들어요.","학급 회의도 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#21','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C15',3,'ox','auto','인권을 존중하는 말을 쓰는 것도 생활 속 인권 보호 실천이에요.',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":21,"concept":"SO5-1-u3-C15","difficulty":3,"kind":"ox","stem":"인권을 존중하는 말을 쓰는 것도 생활 속 인권 보호 실천이에요.","answer":"O","reason_options":[{"t":"작은 일부터 실천하는 것이 인권을 존중하는 사회를 만들기 때문에","correct":true},{"t":"말은 인권과 관계없기 때문에","mis":"SO5-1-u3-X23"}],"mis":"SO5-1-u3-X23","explanation":["말 한마디도 실천이에요.","작은 일부터요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#22','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C16',3,'ox','auto','제안서는 한 번 고른 칸을 낼 때까지 절대 고칠 수 없어요.',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":22,"concept":"SO5-1-u3-C16","difficulty":3,"kind":"ox","stem":"제안서는 한 번 고른 칸을 낼 때까지 절대 고칠 수 없어요.","answer":"X","reason_options":[{"t":"더 알맞은 것이 떠오르면 내기 전까지 얼마든지 고쳐 쓸 수 있기 때문에","correct":true},{"t":"처음 고른 것이 늘 정답이기 때문에","mis":"SO5-1-u3-X25"}],"mis":"SO5-1-u3-X25","explanation":["제안은 다듬어요.","내기 전엔 고쳐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#23','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C10',4,'mc','auto','하윤이네 반 인권 탐사 일지 ①~③을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X04','SO5-1-u3-X13','SO5-1-u3-X09']::text[],false,'{"seq":23,"concept":"SO5-1-u3-C10","difficulty":4,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ①~③을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"법은 생활 곳곳에서 우리를 지켜 주므로 법이 필요한 까닭을 알고 스스로 지키는 태도가 중요하다","correct":true},{"t":"법은 학교 밖에서만 쓰인다","mis":"SO5-1-u3-X04"},{"t":"법은 벌을 피하려고만 지킨다","mis":"SO5-1-u3-X13"},{"t":"법은 사람마다 다르게 쓰인다","mis":"SO5-1-u3-X09"}],"explanation":["등굣길·급식·사진·소방차예요.","곳곳에서 지켜 줘요.","스스로 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#24','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C9',4,'essay','teacher','하윤이네 반 인권 탐사 일지 ④에서 헌법이 보장하는 인권의 모습 두 가지를 찾아 쓰고, 헌법에 인권을 정해 둔 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u3-C9","difficulty":4,"kind":"essay","stem":"하윤이네 반 인권 탐사 일지 ④에서 헌법이 보장하는 인권의 모습 두 가지를 찾아 쓰고, 헌법에 인권을 정해 둔 까닭을 쓰세요.","answer_guide":{"answer":"예: 할머니가 선거 날 투표하신 것은 국가의 정치에 참여하는 모습이고, 삼촌이 일터 가까운 동네로 이사한 것은 국가의 간섭 없이 자유롭게 행동하는 모습이다. 헌법에 인권을 정해 둔 것은 국가 권력이 개인의 기본적인 인권을 함부로 침해하지 못하게 하려는 것이다.","scoring_points":["인권의 모습 두 가지를 썼는가","생활 장면과 바르게 이었는가","헌법에 정한 까닭을 썼는가"]},"explanation":["투표와 이사예요.","보장 모습과 이어요.","국가 권력을 막아요."],"asset":{"type":"passage","lines":["④ 주말 — 할머니는 선거 날 투표하러 가셨다.","삼촌은 일터 가까운 동네로 이사를 했다.","나는 반 친구들과 인권 소책자를 만들었다.","헌법에 담긴 인권이 우리 가족 생활 곳곳에 있었다."],"title":"하윤이네 반 인권 탐사 일지 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_c#25','soc',5,1,'u3','','g5_1_soc_u3_review_c','unit_review','SO5-1-u3-C14',4,'essay','teacher','하윤이네 반 인권 탐사 일지 ⑦에서 찾은 인권 보호 노력을 주변·학교·국가로 나누어 하나씩 쓰고, 이 노력들이 모두를 위한 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u3-C14","difficulty":4,"kind":"essay","stem":"하윤이네 반 인권 탐사 일지 ⑦에서 찾은 인권 보호 노력을 주변·학교·국가로 나누어 하나씩 쓰고, 이 노력들이 모두를 위한 까닭을 쓰세요.","answer_guide":{"answer":"예: 주변에는 노인을 위한 큰 글자 도서와 어린이를 지키는 옐로 카펫이 있다. 학교에는 시각 장애가 있는 사람을 위한 계단 점자 블록이 있다. 국가는 어려운 사람의 생활을 돕는 사회 보장 제도를 마련한다. 이 노력들은 보호가 필요한 사람을 배려하면서도 누구나 언젠가 어리거나 늙거나 아플 수 있기에 결국 모든 사람의 인간다운 생활을 지켜 준다.","scoring_points":["주변·학교·국가의 노력을 하나씩 썼는가","노력과 대상을 바르게 이었는가","모두를 위한 까닭을 썼는가"]},"explanation":["세 곳으로 나누어요.","누구를 위한지 써요.","모두를 위한 까닭을 써요."],"asset":{"type":"passage","lines":["⑦ 배려 찾기 — 도서관에서 큰 글자 도서를, 횡단보도에서 옐로 카펫을 봤다.","학교에서는 계단 점자 블록과 경사로를 찾았다.","복지관에서 사회 복지사 선생님을 만나 하는 일을 들었다.","어려운 사람의 생활을 돕는 나라의 제도도 알게 되었다."],"title":"하윤이네 반 인권 탐사 일지 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#1','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C1',1,'mc','auto','법의 두 가지 특징을 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u3-X01','SO5-1-u3-X02','SO5-1-u3-X26']::text[],false,'{"seq":1,"concept":"SO5-1-u3-C1","difficulty":1,"kind":"mc","stem":"법의 두 가지 특징을 바르게 말한 것은 어느 것인가요?","options":[{"t":"모두가 반드시 지켜야 하고, 어기면 국가로부터 제재를 받는다","correct":true},{"t":"지키고 싶을 때만 지키고, 어겨도 아무 일이 없다","mis":"SO5-1-u3-X01"},{"t":"어른만 지키고, 어기면 친구가 꾸중한다","mis":"SO5-1-u3-X02"},{"t":"나라마다 똑같고, 바뀌지 않는다","mis":"SO5-1-u3-X26"}],"explanation":["강제성이 있어요.","국가의 제재가 있어요.","두 특징이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#2','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C2',1,'mc','auto','다음 가운데 법이 필요한 상황은 어느 것인가요?',ARRAY['SO5-1-u3-X03']::text[],false,'{"seq":2,"concept":"SO5-1-u3-C2","difficulty":1,"kind":"mc","stem":"다음 가운데 법이 필요한 상황은 어느 것인가요?","options":[{"t":"가게에서 값을 내지 않고 물건을 가져간다","correct":true},{"t":"형제끼리 말다툼을 한다","mis":"SO5-1-u3-X03"},{"t":"길의 휴지를 줍지 않는다","mis":"SO5-1-u3-X03"},{"t":"웃어른께 인사하지 않는다","mis":"SO5-1-u3-X03"}],"explanation":["주인에게 큰 피해를 줘요.","법이 필요해요.","나머지는 양심의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#3','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C3',1,'sa','auto','안전하게 등교할 수 있도록 도로의 교통을 정한 법은 「○○ 교통법」이에요. ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u3-C3","difficulty":1,"kind":"sa","stem":"안전하게 등교할 수 있도록 도로의 교통을 정한 법은 「○○ 교통법」이에요. ○○에 들어갈 두 글자를 쓰세요.","answer":["도로"],"explanation":["등굣길과 이어져요.","도로의 교통이에요.","「도로 교통법」이에요."],"mis":"SO5-1-u3-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#4','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C6',1,'mc','auto','개인 정보를 보호하는 법의 역할을 보여 주는 모습은 어느 것인가요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":4,"concept":"SO5-1-u3-C6","difficulty":1,"kind":"mc","stem":"개인 정보를 보호하는 법의 역할을 보여 주는 모습은 어느 것인가요?","options":[{"t":"전화번호 대신 개인 안심 번호를 쓰게 한다","correct":true},{"t":"경찰이 골목을 순찰한다","mis":"SO5-1-u3-X08"},{"t":"거리를 청소한다","mis":"SO5-1-u3-X08"},{"t":"교통 단속을 한다","mis":"SO5-1-u3-X08"}],"explanation":["진짜 번호를 감춰요.","개인 정보를 지켜요.","권리 보호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#5','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C8',1,'mc','auto','인권을 누리는 사람으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X10']::text[],false,'{"seq":5,"concept":"SO5-1-u3-C8","difficulty":1,"kind":"mc","stem":"인권을 누리는 사람으로 알맞은 것은 어느 것인가요?","options":[{"t":"성별·나이·국적에 관계없이 모든 사람","correct":true},{"t":"어른만","mis":"SO5-1-u3-X10"},{"t":"우리나라 사람만","mis":"SO5-1-u3-X10"},{"t":"노력한 사람만","mis":"SO5-1-u3-X10"}],"explanation":["차별 없이 주어져요.","누구나 누려요.","모든 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#6','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C9',1,'mc','auto','헌법에 인권을 정해 둔 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X11','SO5-1-u3-X26']::text[],false,'{"seq":6,"concept":"SO5-1-u3-C9","difficulty":1,"kind":"mc","stem":"헌법에 인권을 정해 둔 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"국가 권력이 인권을 함부로 침해하지 못하게 하려고","correct":true},{"t":"법의 수를 늘리려고","mis":"SO5-1-u3-X11"},{"t":"어른만 읽게 하려고","mis":"SO5-1-u3-X11"},{"t":"조항을 외우게 하려고","mis":"SO5-1-u3-X26"}],"explanation":["국가는 힘이 세요.","그 힘을 막아요.","인권을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#7','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C12',1,'sa','auto','성별·나이·국적 등으로 인권을 보호받지 못하는 것을 「인권 ○○」라고 해요. ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO5-1-u3-C12","difficulty":1,"kind":"sa","stem":"성별·나이·국적 등으로 인권을 보호받지 못하는 것을 「인권 ○○」라고 해요. ○○에 들어갈 두 글자를 쓰세요.","answer":["침해"],"explanation":["인권을 보호받지 못해요.","여러 까닭이 있어요.","인권 침해예요."],"mis":"SO5-1-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#8','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C14',1,'sa','auto','하윤이네 반 인권 탐사 일지 ⑦에서 보호가 필요한 사람이 사회에 잘 적응하도록 돕는 직업은 「사회 ○○사」예요. ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO5-1-u3-C14","difficulty":1,"kind":"sa","stem":"하윤이네 반 인권 탐사 일지 ⑦에서 보호가 필요한 사람이 사회에 잘 적응하도록 돕는 직업은 「사회 ○○사」예요. ○○에 들어갈 두 글자를 쓰세요.","answer":["복지"],"explanation":["복지관에서 만났어요.","사람들의 생활을 도와요.","사회 복지사예요."],"asset":{"type":"passage","lines":["⑦ 배려 찾기 — 도서관에서 큰 글자 도서를, 횡단보도에서 옐로 카펫을 봤다.","학교에서는 계단 점자 블록과 경사로를 찾았다.","복지관에서 사회 복지사 선생님을 만나 하는 일을 들었다.","어려운 사람의 생활을 돕는 나라의 제도도 알게 되었다."],"title":"하윤이네 반 인권 탐사 일지 ⑦"},"mis":"SO5-1-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#9','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C1',2,'mc','auto','세계에 책가방 무게를 제한하는 법이 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X26','SO5-1-u3-X07']::text[],false,'{"seq":9,"concept":"SO5-1-u3-C1","difficulty":2,"kind":"mc","stem":"세계에 책가방 무게를 제한하는 법이 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"자라는 어린이의 건강을 해치지 않도록","correct":true},{"t":"책을 덜 읽게 하려고","mis":"SO5-1-u3-X26"},{"t":"가방을 더 팔려고","mis":"SO5-1-u3-X07"},{"t":"어른 가방을 무겁게 하려고","mis":"SO5-1-u3-X07"}],"explanation":["무거운 가방은 몸에 무리를 줘요.","어린이 건강을 생각했어요.","법에 가치가 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#10','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C5',2,'mc','auto','폐수를 함부로 버리지 못하게 하는 법이 필요한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X07']::text[],false,'{"seq":10,"concept":"SO5-1-u3-C5","difficulty":2,"kind":"mc","stem":"폐수를 함부로 버리지 못하게 하는 법이 필요한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하천이 오염되면 생물과 사람이 함께 피해를 입기 때문에","correct":true},{"t":"공장을 더 짓게 하려고","mis":"SO5-1-u3-X07"},{"t":"하천을 깊게 파려고","mis":"SO5-1-u3-X07"},{"t":"물고기를 잡게 하려고","mis":"SO5-1-u3-X07"}],"explanation":["하천이 오염돼요.","생물과 사람이 아파요.","법으로 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#11','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C6',2,'mc','auto','불이 났을 때 소방관이 출동해 생명과 재산을 지키는 것은 법의 어떤 역할인가요?',ARRAY['SO5-1-u3-X08']::text[],false,'{"seq":11,"concept":"SO5-1-u3-C6","difficulty":2,"kind":"mc","stem":"불이 났을 때 소방관이 출동해 생명과 재산을 지키는 것은 법의 어떤 역할인가요?","options":[{"t":"개인의 생명이나 재산을 보호한다","correct":true},{"t":"공정한 경제 질서를 지킨다","mis":"SO5-1-u3-X08"},{"t":"거리를 깨끗하게 한다","mis":"SO5-1-u3-X08"},{"t":"교통질서를 유지한다","mis":"SO5-1-u3-X08"}],"explanation":["집과 가족을 지켜요.","생명과 재산이에요.","권리 보호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#12','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C10',2,'mc','auto','인터넷 게시판에 글을 쓸 때 법을 지키는 태도로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X13']::text[],false,'{"seq":12,"concept":"SO5-1-u3-C10","difficulty":2,"kind":"mc","stem":"인터넷 게시판에 글을 쓸 때 법을 지키는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"다른 사람을 비방하지 않고 바르고 고운 말을 쓴다","correct":true},{"t":"화가 나면 헐뜯는 글을 쓴다","mis":"SO5-1-u3-X13"},{"t":"이름을 숨기면 아무 말이나 쓴다","mis":"SO5-1-u3-X13"},{"t":"남의 글을 출처 없이 옮긴다","mis":"SO5-1-u3-X13"}],"explanation":["비방은 명예 훼손이에요.","고운 말을 써요.","출처도 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#13','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C11',2,'mc','auto','친구가 싫어하는 별명을 부르지 않아야 하는 바탕이 되는 생각으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X14']::text[],false,'{"seq":13,"concept":"SO5-1-u3-C11","difficulty":2,"kind":"mc","stem":"친구가 싫어하는 별명을 부르지 않아야 하는 바탕이 되는 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"나의 권리가 소중한 만큼 다른 사람의 권리도 소중하기 때문에","correct":true},{"t":"힘이 센 사람의 권리가 더 크기 때문에","mis":"SO5-1-u3-X14"},{"t":"나이가 많을수록 권리가 크기 때문에","mis":"SO5-1-u3-X14"},{"t":"내 권리만 지키면 되기 때문에","mis":"SO5-1-u3-X14"}],"explanation":["모두의 권리예요.","나만큼 남도요.","그래서 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#14','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C12',2,'ox','auto','하윤이네 반 인권 탐사 일지 ⑤의 일들이 계속되면 생활에 불편함을 겪는 사람이 늘어날 수 있어요.',ARRAY['SO5-1-u3-X19']::text[],false,'{"seq":14,"concept":"SO5-1-u3-C12","difficulty":2,"kind":"ox","stem":"하윤이네 반 인권 탐사 일지 ⑤의 일들이 계속되면 생활에 불편함을 겪는 사람이 늘어날 수 있어요.","answer":"O","reason_options":[{"t":"인권이 침해되면 일상생활에서 어려움을 겪고 인간다운 삶을 누리지 못하기 때문에","correct":true},{"t":"침해는 저절로 사라지기 때문에","mis":"SO5-1-u3-X19"}],"mis":"SO5-1-u3-X19","explanation":["어려움이 이어져요.","불편한 사람이 늘어요.","그래서 O예요."],"asset":{"type":"passage","lines":["⑤ 동네 탐사 — 빵집 입구가 계단뿐이라 휠체어가 못 들어갔다.","공사장 소음이 밤늦게까지 이어져 이웃이 잠을 못 잔다.","이웃 아저씨는 다른 나라에서 왔다고 월급을 적게 받는다.","놀이터에서는 아이들이 차례를 지키며 서로 양보했다."],"title":"하윤이네 반 인권 탐사 일지 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#15','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C13',2,'error','auto','해결 방법 토의를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u3-X20','SO5-1-u3-X19']::text[],false,'{"seq":15,"concept":"SO5-1-u3-C13","difficulty":2,"kind":"error","stem":"해결 방법 토의를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"정민 — 「발표할 땐 방법만 말하면 되고 이유는 필요 없어.」","correct":true,"mis_target":"SO5-1-u3-X20"},{"t":"윤아 — 「원인을 먼저 정리해야 방법이 보여.」","mis":"SO5-1-u3-X19"},{"t":"세하 — 「각자 방법을 두 가지씩 찾아 쓰자.」","mis":"SO5-1-u3-X20"}],"explanation":["이유나 근거가 필요해요.","친구들이 판단해요.","정민이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#16','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C16',2,'sa','auto','학교 시설 네 갈래 가운데 안내판과 점자 블록이 드는 갈래는 「○○ 시설」이에요. ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"SO5-1-u3-C16","difficulty":2,"kind":"sa","stem":"학교 시설 네 갈래 가운데 안내판과 점자 블록이 드는 갈래는 「○○ 시설」이에요. ○○에 들어갈 두 글자를 쓰세요.","answer":["안내"],"explanation":["길과 장소를 알려 줘요.","안내판·점자 블록이에요.","안내 시설이에요."],"mis":"SO5-1-u3-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#17','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C6',3,'mc','auto','사진을 허락 없이 올린 일을 법이 해결하는 과정으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X07','SO5-1-u3-X09']::text[],false,'{"seq":17,"concept":"SO5-1-u3-C6","difficulty":3,"kind":"mc","stem":"사진을 허락 없이 올린 일을 법이 해결하는 과정으로 알맞은 것은 어느 것인가요?","options":[{"t":"피해자가 손해 배상을 청구하고 법원이 판결해 배상하게 한다","correct":true},{"t":"피해자가 똑같이 사진을 올려 갚는다","mis":"SO5-1-u3-X07"},{"t":"아무도 모르게 넘어간다","mis":"SO5-1-u3-X07"},{"t":"사진을 올린 사람이 혼자 정한다","mis":"SO5-1-u3-X09"}],"explanation":["청구를 해요.","법원이 판결해요.","배상을 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#18','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C9',3,'mc','auto','하윤이네 반이 인권 소책자를 만들려고 헌법을 찾아볼 때 알맞은 방법은 어느 것인가요?',ARRAY['SO5-1-u3-X26','SO5-1-u3-X06','SO5-1-u3-X11']::text[],false,'{"seq":18,"concept":"SO5-1-u3-C9","difficulty":3,"kind":"mc","stem":"하윤이네 반이 인권 소책자를 만들려고 헌법을 찾아볼 때 알맞은 방법은 어느 것인가요?","options":[{"t":"국가 법령 정보 누리집에서 헌법을 검색해 살펴본다","correct":true},{"t":"조항 번호만 외운다","mis":"SO5-1-u3-X26"},{"t":"친구 말만 듣는다","mis":"SO5-1-u3-X06"},{"t":"어른만 볼 수 있어 찾지 않는다","mis":"SO5-1-u3-X11"}],"explanation":["누리집에서 찾아요.","책과 어른께도 여쭤요.","직접 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#19','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C13',3,'ox','auto','인권 침해 문제를 해결하려면 침해당한 사람의 어려움에 공감하고 그 입장을 존중해야 해요.',ARRAY['SO5-1-u3-X19']::text[],false,'{"seq":19,"concept":"SO5-1-u3-C13","difficulty":3,"kind":"ox","stem":"인권 침해 문제를 해결하려면 침해당한 사람의 어려움에 공감하고 그 입장을 존중해야 해요.","answer":"O","reason_options":[{"t":"공감과 존중이 있어야 주변이 함께 해결에 나서기 때문에","correct":true},{"t":"침해당한 사람이 혼자 참으면 되기 때문에","mis":"SO5-1-u3-X19"}],"mis":"SO5-1-u3-X19","explanation":["공감해요.","존중해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#20','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C14',3,'mc','auto','국가 인권 위원회가 하는 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X22']::text[],false,'{"seq":20,"concept":"SO5-1-u3-C14","difficulty":3,"kind":"mc","stem":"국가 인권 위원회가 하는 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"학교 시험 문제를 낸다","correct":true},{"t":"인권 교육을 지원한다","mis":"SO5-1-u3-X22"},{"t":"인권 침해 사례를 조사한다","mis":"SO5-1-u3-X22"},{"t":"인권 보호 정책을 제안한다","mis":"SO5-1-u3-X22"}],"explanation":["인권을 살피는 기관이에요.","시험은 관계없어요.","첫째 보기가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#21','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C15',3,'mc','auto','인권 포스터를 만들 때 「인권은 우리의 빛」이라는 문구에 담을 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X23']::text[],false,'{"seq":21,"concept":"SO5-1-u3-C15","difficulty":3,"kind":"mc","stem":"인권 포스터를 만들 때 「인권은 우리의 빛」이라는 문구에 담을 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"태양이 없으면 살기 어렵듯 인권이 없으면 인간다운 삶을 살 수 없다","correct":true},{"t":"빛이 밝은 곳에서만 인권이 있다","mis":"SO5-1-u3-X23"},{"t":"밤에는 인권이 사라진다","mis":"SO5-1-u3-X23"},{"t":"빛과 인권은 관계없다","mis":"SO5-1-u3-X23"}],"explanation":["태양처럼 꼭 필요해요.","인간다운 삶이에요.","그 뜻을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#22','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C16',3,'mc','auto','다음 제안 가운데 세 칸이 모두 갖추어진 것은 어느 것인가요?',ARRAY['SO5-1-u3-X25']::text[],false,'{"seq":22,"concept":"SO5-1-u3-C16","difficulty":3,"kind":"mc","stem":"다음 제안 가운데 세 칸이 모두 갖추어진 것은 어느 것인가요?","options":[{"t":"화장실 출입문에 자동문을, 휠체어를 탄 사람이 쉽게 드나들도록","correct":true},{"t":"자동문을 설치합니다","mis":"SO5-1-u3-X25"},{"t":"화장실 출입문에","mis":"SO5-1-u3-X25"},{"t":"누구나 쉽게 드나들도록","mis":"SO5-1-u3-X25"}],"explanation":["어디에가 있어요.","무엇을이 있어요.","무엇을 위해도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#23','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C9',4,'mc','auto','하윤이네 반 인권 탐사 일지 ④와 ⑦을 함께 볼 때 헌법과 사회 보장 제도의 관계로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u3-X11','SO5-1-u3-X22']::text[],false,'{"seq":23,"concept":"SO5-1-u3-C9","difficulty":4,"kind":"mc","stem":"하윤이네 반 인권 탐사 일지 ④와 ⑦을 함께 볼 때 헌법과 사회 보장 제도의 관계로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"헌법이 보장하는 인간다운 삶을 국가가 제도로 실제 생활에서 지켜 준다","correct":true},{"t":"두 가지는 서로 관계가 없다","mis":"SO5-1-u3-X11"},{"t":"제도가 헌법보다 높은 법이다","mis":"SO5-1-u3-X11"},{"t":"헌법은 어려운 사람을 돕지 않는다","mis":"SO5-1-u3-X22"}],"explanation":["헌법이 인권을 보장해요.","제도가 실제로 도와요.","이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#24','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C10',4,'essay','teacher','친구 사진을 올리는 일과 횡단보도를 건너는 일에서 법을 지키는 행동을 하나씩 쓰고, 법을 지키는 까닭과 인권을 존중하는 까닭을 이어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u3-C10","difficulty":4,"kind":"essay","stem":"친구 사진을 올리는 일과 횡단보도를 건너는 일에서 법을 지키는 행동을 하나씩 쓰고, 법을 지키는 까닭과 인권을 존중하는 까닭을 이어 쓰세요.","answer_guide":{"answer":"예: 친구 사진은 올리기 전에 허락을 받고, 횡단보도는 파란불이 켜지면 건넌다. 법을 지키면 다른 사람에게 피해를 주지 않고 나와 다른 사람의 권리를 보호할 수 있다. 나의 권리가 소중한 만큼 다른 사람의 권리도 소중하므로 인권을 존중해야 한다.","scoring_points":["두 가지 법을 지키는 행동을 썼는가","법을 지키는 까닭을 썼는가","인권을 존중하는 까닭을 썼는가"]},"explanation":["허락과 신호예요.","피해를 주지 않아요.","나만큼 남도 소중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u3_review_d#25','soc',5,1,'u3','','g5_1_soc_u3_review_d','unit_review','SO5-1-u3-C16',4,'essay','teacher','하윤이네 반 인권 탐사 일지 ⑧처럼 우리 학교에 제안할 시설을 어디에·무엇을·무엇을 위해로 쓰고, 그 제안이 「장애물 없는 생활 환경 인증 제도」와 이어지는 까닭과 내가 생활에서 실천할 인권 보호 한 가지를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u3-C16","difficulty":4,"kind":"essay","stem":"하윤이네 반 인권 탐사 일지 ⑧처럼 우리 학교에 제안할 시설을 어디에·무엇을·무엇을 위해로 쓰고, 그 제안이 「장애물 없는 생활 환경 인증 제도」와 이어지는 까닭과 내가 생활에서 실천할 인권 보호 한 가지를 쓰세요.","answer_guide":{"answer":"예: 어디에 — 우리 학교 복도에, 무엇을 — 점자 블록을, 무엇을 위해 — 시각 장애가 있는 사람이 안전하게 다닐 수 있도록. 이 제도는 모든 사람이 시설을 불편 없이 쓰도록 하는 것이므로 이 제안과 이어진다. 나는 친구에게 인권을 존중하는 말을 쓰겠다.","scoring_points":["세 칸을 모두 썼는가","인증 제도와 이어 썼는가","생활 속 실천을 썼는가"]},"explanation":["세 칸을 채워요.","모든 사람을 위한 제도예요.","작은 실천을 써요."],"asset":{"type":"passage","lines":["⑧ 별빛초 제안 — 강당 무대는 계단뿐이라 휠체어로 오를 수 없다.","우리 모둠 제안: 강당 무대에 경사로와 안전 손잡이를","휠체어를 탄 친구도 무대에서 발표할 수 있도록.","실현된 모습을 그림으로 그려 학급에 게시했다."],"title":"하윤이네 반 인권 탐사 일지 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
